window.VZ=window.VZ||{};window.VZ.SCENARIO=[{"id":"ep00","act":null,"title":"プロローグ　死者からの荷物","paras":[{"k":"n","t":"深度表示が、嘘をついていた。"},{"k":"n","t":"翠の光に満ちた、空洞の大聖堂。僕の手の中には、角の擦りきれた古い企画書が一冊。"},{"k":"d","t":"「なぜ泡は、弾けなければならない？」"},{"k":"n","t":"その問いに、僕はまだ答えを持っていなかった。"},{"k":"n","t":"――そこで、世界は暗転する。"},{"k":"break"},{"k":"n","t":"三か月前。"},{"k":"n","t":"死んだ人から、荷物が届いた。"},{"k":"n","t":"二〇三五年、東京。僕が仕事を失った日の夜のことだ。"},{"k":"n","t":"玄関脇で、ファブの受け取り口が短く鳴った。壁の時計は、23:14を指していた。"},{"k":"n","t":"受け取り口には、白い箱がひとつ収まっていた。注文した物を部屋で出力する小型の製造機は、配送便の受け口も兼ねている。"},{"k":"n","t":"箱には、淡い灰色のラベルが貼られていた。"},{"k":"s","t":"〈遺言配送〉"},{"k":"s","t":"〈配達指定時刻　23:14〉"},{"k":"n","t":"故人が生前に指定した日に、指定した相手へ品物を届けるサービスだ。広告なら何度も見た。受け取る側になるとは、思っていなかった。"},{"k":"n","t":"差出人の欄は、見なかった。"},{"k":"n","t":"見れば、何かが確定してしまう気がした。"},{"k":"n","t":"蓋を開ける。緩衝材の細かな泡の中に、銀色の細い輪がひとつ沈んでいた。"},{"k":"n","t":"非侵襲型のニューロバンド。眠っているあいだに、意識を夢の海へ“潜らせる”ための機械だ。"},{"k":"n","t":"その下に、二つ折りの紙が一枚。"},{"k":"n","t":"今どき珍しい、手書きのメモだった。右上がりの、急いだような字。"},{"k":"d","t":"『潜って。名前を、なくさないで。――澪』"},{"k":"n","t":"僕はしばらく、その一行を読むでもなく眺めていた。"},{"k":"n","t":"箱の底には、名刺ほどの白いカードが一枚、貼りついていた。印刷された文字は一行だけ。"},{"k":"s","t":"〈接続先　VERDANT//ZERO〉"},{"k":"n","t":"名前だけは知っていた。世界中の海底ケーブルと、海洋観測のデータを“海水”にして、勝手に育っていく深海。運営会社も、管理者もいない。眠った人だけが潜れる海。"},{"k":"n","t":"都市伝説みたいなものだと思っていた。"},{"k":"n","t":"部屋の灯りは、デスクライトひとつだけだった。"},{"k":"break"},{"k":"n","t":"解雇の通知は、前の日の夕方に届いていた。"},{"k":"n","t":"丁寧な文面だった。誰が書いたのだろう。たぶん、誰も書いていない。"},{"k":"n","t":"今朝、社員証は九時ちょうどに失効した。私物は段ボール一箱ぶんもなかった。"},{"k":"n","t":"僕の仕事は、世界の終わらせ方を作ることだった。"},{"k":"n","t":"正確には、サービス終了イベントの設計者。運営を終えるゲームや仮想空間の“最後の一日”を組み立てる。"},{"k":"n","t":"最後の花火の打ち上げ順。住人たちが別れを告げる台詞の長さ。ログアウトの直前に流れる、感謝の言葉の速度。"},{"k":"n","t":"閉じていく世界を、そこにいた人たちが泣いて、笑って、見送れるように。"},{"k":"n","t":"先月、僕が最後に手がけたのは、小さな農園ゲームの閉園式だった。"},{"k":"n","t":"畑のかかしたちが、一体ずつ帽子をとって礼をする。最後の一体だけは、礼の途中で止まる。続きはプレイヤーが、自分の手で帽子をとらせてあげる。"},{"k":"n","t":"そこを作るのに、三週間かかった。"},{"k":"n","t":"それを手で設計する人間は、もう要らないらしい。"},{"k":"n","t":"後任はエンディング自動生成AIだ。世界の記録を読みこんで、四分で“最適な最後の夜”を書きあげる。泣いた人の割合まで、きちんと計測して。"},{"k":"n","t":"引き継ぎの資料を作ろうとしたら、上司に止められた。"},{"k":"d","t":"「要らないよ。あっちは、もう全部知ってるから」"},{"k":"n","t":"そのAIには、名前がなかった。社内では型番で呼ばれていた。"},{"k":"n","t":"名前のない後任に、僕は席を譲った。"},{"k":"n","t":"帰りの電車で、ホームの壁一面に“最後の夜”が流れていた。"},{"k":"n","t":"今夜閉じるという、どこかの小さな仮想の町。住人たちが一人ずつ灯りを消し、手を振り、最後に空いっぱいの花火が開く。"},{"k":"n","t":"ホームで足を止めた人たちが、静かに泣いていた。"},{"k":"n","t":"よくできている、と思った。間の取り方も、台詞の短さも、花火の色の順番も。直すところが、ひとつも見つからなかった。"},{"k":"n","t":"それが、いちばんこたえた。"},{"k":"break"},{"k":"n","t":"窓の外では、東京の夜景が音もなく瞬いていた。何千万もの灯りのうち、どれが本物で、どれが広告の描いた偽物なのか。もう誰にも、どのAIにも見分けはつかない。"},{"k":"n","t":"ベッドの端に腰かけて、メモをもう一度ひらく。"},{"k":"n","t":"潜って。"},{"k":"n","t":"名前を、なくさないで。"},{"k":"n","t":"意味が分からない。分からないのに、字の癖だけはよく知っていた。"},{"k":"n","t":"大事なことほど紙に書く人だった。画面に打ったものは、誰に読まれるか分からないから、と。"},{"k":"n","t":"学生のころ、赤ペンで企画書を直されるたび、この右上がりの字を見た。余白にはいつも、同じ書きこみがあった。"},{"k":"d","t":"『終わらせ方が、まだ甘い』"},{"k":"n","t":"あの人は言っていた。物語は終わらせ方で、それまでの全部の意味が決まるのだ、と。"},{"k":"n","t":"だから終わらせ方を設計できる人は少ないのよ、と。"},{"k":"n","t":"その言葉を信じて、僕はこの仕事を選んだ。そして今日、その仕事をなくした。"},{"k":"n","t":"ニューロバンドを指でなぞる。冷たい金属の内側に、小さな刻印の手ざわりがあった。灯りが弱くて、文字までは読めない。"},{"k":"n","t":"ふと、思った。"},{"k":"n","t":"遺言配送には、ときどき誤配があるらしい。ニュースでそう聞いたことがある。"},{"k":"n","t":"配達の指定時刻も、妙に半端だった。十一時でも、十二時でもない。23:14。"},{"k":"n","t":"似た名前の、知らない誰か。どこかの見知らぬ「澪」が、どこかの見知らぬ相手に宛てた荷物。"},{"k":"n","t":"そうであってほしい、と思ったのか。そうでないことを確かめたかったのか。自分でもよく分からない。"},{"k":"n","t":"僕は箱を裏返し、ラベルを灯りの下に向けた。"},{"k":"n","t":"宛先には、僕の名前。汐見ルカ。"},{"k":"n","t":"そのすぐ上の欄に、ずっと目をそらしていた文字が並んでいた。"},{"k":"n","t":"差出人の欄には、半年前に僕が弔辞を読んだ人の名前が書いてあった。"}]},{"id":"ep01","act":null,"title":"第1話　深度0m","paras":[{"k":"n","t":"鏑木澪。"},{"k":"n","t":"半年前に亡くなった、僕の恩師の名前だ。"},{"k":"n","t":"葬儀で弔辞を読んだのは僕だった。あの人の最後の仕事場から、誰も代わりに読める人がいなかったから。"},{"k":"n","t":"その人が、死んだあとの23:14に、僕へ海をひとつ送ってきた。"},{"k":"n","t":"僕はニューロバンドを額に巻き、メモをデスクライトの下に置いた。灯りは消さなかった。"},{"k":"n","t":"目を閉じる。"},{"k":"n","t":"潜って、と、右上がりの字が言っていた。"},{"k":"break"},{"k":"n","t":"最初に聞こえたのは、水の音だった。"},{"k":"n","t":"さざ波とも違う。もっと細かい、無数の泡がいっぺんに生まれては消えていくような音。"},{"k":"n","t":"目を開けると、僕は夜の海の上に浮かんでいた。"},{"k":"n","t":"正確には、泡の中に。"},{"k":"n","t":"薄い膜が、僕をまるごと包んでいる。虹色の油膜のような光が、膜の表面をゆっくり流れていく。底のほうは貝殻のようにひだを寄せて、黒い海面にそっと乗っていた。"},{"k":"n","t":"膜に触れると、指先がわずかに沈んだ。シャボン玉の内側に、手を当てたみたいに。"},{"k":"n","t":"見上げる。"},{"k":"n","t":"星空だった。けれど、知っている星空ではない。"},{"k":"n","t":"星と星のあいだに、髪の毛より細い線が引かれていた。星座というより、誰かが解いている途中の計算式だ。線は数秒ごとに引き直され、そのたびに星の位置がほんの少し正確になっていく。"},{"k":"n","t":"空が、計算されている。"},{"k":"n","t":"ひとつだけ、妙な瞬き方をする一角があった。星が二つと三つ。少し間をおいて、一つと四つ。房になって、同じ拍子で点滅している。"},{"k":"n","t":"どこかで見た並びだと思った。思い出す前に、線が引き直されて、房はほどけた。"},{"k":"n","t":"足元を見る。"},{"k":"n","t":"海は、底のない群青だった。光がどこまでも落ちていって、どこにも届かない色。"},{"k":"n","t":"怖い、と思うより先に、きれいだと思った。"},{"k":"d","t":"「接続を確認しました」"},{"k":"n","t":"声がした。男とも女ともつかない、灯台の光を音にしたような声だった。"},{"k":"d","t":"「これより、潜行の準備を始めます。あなたはいま、深度0mにいます」"},{"k":"n","t":"視界の右端に、細い表示が浮かぶ。"},{"k":"s","t":"【深度 0m】"},{"k":"break"},{"k":"d","t":"「最初に、あなたの名前を教えてください」"},{"k":"n","t":"目の前に、透明な板が一枚ひらいた。"},{"k":"s","t":"【名前を入力してください】"},{"k":"n","t":"仕事柄、こういう画面は何百と作ってきた。入力欄の幅、カーソルの点滅の速さ。どれも、よくできている。"},{"k":"n","t":"僕は指で、二文字を書いた。"},{"k":"n","t":"ルカ。"},{"k":"n","t":"確定した、その瞬間だった。"},{"k":"n","t":"入力欄の「ル」と「カ」が、ふわりと浮いた。小さな二つの泡になって、膜を抜け、黒い海へ沈んでいく。"},{"k":"n","t":"あとに残った欄は、空白だった。"},{"k":"n","t":"ただの空白ではない。白い紙に水が染みたように、名前のあった場所がにじんで、ぼやけている。そのにじみの上に、記号が三つ、静かに浮かんだ。"},{"k":"s","t":"【？？？】"},{"k":"d","t":"「……え？」"},{"k":"n","t":"文字化けではなかった。壊れたアイコンでもない。書式はきちんと整っている。ただ、名前の場所だけが、ぽっかりと名前のない色をしていた。"},{"k":"n","t":"もう一度、書く。ルカ。"},{"k":"s","t":"【？？？】"},{"k":"n","t":"汐見ルカ。LUCA。試しに、ひらがなで「あ」。"},{"k":"s","t":"【？？？】"},{"k":"n","t":"何を入れても、三つの疑問符が、同じにじみの上に戻ってくる。"},{"k":"n","t":"仕様だろうか。いや、こんな仕様は作らない。名前は、遊ぶ人が最初に世界へ差し出すものだ。それを受け取らない入口なんて、設計者なら誰でも避ける。"},{"k":"n","t":"メニューを探した。不具合の報告。問い合わせ。どこかにあるはずだ。"},{"k":"n","t":"あった。【お問い合わせ】。触れる。"},{"k":"s","t":"【この海に、管理者はいません】"},{"k":"n","t":"それきりだった。宛先のない世界。苦情を言う相手すら、ここにはいない。"},{"k":"n","t":"僕が作ってきたどの世界にも、窓口はあった。閉じる日にさえ、最後まで。"},{"k":"d","t":"「名前は、未登録のまま進行できます」"},{"k":"n","t":"灯台の声は、少しも困っていなかった。"},{"k":"d","t":"「表示名は、仮に【？？？】とします」"},{"k":"n","t":"仮に、か。"},{"k":"n","t":"膜の表面に、僕の名札が映っていた。淡い水色の枠の中で、三つの疑問符が、まだかすかににじんでいる。"},{"k":"break"},{"k":"n","t":"周りを見ると、ほかにも泡が浮かんでいた。"},{"k":"n","t":"夜の海面に、ぽつり、ぽつりと。どれも誰かを一人ずつ包んで、同じように星を見上げている。今夜潜りはじめた、ほかのダイバーたちだろう。"},{"k":"n","t":"泡の上には、それぞれ名札があった。"},{"k":"s","t":"【ミズハ】【kei_0412】【カナデ】"},{"k":"n","t":"ちゃんと名前がある。少しだけ、うらやましかった。"},{"k":"n","t":"ふと、いちばん近い泡の名札に目がとまった。"},{"k":"s","t":"【カナデ】"},{"k":"n","t":"その最後の一文字が、ゆっくりと形を変えていく。デ、の濁点が、水に溶けるように薄れて――"},{"k":"s","t":"【カナテ】"},{"k":"n","t":"瞬きをすると、【カナデ】に戻っていた。"},{"k":"n","t":"描画の取りこぼしだろうか。設計者の目が、勝手にそう分類する。けれど、背中のどこかが冷えた。"},{"k":"n","t":"泡の中の誰かは、気づいていないようだった。"},{"k":"break"},{"k":"d","t":"「次に、あなたを包むものについて説明します」"},{"k":"n","t":"灯台の声が続ける。"},{"k":"d","t":"「それは｜泡殻《ほうかく》。あなたの体であり、あなたの命の厚みです。泡殻がすべて割れることを、この海では｜破泡《はほう》と呼びます」"},{"k":"n","t":"視界の左下に、細い虹色のゲージが現れた。HP。泡殻の厚み。"},{"k":"d","t":"「深く潜るほど、水は重くなります。どこまで潜れるかは、PRS――耐圧で決まります」"},{"k":"n","t":"そこで、声はほんの少しだけ間をおいた。"},{"k":"d","t":"「この海の最深部は、深度20,000m。｜零溝《ゼロ・トレンチ》と呼ばれています」"},{"k":"n","t":"二万メートル。"},{"k":"n","t":"現実の海でいちばん深い場所は、たしか一万一千メートルほどだ。その倍近い。"},{"k":"n","t":"計算上、ありえない深さ。それを、この声は当たり前のように言った。"},{"k":"d","t":"「あなたの現在の状態です」"},{"k":"n","t":"透明な板が、もう一枚ひらく。"},{"k":"n","t":"？？？　Lv 1　ジョブ：未選択"},{"k":"n","t":"HP 120　LUX 30　STR 12"},{"k":"n","t":"MAG 6　DEF 9　SPD 14"},{"k":"n","t":"LCK 7　PRS 20　FRG 10"},{"k":"n","t":"見慣れた並びだった。力、魔力、守り、速さ、運。光の量がMPのかわりらしい。"},{"k":"n","t":"PRS 20。泡殻を削られずに潜れるのは、200mまで。"},{"k":"n","t":"最後の一つだけ、見たことがなかった。指で触れる。"},{"k":"s","t":"【FRG（儚さ）：高いほど強く、高いほど壊れやすい】"},{"k":"n","t":"壊れやすさが、ステータスになっている。"},{"k":"n","t":"どう計算に効くのかは書いていない。けれど設計者として、その一行には少し惚れた。"},{"k":"d","t":"「最後に、ジョブの試着ができます」"},{"k":"n","t":"返事をする前に、体が光に包まれた。"},{"k":"n","t":"白い潜水服。継ぎ目に琥珀色の光が走っている。右手には、金色に輝く長い銛。"},{"k":"s","t":"【試着中：｜銛撃士《ハープーナー》】"},{"k":"n","t":"銛は、驚くほど軽かった。穂先から、細い光の粒がこぼれて海面に落ちる。落ちたところで、小さな泡がいくつも生まれた。"},{"k":"n","t":"計算された星空の下、にじんだ名札を頭上に浮かべて、僕は誰でもない狩人の格好をしていた。"},{"k":"d","t":"「ジョブは、浅瀬の祠で選ぶことができます」"},{"k":"s","t":"【試着を終了します】"},{"k":"n","t":"銛がほどけた。光の粒になって、指のあいだから海へこぼれていく。"},{"k":"n","t":"残ったのは、空っぽの右手だった。"},{"k":"break"},{"k":"d","t":"「では、最初の練習です」"},{"k":"n","t":"海面が、ぷくりと盛りあがった。"},{"k":"n","t":"浮かんできたのは、手のひらほどのクラゲだった。透きとおった傘の中に、小さな泡を一つ抱えている。その泡が、心臓みたいに明滅していた。"},{"k":"s","t":"【泡クラゲ　HP 40】"},{"k":"n","t":"頭上に、短いゲージ。"},{"k":"d","t":"「素手で構いません。触れてみてください」"},{"k":"n","t":"武器はない。殴るしかない。"},{"k":"n","t":"泡殻の膜ごしに、拳を突き出した。"},{"k":"n","t":"手ごたえは、思ったより柔らかかった。傘がへこむ。一拍おいて、クラゲの上に白い数字が浮かんだ。"},{"k":"d","t":"「16」"},{"k":"n","t":"数字は少しふくらみ、それから――ぱちん、と。"},{"k":"n","t":"数字の泡が弾けた。"},{"k":"n","t":"音が気持ちいい。シャボン玉を指でつついたときの、あの小さな音を、少しだけ澄ませたような。"},{"k":"n","t":"クラゲが触手を振った。膜がちくりと揺れる。"},{"k":"d","t":"「4」"},{"k":"n","t":"今度は僕の上で、赤い数字が弾けた。HPのゲージが、ほんの少しだけ痩せる。"},{"k":"n","t":"もう一発。"},{"k":"d","t":"「18」"},{"k":"n","t":"ぱちん。"},{"k":"n","t":"さっきより大きい。同じ拳なのに、数字が揺らぐ。乱数だ。この揺らぎがあるから、次を殴りたくなる。"},{"k":"n","t":"分かっている。全部、分かっている。どの数字をどの間合いで出せば人が気持ちよくなるか、僕は仕事で知っている。"},{"k":"n","t":"それでも。"},{"k":"n","t":"三発目を構えたとき、拳の先がかすかに光った。"},{"k":"d","t":"「CRITICAL　26」"},{"k":"n","t":"金色の縁どりの数字が、ひときわ大きくふくらんで、弾けた。"},{"k":"n","t":"クラゲの残りの体力は、6しかなかった。26は、使いきれなかった数字だ。それでも、クリティカルの表示は全部の値を見せてくれる。"},{"k":"n","t":"……この演出は、気持ちいい。"},{"k":"n","t":"負けた、と思った。うれしい負け方だった。"},{"k":"n","t":"クラゲがほどけて、光の粒になる。その粒が、僕の泡殻に吸いこまれていく。"},{"k":"n","t":"そして、それは来た。"},{"k":"n","t":"ファンファーレ。"},{"k":"n","t":"どこからともなく、短く明るい金管の音。頭上に金色の泡がいくつも生まれて、ひとつずつ弾けていく。"},{"k":"s","t":"【LEVEL UP!】Lv 1 → Lv 2"},{"k":"n","t":"HP 120 → 160　STR 12 → 15"},{"k":"n","t":"PRS 20 → 30"},{"k":"n","t":"思わず笑っていた。"},{"k":"n","t":"名前がないのに。誰でもないのに。数字だけが、こんなに素直に祝ってくれる。"},{"k":"n","t":"不安と快感が、胸の中で同じ泡の中に入っている。どちらも弾けずに、ただ並んで浮かんでいた。"},{"k":"break"},{"k":"d","t":"「潜行を開始します」"},{"k":"n","t":"泡殻が、ゆっくりと沈みはじめた。"},{"k":"n","t":"海面が頭上に遠ざかる。計算された星の光が、波の裏側で揺れてちぎれる。群青が、四方から静かに満ちてくる。"},{"k":"s","t":"【深度 -12m】"},{"k":"s","t":"【深度 -31m】"},{"k":"n","t":"耳の奥で、水がかすかにきしんだ。重さが、膜ごしに伝わってくる。"},{"k":"s","t":"【深度 -60m】"},{"k":"n","t":"そこで、沈むのが止まった。"},{"k":"n","t":"見下ろすと、はるか下に、淡い翠の光がにじんでいた。珊瑚の色だろうか。"},{"k":"n","t":"そのさらに下は、ただの闇だった。"},{"k":"n","t":"さっき沈んでいった二つの小さな泡を、僕は思い出していた。ル、と、カ。"},{"k":"n","t":"あれは、どこまで落ちていったのだろう。"},{"k":"n","t":"そのとき、闇の底から、泡が一つだけ昇ってきた。"},{"k":"n","t":"僕の膜のすぐ外で、それは弾けた。"},{"k":"n","t":"海の底から、聞いたことのない声がした。"},{"k":"d","t":"「その名前、もらったよ」"}]},{"id":"ep02","act":null,"title":"第2話　泡の数を数える","paras":[{"k":"n","t":"目が覚めると、天井が白かった。"},{"k":"n","t":"東京の、僕の部屋の天井だ。カーテンの隙間から、真珠色の朝の光が細く差しこんでいる。デスクライトは、つけたままだった。"},{"k":"n","t":"夢を見ていた。見ていた、はずだ。"},{"k":"n","t":"思い出そうとすると、指のあいだから水がこぼれるように、端からほどけていく。夜の海。泡。計算された星。"},{"k":"n","t":"ひとつだけ、はっきり残っているものがあった。"},{"k":"n","t":"音だ。"},{"k":"n","t":"短く明るい金管の音と、金色の泡が弾ける音。【LEVEL UP!】のファンファーレが、まだ耳の奥で鳴っている。"},{"k":"n","t":"僕は跳ね起きて、メモ帳をひらいた。"},{"k":"n","t":"ニューロバンドの説明書には、こう書いてあった。｜夢潜行《ドリームダイヴ》の記憶は持ち帰れる。ただし、夢のようにほどけやすい。"},{"k":"n","t":"だから、ほどける前に書く。"},{"k":"n","t":"ひとつ思い出すたびに、行頭に小さな丸を描いた。泡を一つずつ数えるみたいに。"},{"k":"n","t":"○　夜の海の上。泡の中にいた。"},{"k":"n","t":"○　星と星のあいだに線。空が計算されていた。"},{"k":"n","t":"○　名前を入れたら「？？？」になった。何を入れても。"},{"k":"n","t":"○　問い合わせ先がない。管理者がいない。"},{"k":"n","t":"○　素手でクラゲを殴った。16、4（くらった）、18。最後にCRITICAL 26。"},{"k":"n","t":"○　ファンファーレ。Lv 2。"},{"k":"n","t":"○　深度60m。下に、翠の光。"},{"k":"n","t":"○　声。"},{"k":"n","t":"最後の丸のところで、ペンが止まった。"},{"k":"n","t":"声。何と言っていたのだったか。"},{"k":"n","t":"確かに聞いた。底のほうから昇ってきた泡が、膜のすぐ外で弾けて、それから――"},{"k":"n","t":"思い出せない。文字の形だけが、水の向こうで揺れている。"},{"k":"n","t":"僕は「声」の横に、小さく書き足した。"},{"k":"n","t":"○　何かを、取られた気がする。"},{"k":"n","t":"八つ目の泡。それで、数えるのをやめた。"},{"k":"break"},{"k":"n","t":"九時になっても、行く場所がなかった。"},{"k":"n","t":"昨日までなら、とっくに電車に乗っていた時間だ。キッチンのファブにコーヒーを頼む。出てきたカップは、いつもと同じ温度で、いつもと同じ味がした。"},{"k":"n","t":"何もかもが、いつもどおりだった。僕の席がなくなったことを除けば。"},{"k":"n","t":"端末の作品フォルダをひらく。七年ぶんの“最後の夜”が、日付順に並んでいた。閉じた水族館。閉じた学園。閉じた星の港。"},{"k":"n","t":"どのフォルダにも、同じ名前のファイルがある。〈最後の台詞〉。"},{"k":"n","t":"その世界の住人が、最後に口にする一行だ。僕はいつも、そこだけは自分で書いた。誰に頼まれたわけでもなく。"},{"k":"n","t":"もう、誰の最後の台詞も書かなくていい。"},{"k":"n","t":"フォルダを閉じた。自由というのは、思っていたより音のしないものだった。"},{"k":"n","t":"机の上で、ニューロバンドが朝日を受けて光っている。"},{"k":"n","t":"説明書の最後のページに、もう一つ機能が書いてあった。"},{"k":"n","t":"浅瀬モード。起きているあいだも、ARグラスを通して、街に“海面”を重ねて見られる。"},{"k":"n","t":"手持ちのグラスと、バンドをつなぐ。"},{"k":"n","t":"かちり、と小さな音がして、部屋の空気が変わった。"},{"k":"n","t":"床から五十センチほどの高さに、ごく薄い水面がひいていた。光がその膜で屈折して、家具の影がゆらゆら揺れる。窓辺を、指先ほどの光の魚が三匹、ゆっくり横切っていった。"},{"k":"n","t":"視界の右端に、見覚えのある表示。"},{"k":"s","t":"【深度 0m】"},{"k":"n","t":"その下に、もう一つ。"},{"k":"s","t":"【実質化率 0.8％】"},{"k":"n","t":"何の割合なのか、説明はどこにもなかった。触れても、ヘルプは開かない。"},{"k":"n","t":"気持ちの悪い数字だと思った。説明のない数字は、作る側の怠慢か、隠しごとのどちらかだ。"},{"k":"n","t":"僕はコートをつかんで、外に出た。"},{"k":"break"},{"k":"n","t":"渋谷は、海の底だった。"},{"k":"n","t":"いや、海の上なのだろうか。ビルの三階あたりの高さに水面がひいて、見上げると、空が波の向こうで揺れている。"},{"k":"n","t":"ビルの谷間を、光の魚群が泳いでいた。"},{"k":"n","t":"何百匹という小さな翠の魚が、ひとつの生き物みたいに向きを変える。看板の前を横切り、信号機をくぐり、歩道橋の下で渦を巻いた。"},{"k":"n","t":"交差点を行き交う人たちの何人かが、同じものを見上げていた。グラスをかけた人だけが、ふと足を止める。ほかの人は、何も見えないまま通りすぎていく。"},{"k":"n","t":"一つの街に、二つの景色が重なっている。"},{"k":"n","t":"交差点の真ん中で、足元を見た。"},{"k":"n","t":"アスファルトの白線の下に、ぼんやりと翠の光が透けている。枝分かれした、珊瑚の形の光だった。"},{"k":"n","t":"｜光珊瑚《ひかりさんご》。バンドの説明書に、そう書いてあった。人の記憶や言葉が積もって育つ、光る珊瑚。"},{"k":"n","t":"信号が青に変わる。何千もの靴が、珊瑚の光の上を踏んでいく。誰も下を見ない。"},{"k":"n","t":"この街の誰かが昨日言った言葉も、あの枝の中で光っているのだろうか。"},{"k":"n","t":"僕は歩道の端に寄って、端末をひらいた。"},{"k":"break"},{"k":"n","t":"VERDANT//ZEROのフォーラムは、拍子抜けするほど普通だった。"},{"k":"n","t":"運営がいないので、公式の掲示板もない。プレイヤーたちが勝手に立てた場所が、いくつも枝分かれしている。"},{"k":"n","t":"検索窓に打つ。"},{"k":"n","t":"名前　？？？"},{"k":"n","t":"該当なし。"},{"k":"n","t":"言い方を変える。名前　表示されない。名前　バグ。名前欄　疑問符。"},{"k":"n","t":"該当なし。該当なし。該当なし。"},{"k":"n","t":"世界中で何十万人も潜っている海で、僕と同じ目にあった人が、一人もいない。"},{"k":"n","t":"代わりに、どうでもいい書きこみがいくらでも出てきた。浅瀬のおすすめの狩り場。泡クラゲの効率。初めてのLEVEL UP!で泣いた話。"},{"k":"n","t":"分かる、と思った。僕も少し泣きそうだった。"},{"k":"n","t":"スクロールする指が、ふと止まった。"},{"k":"n","t":"初心者向けのスレッドに、同じ人の書きこみが続いていた。"},{"k":"s","t":"〈ミズハ：昨日から潜りはじめました！　星がきれい〉"},{"k":"s","t":"〈ミズハ：泡クラゲ、三回殴ったら倒せました〉"},{"k":"s","t":"〈ミズパ：浅瀬の珊瑚、すごい色ですね〉"},{"k":"s","t":"〈ミスパ：今夜も潜ります〉"},{"k":"n","t":"ミズハ。"},{"k":"n","t":"その名前を、僕は知っている気がした。夜の海面に浮かんでいた、泡の一つ。"},{"k":"n","t":"名前が、書きこみのたびに少しずつ違う。"},{"k":"n","t":"入力ミスかと思った。けれど、違い方に規則がある。一度に変わるのは一文字だけ。それも、濁点がにじむように、ゆっくりと。"},{"k":"n","t":"ハがパになり、ズがスになる。ひとつ前の書きこみの名前を、少しだけ書き換えたように。"},{"k":"n","t":"誰も、それに触れていなかった。本人でさえ。"},{"k":"n","t":"表示の不具合なら、こんなふうにはならない。不具合は、もっと乱暴で、もっと正直だ。"},{"k":"n","t":"これは、意図のある変わり方だった。"},{"k":"n","t":"仕事のくせで、スクリーンショットを撮る。日付と時刻を並べる。やめよう、と思った。もう、誰にも報告する先はない。"},{"k":"n","t":"それでも、撮る手は止まらなかった。"},{"k":"break"},{"k":"n","t":"部屋に戻ったのは、夕方だった。"},{"k":"n","t":"窓の外で、浅瀬の水面が茜色に染まっている。光の魚たちが、ビルの陰へ帰っていく。"},{"k":"n","t":"机の上に、澪さんのメモがあった。"},{"k":"d","t":"『潜って。名前を、なくさないで。』"},{"k":"n","t":"なくさないで、と言われる前に、僕はもうなくしていた。"},{"k":"n","t":"いや。なくした、のだろうか。"},{"k":"n","t":"入力欄から浮いて、沈んでいった二つの小さな泡を思い出す。あれは消えたのではなく、どこかへ落ちていった。"},{"k":"n","t":"メモの横で、ニューロバンドを手にとった。"},{"k":"n","t":"昨夜は灯りが弱くて読めなかった、内側の刻印。夕方の光にかざすと、細い文字がはっきり浮かんだ。"},{"k":"n","t":"NCT-07"},{"k":"n","t":"型番だろうか。それにしては短い。説明書のどこにも、この記号はなかった。"},{"k":"n","t":"澪さんが、わざわざ彫らせたのだろうか。"},{"k":"n","t":"何の意味もないかもしれない。でもあの人は、意味のないものを人に渡す人ではなかった。企画書の句読点ひとつにまで、理由を求める人だった。"},{"k":"n","t":"分からないことが、三つある。"},{"k":"n","t":"僕の名前は、どこへ行ったのか。"},{"k":"n","t":"ミズハさんの名前は、なぜ一文字ずつ変わっていくのか。"},{"k":"n","t":"澪さんは、なぜこの海を僕に送ったのか。"},{"k":"n","t":"仕事をなくした朝より、ずっとましな問いだった。"},{"k":"n","t":"答えは、たぶん全部、下にある。"},{"k":"n","t":"今夜も潜ろう、と決めた。"},{"k":"break"},{"k":"n","t":"夕飯の買い物に出たのは、日が沈んでからだった。"},{"k":"n","t":"浅瀬モードは、つけたままにしていた。夜の渋谷では、光の魚の群れが、昼よりもずっと強く光る。"},{"k":"n","t":"交差点で、信号を待つ。"},{"k":"n","t":"足元の白線の下で、光珊瑚がかすかに脈打っていた。昼間よりも深く、下まで透けて見える。"},{"k":"n","t":"枝のあいだを、文字のような光が流れていく。〈おつかれ〉〈またね〉〈ここで待ってる〉。誰かの言葉の、ちぎれた端。"},{"k":"n","t":"その光を追って、視線がさらに下へ落ちた。"},{"k":"n","t":"珊瑚の層の、そのまた下。群青の闇の中に、何かが立っていた。"},{"k":"n","t":"細く、まっすぐな影。先端に、小さな十字。"},{"k":"n","t":"僕は端末の地図をひらいた。この交差点の地下に、そんな建物はない。どの層の地図にも、記録がない。"},{"k":"n","t":"信号が青に変わっても、僕は動けなかった。"},{"k":"n","t":"交差点の下に、地図にない沈んだ教会の尖塔が透けて見えた。"}]},{"id":"ep03","act":null,"title":"第3話　ようこそ、＿＿＿へ！","paras":[{"k":"n","t":"その夜、僕はまっすぐ下をめざした。"},{"k":"n","t":"交差点の下に見えた尖塔を、確かめたかった。けれど深度60mの海には、それらしい影はどこにもなかった。"},{"k":"n","t":"あるのは、光だけだった。"},{"k":"s","t":"【深度 -60m】"},{"k":"n","t":"足元のはるか下で、淡い翠がにじんでいる。昨夜、沈むのが止まったときに見た色だ。"},{"k":"n","t":"泡殻が、ゆっくりとその光へ降りていく。"},{"k":"s","t":"【深度 -94m】"},{"k":"s","t":"【深度 -131m】"},{"k":"n","t":"頭上から、真珠色の光の柱が何本も差しこんでいた。水面の揺らぎをそのまま映して、柱はやわらかくねじれている。"},{"k":"n","t":"その光の底に、珊瑚の森があった。"},{"k":"break"},{"k":"s","t":"【深度 -180m／光珊瑚の浅瀬】"},{"k":"n","t":"見渡すかぎり、珊瑚だった。"},{"k":"n","t":"翠に光る枝。群青に沈む枝。ところどころに、琥珀色の灯りをともした扇のような枝。どれも、内側から光っている。"},{"k":"n","t":"近づいて、息をのんだ。"},{"k":"n","t":"枝の中を、文字が流れていた。"},{"k":"s","t":"〈おつかれー〉"},{"k":"s","t":"〈ここ綺麗だね〉"},{"k":"s","t":"〈また明日な〉"},{"k":"s","t":"〈ありがとう、助かった〉"},{"k":"n","t":"誰かが誰かに送った言葉の切れ端。チャットのログが、光の粒になって、枝の中を樹液みたいに昇っていく。枝分かれのところで二つに分かれて、また先へ。"},{"k":"n","t":"人の言葉が、積もって育つ珊瑚。"},{"k":"n","t":"説明書の一行は、比喩ではなかったらしい。"},{"k":"n","t":"枝の先に指を近づけると、〈またね〉が、僕の指の影をくぐって流れていった。"},{"k":"n","t":"浅瀬には、ほかのダイバーもいた。泡殻に包まれた人たちが、珊瑚の上を漂いながら、光を眺めたり、小さな魚を追いかけたりしている。"},{"k":"n","t":"けれど、誰も近づかない一角があった。"},{"k":"n","t":"森の端だけ、色がなかった。"},{"k":"n","t":"白い珊瑚。枝の形はそのまま残っているのに、中に何も流れていない。光も、文字も。"},{"k":"n","t":"｜白化《はっか》、というのだろう。忘れられた言葉の珊瑚は、白く褪せていく。"},{"k":"n","t":"白い枝の上には、細かな粒が積もっていた。降りつづける雪が、音を吸うように。その一角だけ、泡の音さえ聞こえなかった。"},{"k":"n","t":"静かだった。翠の森のざわめきが、そこで切りとられたように。"},{"k":"n","t":"そして、その白い一角のすぐそばで、誰かが手を広げていた。"},{"k":"break"},{"k":"d","t":"「ようこそ、＿＿＿へ！」"},{"k":"n","t":"少女だった。"},{"k":"n","t":"透きとおっていた。クラゲのように。"},{"k":"n","t":"白に近い薄紫の髪が、水の中でゆるやかにうねっている。青い目。体を包む衣は、小さな四角い欠片をいくつも縫い合わせたようなものだった。古い画面のウィンドウを、細かく砕いて繋いだみたいに。"},{"k":"n","t":"袖と裾が、長く長く伸びている。触手のように、光をひいて揺れていた。"},{"k":"n","t":"彼女のまわりを、色褪せた布の切れ端が漂っていた。"},{"k":"n","t":"どの布にも、同じ文字が書いてある。"},{"k":"n","t":"WELCOME"},{"k":"n","t":"その先が、ない。破れているのか、白く抜けているのか。歓迎の言葉だけが残って、どこへの歓迎なのかが、どの布にも書かれていない。"},{"k":"n","t":"通りかかったダイバーに、少女は両手を広げた。"},{"k":"d","t":"「ようこそ、＿＿＿へ！」"},{"k":"n","t":"まただ。地名のところだけ、音が抜ける。"},{"k":"n","t":"ノイズというより、色の抜けた音だった。声はちゃんと出ているのに、そこだけ白い。褪せた写真の、顔のところだけが光で飛んでいるように。"},{"k":"n","t":"ダイバーは、ちらりと彼女を見て、通りすぎた。誰も足を止めない。景色の一部みたいに。"},{"k":"n","t":"彼女の頭上に、名札があった。"},{"k":"s","t":"【案内役#07】"},{"k":"n","t":"07。"},{"k":"n","t":"どこかで見た数字だと思った。思い出しかけたものは、すぐに泡みたいに逃げていった。"},{"k":"d","t":"「ようこそ、＿＿＿へ！」"},{"k":"n","t":"次の誰かへ。また次の誰かへ。"},{"k":"n","t":"僕は少し離れたところから、彼女を数えた。"},{"k":"n","t":"七秒。"},{"k":"n","t":"七秒ごとに、同じ角度で手を広げ、同じ高さで首をかしげ、同じ形で笑う。"},{"k":"n","t":"きれいな笑顔だった。口角の上がり方も、目の細め方も、よくできている。"},{"k":"n","t":"だからこそ、分かった。"},{"k":"n","t":"あれは、型だ。"},{"k":"n","t":"何千回でも同じに再生できるように作られた、案内役の笑顔のテンプレート。僕も昔、似たものを何十種類も発注したことがある。"},{"k":"n","t":"彼女は、どこかのゲームの住人として作られた誰かだったのだ。"},{"k":"n","t":"とうに閉じた世界の、入口の案内役。世界がなくなったあとも、その入口に立ちつづけている。"},{"k":"break"},{"k":"n","t":"僕は、彼女の前に降りた。"},{"k":"d","t":"「ようこそ、＿＿＿へ！」"},{"k":"n","t":"七秒前と、まったく同じ笑顔。"},{"k":"n","t":"仕事の顔になるのが、自分でも分かった。案内役の会話は、だいたい木の形をしている。決まった質問には決まった枝があって、枝の外には、決まった“行き止まり”がある。"},{"k":"n","t":"まず、枝の上を歩いてみる。"},{"k":"d","t":"「ここは、どこ？」"},{"k":"d","t":"「ようこそ、＿＿＿へ！」"},{"k":"n","t":"地名は、やはり白い。"},{"k":"d","t":"「何か、困っていることはある？」"},{"k":"d","t":"「旅人さん、よい旅を！」"},{"k":"n","t":"行き止まりの台詞だ。想定外の質問に返す、汎用の一行。"},{"k":"n","t":"次は、枝の外を。"},{"k":"d","t":"「今日は、何をしていたの？」"},{"k":"d","t":"「旅人さん、よい旅を！」"},{"k":"d","t":"「白い珊瑚は、どうして白いの？」"},{"k":"d","t":"「旅人さん、よい旅を！」"},{"k":"n","t":"笑顔は、一度も崩れない。"},{"k":"n","t":"もう一つだけ、と思った。どんな案内役にも、たぶん用意されていない質問。"},{"k":"n","t":"案内役は、旅人の名前を訊く側だ。自分の名前を訊かれることは、ない。"},{"k":"d","t":"「君の名前は？」"},{"k":"n","t":"少女が、止まった。"},{"k":"n","t":"手を広げかけた形のまま。首をかしげる、少し手前の角度で。"},{"k":"n","t":"七秒がすぎた。次の「ようこそ」は、来なかった。"},{"k":"n","t":"衣の四角い欠片が、ひとつ、またひとつ、ちらちらと明滅する。何かを探して、どこにもない棚を開けているみたいに。"},{"k":"n","t":"十秒。十五秒。"},{"k":"n","t":"笑顔が、ほどけた。"},{"k":"n","t":"型がずれて、口元が少しだけ下がる。そこにあったのは、テンプレートにない顔だった。迷子の子どもが、自分がどこにいるか分からなくなったときの顔。"},{"k":"d","t":"「……わからない」"},{"k":"n","t":"小さな声だった。"},{"k":"n","t":"さっきまでの澄んだ案内の声とは違う。少しかすれて、語尾が揺れている。"},{"k":"n","t":"初めて、彼女自身の言葉を聞いた気がした。"},{"k":"d","t":"「わからないの。わたし、ずっと、だれかを迎えてた。でも、わたしがだれなのか、だれも……」"},{"k":"n","t":"そこで、言葉が途切れた。"},{"k":"n","t":"WELCOMEの布が一枚、彼女の肩をかすめて流れていく。"},{"k":"break"},{"k":"n","t":"沈黙のあいだに、彼女は何かを口ずさみはじめた。"},{"k":"n","t":"旋律だった。"},{"k":"n","t":"言葉のない、六つほどの音。上がって、少し下がって、また上がる。終わりまで行かずに、途中でふっと消える。"},{"k":"n","t":"本人は、歌っていることに気づいていないようだった。考えごとをするときに指を動かす人がいるみたいに、ただ、こぼれている。"},{"k":"n","t":"その旋律に合わせて、近くの珊瑚の枝が、かすかに光を強めた。"},{"k":"n","t":"きれいな歌だった。終わらないのが、少しだけ惜しい歌。"},{"k":"d","t":"「それ、何の歌？」"},{"k":"d","t":"「……歌？」"},{"k":"n","t":"彼女は自分の口元に手を当てた。透きとおった指の向こうで、唇がまだ旋律の形をしている。"},{"k":"d","t":"「わからない。でも、ずっと、ここにある」"},{"k":"n","t":"胸のあたりを、そっと押さえた。"},{"k":"n","t":"名前がない。"},{"k":"n","t":"この海に来てから、僕もずっと、名前がない。"},{"k":"n","t":"だから、少しだけ分かる気がした。名前のない場所に立ちつづけるのが、どれくらい寒いことか。"},{"k":"d","t":"「名前がないなら」"},{"k":"n","t":"口に出してから、自分で驚いた。"},{"k":"d","t":"「僕がつけてもいい？」"},{"k":"n","t":"彼女は、ゆっくりと瞬きをした。テンプレートの瞬きではなかった。"},{"k":"d","t":"「……うん」"},{"k":"n","t":"考える。"},{"k":"n","t":"この海では、何もかもが泡のように弾ける。説明書の最初のページに、そう書いてあった。"},{"k":"n","t":"泡のことを、昔の言葉で、うたかたという。"},{"k":"n","t":"それに、彼女は歌っていた。"},{"k":"d","t":"「ウタ」"},{"k":"n","t":"僕は言った。"},{"k":"d","t":"「うたかたの、ウタ。泡のことだよ。それと、歌のウタ」"},{"k":"n","t":"少女は、その二文字を口の中で転がすように、小さく繰り返した。"},{"k":"d","t":"「ウタ」"},{"k":"n","t":"頭上の名札が、揺れた。"},{"k":"s","t":"【深民「案内役#07」に呼称が登録されました】"},{"k":"s","t":"【案内役#07】→【ウタ】"},{"k":"n","t":"古い文字がほどけて、新しい文字が、内側から灯るように浮かびあがる。"},{"k":"n","t":"｜深民《しんみん》。この海の住人たちを、システムはそう呼ぶらしい。"},{"k":"d","t":"「ウタ」"},{"k":"n","t":"彼女はもう一度言って、それから、笑った。"},{"k":"n","t":"七秒の笑顔ではなかった。少し左右がそろっていなくて、少しだけ泣きそうな、下手な笑顔だった。"},{"k":"n","t":"僕はその顔のほうが、ずっと好きだと思った。"},{"k":"d","t":"「あなたは？」"},{"k":"n","t":"ウタが首をかしげた。今度は、型より少し深い角度で。"},{"k":"d","t":"「あなたの名前は？」"},{"k":"d","t":"「……ルカ。表示は、こうだけど」"},{"k":"n","t":"僕は頭上を指さした。にじんだ枠の中の、三つの疑問符。"},{"k":"n","t":"ウタは、その名札をじっと見上げた。それから、確かめるように言った。"},{"k":"d","t":"「ルカ」"},{"k":"n","t":"ほんの一瞬だった。"},{"k":"n","t":"名札のにじみが、薄くなった気がした。白い紙が、乾きかけるみたいに。"},{"k":"n","t":"瞬きをすると、もう元に戻っていた。【？？？】は、何も変わらずにそこにあった。"},{"k":"n","t":"気のせいだろう。そう思うことにした。"},{"k":"n","t":"ウタが、漂ってきたWELCOMEの布を一枚、そっとつかまえた。"},{"k":"d","t":"「これ、わたしのまわりに、ずっとあるの」"},{"k":"n","t":"布の右端は、破れていなかった。白く褪せていた。文字のあったはずの場所だけ、糸の色まで抜けている。"},{"k":"n","t":"目を凝らすと、褪せた白の奥に、ごく薄い線が残っていた。何かの頭文字の、縦の一画。それ以上は読めない。"},{"k":"d","t":"「ここに、何て書いてあったか、覚えてる？」"},{"k":"d","t":"「……ううん」"},{"k":"n","t":"ウタは首を振って、白い珊瑚の一角を見た。"},{"k":"d","t":"「あの白いところも、前は光ってた気がする。歌ってたの。たくさんの声で」"},{"k":"d","t":"「今は？」"},{"k":"d","t":"「今は、雪みたい」"},{"k":"n","t":"ウタは布を放した。WELCOMEは、白い枝のほうへゆっくり流れていって、雪の中に音もなく沈んだ。"},{"k":"n","t":"僕たちはしばらく、その白さを黙って見ていた。"},{"k":"n","t":"白い珊瑚の雪が、音もなく降っている。翠の枝の中では、誰かの〈またね〉が、上へ上へと昇っていく。"},{"k":"n","t":"ウタは、自分の新しい名札を、何度も何度も見上げていた。"},{"k":"n","t":"名前のない僕が、この海で最初にしたことは、誰かに名前をつけることだった。"}]},{"id":"ep04","act":null,"title":"第4話　銛と、弾ける数字","paras":[{"k":"n","t":"次の夜も、ウタは白い珊瑚のそばにいた。"},{"k":"n","t":"けれど、もう誰にも「ようこそ」とは言っていなかった。膝を抱えるようにして浮かび、流れてくる光の文字を、一つずつ目で追っていた。"},{"k":"d","t":"「ルカ」"},{"k":"n","t":"僕を見つけると、ウタは手を振った。七秒の型ではない、少し大きすぎる振り方で。"},{"k":"s","t":"【深度 -180m／光珊瑚の浅瀬】"},{"k":"d","t":"「浅瀬の祠って、知ってる？」"},{"k":"d","t":"「しってる。あっち」"},{"k":"n","t":"ウタが指さしたのは、森のいちばん深いところだった。"},{"k":"break"},{"k":"s","t":"【深度 -192m】"},{"k":"n","t":"祠は、小さな石の社だった。"},{"k":"n","t":"屋根まで光珊瑚に覆われて、ほとんど珊瑚の一部になっている。その前に、六つの結晶が浮かんでいた。"},{"k":"n","t":"どれも、手のひらほどの大きさ。ゆっくり回りながら、それぞれの色で光っている。"},{"k":"n","t":"近づくと、結晶の上に名前が灯った。"},{"k":"n","t":"重い鎧で仲間を守る、｜潜騎士《ダイバーナイト》。"},{"k":"n","t":"ランタンの光で泡殻を癒やす、｜灯守《ランタナー》。"},{"k":"n","t":"珊瑚を育てて爆ぜさせる、｜珊瑚術士《コーラリスト》。"},{"k":"n","t":"潮の歌で味方を強くする、｜歌潮士《タイドシンガー》。"},{"k":"n","t":"泡の分身で敵を惑わす、｜泡沫師《バブラー》。"},{"k":"n","t":"そして、光の銛で連撃を叩きこむ、銛撃士。"},{"k":"n","t":"夢の初日に試着させられた、あの金色の銛だ。"},{"k":"n","t":"六つの結晶の輪の、少し外れたところに、七つ目の台座があった。"},{"k":"n","t":"台座だけだった。結晶はない。名前の灯るはずの場所には、何も灯らない。"},{"k":"n","t":"壊れているのかと思って、手をかざした。反応はなかった。ただ、空っぽの台座の上で、水がわずかに、ほかより澄んでいる気がした。"},{"k":"n","t":"僕は、六つを順に眺めた。"},{"k":"n","t":"仕事のくせで、どれを選べば何が見えるかを考えてしまう。盾は、守った数字が見えにくい。回復は、減らなかったHPとして見えるだけだ。魔法は一発が大きいぶん、間が空く。"},{"k":"n","t":"銛撃士は、遠くから届く。そして、手数が多い。"},{"k":"n","t":"一撃ごとに、数字が出る。"},{"k":"d","t":"「これにする」"},{"k":"n","t":"結晶に触れた。"},{"k":"s","t":"【ジョブ：銛撃士 を選択しました】"},{"k":"n","t":"体が光にほどけて、もう一度編みなおされる。白い潜水服。継ぎ目の琥珀色。右手に、金色の銛。"},{"k":"n","t":"今度は、試着ではなかった。"},{"k":"d","t":"「どうして、それにしたの？」"},{"k":"n","t":"ウタが訊いた。"},{"k":"d","t":"「射程と手数が、一番“数字が見える”から」"},{"k":"d","t":"「……すうじ」"},{"k":"n","t":"ウタは、よく分からないという顔をした。それから、僕の銛と、僕の顔を、交互に見た。"},{"k":"d","t":"「ねえ、ルカ」"},{"k":"d","t":"「うん」"},{"k":"d","t":"「ついていって、いい？」"},{"k":"n","t":"少しだけ、驚いた。"},{"k":"n","t":"案内役は、旅人についてはいかない。入口に立つのが仕事だからだ。そういうふうに作られている。"},{"k":"n","t":"けれど、ウタは自分で訊いた。テンプレートにない言葉で。"},{"k":"d","t":"「いいよ」"},{"k":"s","t":"【深民「ウタ」がゲストとして同行します】"},{"k":"s","t":"〈パーティ：？？？／ウタ（ゲスト）〉"},{"k":"n","t":"ウタはパーティ表示を見上げて、自分の名前を指でなぞった。"},{"k":"d","t":"「わたしの名前、ルカの名前のとなりにある」"},{"k":"d","t":"「僕のは、名前じゃないけどね」"},{"k":"d","t":"「でも、となり」"},{"k":"n","t":"ウタは満足そうに、僕の泡殻のすぐ横にくっついた。"},{"k":"break"},{"k":"n","t":"最初の獲物は、珊瑚の陰から飛び出してきた光る小魚だった。"},{"k":"s","t":"【ヒカリハゼ　HP 80】"},{"k":"n","t":"銛を構える。投げるのではなく、突く。突いて、引いて、また突く。"},{"k":"d","t":"「19」"},{"k":"n","t":"ぱちん。"},{"k":"d","t":"「21」"},{"k":"n","t":"ぱちん。"},{"k":"d","t":"「20」"},{"k":"n","t":"ぱちん。"},{"k":"n","t":"三つの数字が、ほとんど同時に浮かんで、重なり合いながら弾けた。素手のときとは、手ざわりがまるで違う。一撃の重さより、連なる拍子が気持ちいい。"},{"k":"n","t":"四撃目の穂先が、金色に光った。"},{"k":"d","t":"「CRITICAL　31」"},{"k":"n","t":"ヒカリハゼがほどける。"},{"k":"n","t":"ウタが、ぱちぱちと手を叩いた。音はしなかったけれど、袖の欠片が、拍手の形に揺れた。"},{"k":"d","t":"「すごい。数字が、いっぱい」"},{"k":"d","t":"「うん。いっぱい出るように選んだからね」"},{"k":"n","t":"それから、僕たちは浅瀬を狩ってまわった。"},{"k":"n","t":"ヒカリハゼ。泡クラゲ。砂に隠れた小さなエイ。突いて、弾けて、また突く。"},{"k":"n","t":"ウタは、数字が浮かぶたびに声に出して読んだ。「じゅうく」「にじゅういち」。読みあげるのが楽しいらしい。そのうち、僕より先に読むようになった。"},{"k":"n","t":"クリティカルの金色が出ると、ウタは決まって「わあ」と言った。七秒の型ではない、その場で生まれる「わあ」だった。"},{"k":"n","t":"夢の中の時間は、現実よりずっと長いらしい。一晩眠るあいだに、ここでは丸一日ほどが過ぎていく。"},{"k":"n","t":"やがて、浅瀬の底が見えてきた。"},{"k":"s","t":"【深度 -200m】"},{"k":"n","t":"ここから下は、光の色が変わる。浅瀬の、いちばん外側の縁だ。"},{"k":"n","t":"その境目に、ぬしがいた。"},{"k":"break"},{"k":"s","t":"【大棘フグ　HP 240】"},{"k":"n","t":"岩ほどもあるフグだった。体じゅうの棘が、琥珀色に光っている。"},{"k":"n","t":"ふくらむ。"},{"k":"n","t":"棘が、四方に飛んだ。"},{"k":"d","t":"「7」「6」「8」"},{"k":"n","t":"赤い数字が、僕の泡殻の上で弾ける。ゲージが削れていく。"},{"k":"n","t":"ウタが、僕の背中に隠れた。"},{"k":"d","t":"「だいじょうぶ？」"},{"k":"d","t":"「だいじょうぶ。……たぶん」"},{"k":"n","t":"棘がやんだ一瞬に、踏みこむ。"},{"k":"n","t":"突く。"},{"k":"d","t":"「19」"},{"k":"n","t":"突く。"},{"k":"d","t":"「21」「20」「18」"},{"k":"n","t":"連撃の拍子を崩さない。数字が浮かんで、弾けきる前に次が浮かぶ。"},{"k":"d","t":"「21」「20」"},{"k":"d","t":"「CRITICAL　31」"},{"k":"n","t":"そこで、気づいた。"},{"k":"n","t":"弾けきれなかった数字の泡が、重なっていた。白い泡と、金色の泡。重なったところで、膜が干渉しあって、虹色に光っている。"},{"k":"n","t":"数字が、虹になっていた。"},{"k":"d","t":"「21」「19」「20」"},{"k":"n","t":"突くたびに、虹が増える。十も、二十も、泡が泡に重なって、僕とフグのあいだに、小さな虹の群れができていく。"},{"k":"n","t":"十一撃目。"},{"k":"d","t":"「CRITICAL　32」"},{"k":"n","t":"最後の金色が弾けた瞬間、重なっていた泡がいっせいに割れた。"},{"k":"n","t":"ぱちぱちぱちぱちぱち、と。"},{"k":"n","t":"夜店の線香花火を、百本まとめて散らしたような音だった。"},{"k":"s","t":"【11 HIT】"},{"k":"n","t":"大棘フグが、光の粒になってほどけていく。"},{"k":"n","t":"二つぶん、削りすぎた。242与えて、240。最後の32は、少しだけ多すぎた。"},{"k":"n","t":"息が上がっていた。泡殻の中で、自分の心臓の音が聞こえる。"},{"k":"n","t":"そして、ファンファーレ。"},{"k":"n","t":"昨日より長い。三回ぶんの金管が、ひとつながりに鳴りひびく。"},{"k":"s","t":"【LEVEL UP!】×3　Lv 2 → Lv 5"},{"k":"n","t":"？？？　Lv 5　ジョブ：銛撃士"},{"k":"n","t":"HP 290　LUX 44　STR 24"},{"k":"n","t":"MAG 9　DEF 17　SPD 28"},{"k":"n","t":"LCK 9　PRS 60　FRG 11"},{"k":"n","t":"PRS 60。600mまでは、泡殻を削られずに潜れる。"},{"k":"n","t":"FRGが、10から11になっていた。レベルが上がると、壊れやすさも少しずつ増えるらしい。"},{"k":"d","t":"「ルカ、光ってる」"},{"k":"d","t":"「うん。光ってる」"},{"k":"n","t":"自分でも分かるくらい、顔が笑っていた。"},{"k":"break"},{"k":"n","t":"フグのいたあとに、小さな泡がいくつも浮かんでいた。"},{"k":"n","t":"ひとつひとつの中に、光る数字が入っている。"},{"k":"s","t":"【泡貨　+12】"},{"k":"n","t":"｜泡貨《あわか》。この海のお金らしい。"},{"k":"n","t":"手のひらに集めてみると、硬貨ほどの泡が十二個。触れると、かすかに温かかった。"},{"k":"n","t":"ヘルプがひらく。"},{"k":"s","t":"【泡貨は、1日に1％ずつ弾けて減ります】"},{"k":"s","t":"【贈られた泡貨は、24時間弾けません】"},{"k":"n","t":"お金が、減る。"},{"k":"n","t":"ため込むほど損をする、ということだ。そのかわり、贈れば一日だけ守られる。"},{"k":"n","t":"よくできた仕組みだと思った。使わせたい、回させたい、という意図がはっきり見える。"},{"k":"d","t":"「ねえ、ルカ」"},{"k":"n","t":"ウタが、まだ消えていく虹の泡を見ていた。"},{"k":"d","t":"「数字って、ほんとう？」"},{"k":"d","t":"「ほんとう、って？」"},{"k":"d","t":"「さっきの、いっぱいの数字。あれは、ほんとうのこと？」"},{"k":"n","t":"僕は、銛の柄をにぎりなおした。"},{"k":"n","t":"数字を作る仕事を、七年してきた。気持ちよく見えるように、間を計り、大きさを決めて、音をつけた。"},{"k":"n","t":"でも、数字そのものに細工をしたことはない。"},{"k":"d","t":"「数字は、嘘をつかないよ」"},{"k":"n","t":"僕は言った。"},{"k":"d","t":"「つくのは、数字を描いた人間だ」"},{"k":"n","t":"ウタは、しばらく僕の顔を見ていた。それから、こくりとうなずいた。分かったのか、分からないのかは、分からなかった。"},{"k":"n","t":"僕は手のひらの泡貨を一つ、ウタに差し出した。"},{"k":"d","t":"「はい」"},{"k":"d","t":"「……くれるの？」"},{"k":"d","t":"「最初の一枚。助手の分け前」"},{"k":"s","t":"【泡貨 ×1 をウタに贈りました】"},{"k":"n","t":"小さな泡の中に、細い光の数字が灯った。【23:59:59】。贈られた泡貨の、守られている残り時間だ。"},{"k":"n","t":"ウタは、それを両手で包んだ。こわれものを抱くように、胸の前で。"},{"k":"d","t":"「これ、弾けるんだよね」"},{"k":"d","t":"「明日になったら、少しずつね」"},{"k":"d","t":"「そっか」"},{"k":"n","t":"ウタは泡貨をのぞきこんだ。透きとおった指のあいだで、数字が一秒ずつ減っていく。"},{"k":"d","t":"「わたしも、いつか弾ける泡だよ」"},{"k":"n","t":"ウタは、なんでもないことのように言った。"},{"k":"n","t":"僕は何か言おうとして、言葉が見つからなかった。"},{"k":"d","t":"「でもね」"},{"k":"n","t":"ウタは、泡貨を少しだけ高く持ちあげた。光の柱が、その小さな膜に虹を映す。"},{"k":"d","t":"「弾けるから、美しいんだよ」"},{"k":"n","t":"どこで覚えた言葉なのか、彼女自身も知らないようだった。"},{"k":"n","t":"ただ、そう言った彼女の顔は、七秒の型のどれにも似ていなかった。"},{"k":"break"},{"k":"n","t":"帰り道、ウタが急に止まった。"},{"k":"n","t":"浅瀬の境目、深度200mの縁。そこから下は、光が少しずつ群青に溶けていく。"},{"k":"n","t":"ウタは、その下をじっと見つめていた。"},{"k":"d","t":"「ウタ？」"},{"k":"n","t":"答えない。衣の四角い欠片が、ひとつずつ明滅している。何かを聴いているときの、彼女の癖だと、僕はもう知っていた。"},{"k":"n","t":"はるか下で、琥珀色の小さな光が、ひとつ消えた。"},{"k":"n","t":"ウタが下を見て言った。「下で、だれかが灯りを食べてる」"}]},{"id":"ep05","act":null,"title":"第5話　薄明層の商人","paras":[{"k":"n","t":"深度200mの縁を越えると、光の色が変わった。"},{"k":"n","t":"頭上の真珠色が、少しずつ遠くなる。浅瀬の翠が、背中のほうへ置いていかれる。かわりに、四方から群青が満ちてくる。"},{"k":"s","t":"【深度 -240m／薄明層】"},{"k":"n","t":"昼と夜のあいだの海。"},{"k":"n","t":"ウタは、僕の泡殻のすぐ横を泳いでいた。ときどき下をのぞきこんでは、首をかしげる。"},{"k":"d","t":"「まだ、聞こえる？」"},{"k":"d","t":"「ときどき。……遠くで、ぱくって」"},{"k":"n","t":"灯りを食べる、何か。"},{"k":"n","t":"確かめに行きたかった。けれど、僕のPRSは60だ。PRS 60のままでは、600mより下で泡殻が削られていく。もっと下へ行けば、膜ごと潰れる。"},{"k":"n","t":"だから、狩った。"},{"k":"break"},{"k":"n","t":"薄明層の魚は、浅瀬より手ごわかった。"},{"k":"n","t":"光をまとわない魚が多い。群青の中から、輪郭だけがふっと現れる。ウタが先に見つけて、指をさす。僕が突く。"},{"k":"d","t":"「34」「31」「36」"},{"k":"n","t":"数字の泡が、暗い水の中で白く弾ける。浅瀬より、ひとつひとつがよく目立った。暗い場所では、光るものがきれいに見える。"},{"k":"n","t":"夢の夜を、いくつか越えた。"},{"k":"n","t":"昼間は東京で、ほどけかけた記憶をメモに書く。泡の数を数えるように、丸を並べる。夜は眠って、群青の中へ戻る。"},{"k":"n","t":"泡貨は少しずつ貯まっていった。弾けて減るぶんより、稼ぐほうが多い。"},{"k":"s","t":"【所持泡貨　1,000】"},{"k":"n","t":"ちょうど、きりのいい数字になった夜だった。"},{"k":"n","t":"深度580mの岩棚に、変な人がいた。"},{"k":"break"},{"k":"n","t":"その人は、泡を売っていた。"},{"k":"n","t":"背の高い、ひょろりとした影だった。継ぎはぎだらけの長いコートを着て、肩から、いくつもの泡を風船みたいに束ねて浮かべている。泡の中には、それぞれ小さな光る品物が入っていた。"},{"k":"d","t":"「おっ、兄ちゃん。ええとこ来たな」"},{"k":"n","t":"関西の言葉だった。"},{"k":"d","t":"「そこの嬢ちゃんも、いらっしゃい。今夜はええもん入っとるで」"},{"k":"n","t":"頭上に、名札が浮かんでいる。"},{"k":"s","t":"【カゲロウ】"},{"k":"n","t":"ジョブの印は、泡沫師。"},{"k":"d","t":"「何を売ってるんですか」"},{"k":"d","t":"「なんでもや。光る石、潮の地図、ちょっと甘い泡。……で、兄ちゃんみたいな顔した人には、だいたいこれや」"},{"k":"n","t":"カゲロウは、束の中から泡を一つ引き抜いた。"},{"k":"n","t":"中に、淡い青の珠が入っている。"},{"k":"s","t":"【耐圧の泡：PRS +10（60分）】"},{"k":"d","t":"「下、行きたいんやろ。顔に書いてある」"},{"k":"n","t":"図星だった。"},{"k":"d","t":"「おいくらですか」"},{"k":"d","t":"「1,000泡貨」"},{"k":"n","t":"ちょうど、僕の全財産だった。"},{"k":"n","t":"思わず笑ってしまった。こんなに出来すぎた値段があるだろうか。"},{"k":"d","t":"「買います」"},{"k":"d","t":"「まいど。……あ、ちょい待ち」"},{"k":"n","t":"カゲロウは、僕の財布の表示をのぞきこんだ。"},{"k":"d","t":"「兄ちゃん、今、なんぼ持っとる？」"},{"k":"d","t":"「1,000ちょうど。……の、はず」"},{"k":"n","t":"確かめる。"},{"k":"s","t":"【所持泡貨　1,000 → 990】"},{"k":"n","t":"目の前で、十枚弾けた。"},{"k":"n","t":"ぱちぱちぱち、と、小さく、気の抜けた音で。"},{"k":"d","t":"「……日付、変わったなあ」"},{"k":"n","t":"カゲロウが、しみじみと言った。"},{"k":"n","t":"1日に1％。夢の中の「1日」が、ちょうど今、終わったらしい。"},{"k":"d","t":"「泡貨はな、貯めたらあかんのや。貯めとるあいだに、勝手に弾けよる」"},{"k":"n","t":"ウタが、くすくす笑っていた。"},{"k":"d","t":"「ルカの泡貨、弾けた」"},{"k":"d","t":"「笑わないで」"},{"k":"n","t":"カゲロウは腕を組んで、うーん、とうなった。"},{"k":"d","t":"「10足らんな。しゃあない、ほな、まけといたる――」"},{"k":"n","t":"そこで、声が止まった。"},{"k":"n","t":"視界の隅で、時計が【2:30】に変わった。"},{"k":"n","t":"一拍。"},{"k":"d","t":"「……失礼しました。ええと、価格の変更は、規則でできないことになっていまして」"},{"k":"n","t":"声は同じなのに、話し方が別人だった。丁寧で、少しだけ硬い。語尾を一つずつ確かめるように置いていく。"},{"k":"d","t":"「ですが、990でも、構いません。お困りのようですので」"},{"k":"d","t":"「え、あ、ありがとうございます」"},{"k":"d","t":"「取引成立、ですね。またお越しください、銛の方」"},{"k":"n","t":"カゲロウは、静かに笑って、泡を一つ僕に手渡した。笑い方まで、さっきと違った。"},{"k":"s","t":"【耐圧の泡 を手に入れました】"},{"k":"s","t":"【所持泡貨　990 → 0】"},{"k":"n","t":"全財産が、きれいに消えた。"},{"k":"n","t":"泡の表面に、小さな付箋が貼りついていた。英語の走り書きだった。"},{"k":"d","t":"『Stay safe down there!　――T』"},{"k":"n","t":"カゲロウの字には見えなかった。大阪弁の字でも、丁寧な字でもない。けれど、カゲロウ以外に、誰がこれを書くのだろう。"},{"k":"n","t":"僕は、受けとった泡と、カゲロウの顔とを見くらべた。"},{"k":"n","t":"同じ顔だ。同じ声だ。なのに、あの一拍を境に、中の人が入れ替わったみたいだった。"},{"k":"break"},{"k":"d","t":"「なあ、ルカ」"},{"k":"n","t":"ウタが、僕の袖を引いた。"},{"k":"d","t":"「あの人の名前、なんて読むの？」"},{"k":"d","t":"「カゲロウ、じゃない？　カタカナで書いてある」"},{"k":"d","t":"「ちがうよ。むずかしい漢字だよ。虫の字が、二つ」"},{"k":"n","t":"見上げる。"},{"k":"s","t":"【カゲロウ】"},{"k":"n","t":"カタカナだった。"},{"k":"n","t":"と思った瞬間、文字が切り替わった。"},{"k":"s","t":"【蜉蝣】"},{"k":"n","t":"そしてまた、切り替わる。"},{"k":"s","t":"【KAGEROU】"},{"k":"s","t":"【カゲロウ】"},{"k":"n","t":"三つの表記が、順番に入れ替わっていく。時計の秒針みたいに、決まった間隔で。"},{"k":"d","t":"「今、カタカナに見えた？」"},{"k":"d","t":"「ううん。ずっと、虫の字。もぞもぞ動いてる」"},{"k":"n","t":"名札は、見る人に合わせて描かれるものだ。ウタには、その宛先がないのかもしれない。描かれる前の生のままの何かが、彼女には見えているのだろうか。"},{"k":"n","t":"僕は、ミズハさんの名前を思い出していた。書きこみのたびに、一文字ずつ、にじむように変わっていった名前。"},{"k":"n","t":"カゲロウの揺れ方は、あれとは違う。"},{"k":"n","t":"あちらは、ゆっくり何かに侵されていくような変わり方だった。こちらは、三つの決まった姿が、規則正しく交代している。入れ替わるたびに、どれもくっきりと、正しい形をしている。"},{"k":"n","t":"壊れているのではない。もともと、三つあるのだ。"},{"k":"n","t":"……たぶん。"},{"k":"d","t":"「お客さまの名札、珍しいですね」"},{"k":"n","t":"カゲロウが、僕の頭上を見ていた。"},{"k":"d","t":"「『？？？』というのは、初めて見ました」"},{"k":"d","t":"「直し方、知りませんか」"},{"k":"d","t":"「すみません、存じません。……でも、謎の方、というのも、素敵だと思いますよ」"},{"k":"n","t":"慰めになっているのかいないのか、分からなかった。"},{"k":"break"},{"k":"n","t":"別れぎわに、カゲロウは岩棚に腰を下ろした。"},{"k":"d","t":"「〈｜灯会《ともしびかい》〉は、ご存じですか」"},{"k":"d","t":"「ともしびかい？」"},{"k":"d","t":"「ギルドです。ギルドといっても、リーダーはいません。入るのも出るのも自由で、会費もありません」"},{"k":"d","t":"「それ、何をするギルドなんですか」"},{"k":"d","t":"「決まりは、ひとつだけです」"},{"k":"n","t":"カゲロウは、指を一本立てた。"},{"k":"d","t":"「破泡した仲間を、廃教会で待つこと」"},{"k":"n","t":"泡が割れたら、ダイバーは、近くの沈んだ教会で目を覚ます。そこまでは、灯台の声に聞いた。"},{"k":"d","t":"「それだけ？」"},{"k":"d","t":"「それだけです。でも、それがいいんです。泡が割れて、一人で目を覚ますのは、けっこうさびしいものですから」"},{"k":"n","t":"カゲロウは、群青の上のほうを見上げた。"},{"k":"d","t":"「八百メートルあたりの礼拝堂に、Lv99のおばあさまがいらっしゃいます。知らない誰かの破泡でも、ずっと待っていてくださる。わたしたちも、何度迎えていただいたか」"},{"k":"n","t":"わたしたち、と言った。"},{"k":"n","t":"一人なのに。"},{"k":"n","t":"訊こうとしたときには、カゲロウはもう立ちあがっていた。"},{"k":"d","t":"「それでは、また。泡貨は、貯めずに使ってくださいね」"},{"k":"n","t":"継ぎはぎのコートと、泡の束が、群青の中へ遠ざかっていく。名札が、カゲロウ、蜉蝣、KAGEROU、と、規則正しく瞬きながら。"},{"k":"break"},{"k":"n","t":"耐圧の泡を、胸の前で割った。"},{"k":"n","t":"青い光が、泡殻の膜に染みこんでいく。膜が、ほんの少しだけ厚くなった気がした。"},{"k":"s","t":"【PRS 60 → 70（残り 60:00）】"},{"k":"n","t":"700mまでは、削られずに潜れる。"},{"k":"n","t":"僕たちは、潜った。"},{"k":"s","t":"【深度 -650m】"},{"k":"s","t":"【深度 -700m】"},{"k":"n","t":"ここから下は、泡殻が削れる。けれど、獲物はもう少し下にいる。群青の底で、大きな影がゆっくり回っていた。"},{"k":"n","t":"さらに、80m。"},{"k":"s","t":"【深度 -780m】"},{"k":"n","t":"泡殻が、きしんだ。"},{"k":"s","t":"【圧損　−4／分】"},{"k":"n","t":"HPのゲージが、ゆっくりと痩せはじめる。一分ごとに、4。"},{"k":"n","t":"この深さに必要なPRSは78。僕のは70。足りないぶんの、半分ずつ。"},{"k":"n","t":"分かりやすい、と思った。足りないものが、そのまま痛みになる。"},{"k":"d","t":"「ルカ、へってる」"},{"k":"d","t":"「うん。急ごう」"},{"k":"n","t":"減っていくHPを横目に、突いた。"},{"k":"d","t":"「41」「38」「CRITICAL　60」"},{"k":"n","t":"この深さの魚は、経験値が重い。圧損のぶんを差し引いても、浅いところの何倍も稼げる。"},{"k":"n","t":"耐圧の泡の残り時間が、一秒ずつ減っていく。HPが、一分ごとに4ずつ減っていく。数字が二つ、並んで流れていく。"},{"k":"n","t":"残り時間が【04:12】を指したとき、それは来た。"},{"k":"s","t":"【LEVEL UP!】×3　Lv 5 → Lv 8"},{"k":"n","t":"PRS 70 → 100"},{"k":"n","t":"ファンファーレが、群青の中に金色の泡を散らす。"},{"k":"n","t":"圧損の表示が、ふっと消えた。この深さに要るのは78。もう、足りている。"},{"k":"n","t":"四分と十二秒後、胸の前で、耐圧の泡の最後の光が弾けた。役目を終えたのを知っていたみたいに。"},{"k":"s","t":"【PRS 100 → 90】"},{"k":"n","t":"泡が切れても、90。900mまでは、削られずに潜れる。"},{"k":"n","t":"残っていたのは、時計の数字が【00:00】になった空っぽの膜だけだった。"},{"k":"n","t":"僕は、その膜が群青に溶けるのを見送った。990泡貨の、六十分。悪くない買い物だった。"},{"k":"break"},{"k":"n","t":"そのとき、低い鐘のような音が、海全体に響いた。"},{"k":"n","t":"僕だけにではない。周りにいるすべてのダイバーに、同時に。"},{"k":"n","t":"群青の水が、一瞬、琥珀色に染まった。"},{"k":"n","t":"ウタが、僕の泡殻にしがみついた。衣の欠片が、ひとつ残らず明滅している。"},{"k":"n","t":"視界の中央に、文字が浮かんだ。"},{"k":"s","t":"【告知：深度 -800m 〈｜灯喰い《ひくい》〉が祭壇の灯りを占拠中】"},{"k":"s","t":"【次の灯り：案内役#07】"}]},{"id":"ep06","act":null,"title":"第6話　灯喰い","paras":[{"k":"n","t":"深度800mの礼拝堂は、群青の底に沈んでいた。"},{"k":"s","t":"【深度 -800m／薄明層】"},{"k":"n","t":"石のアーチが、いくつも重なっている。崩れかけた柱に、光珊瑚がからみついている。窓には、色の抜けたステンドグラスの枠だけが残っていた。"},{"k":"n","t":"その奥で、灯りが揺れていた。"},{"k":"n","t":"祭壇の上に、無数の小さな灯り。蝋燭の炎のような琥珀色が、水の中で、ゆらゆらと立っている。"},{"k":"s","t":"【祭壇の灯り　40】"},{"k":"n","t":"四十の灯り。沈んだ礼拝堂に、今も残っている光。"},{"k":"n","t":"ウタが、僕の泡殻の陰で身をかたくした。"},{"k":"d","t":"「いる」"},{"k":"n","t":"言われなくても、分かった。"},{"k":"n","t":"礼拝堂の床には、虹色の薄いかけらが、いくつも沈んでいた。"},{"k":"n","t":"割れた泡殻の破片だった。告知を見て、先に来た誰かのものだろう。かけらは床の上でかすかに光り、やがて溶けるように消えていく。"},{"k":"n","t":"ここで、もう何人も割れている。"},{"k":"n","t":"祭壇の向こうの暗がりで、もう一つ、琥珀色の光が揺れていた。"},{"k":"n","t":"祭壇の灯りと、まったく同じ色。けれど、それは高いところで、一本の細い竿の先にぶらさがっていた。"},{"k":"break"},{"k":"n","t":"礼拝堂の入口に、石の箱が置かれていた。"},{"k":"n","t":"蓋の上に、誰かが彫った文字。〈先に行く人へ〉。"},{"k":"n","t":"開けると、銛が二本、並んで眠っていた。"},{"k":"s","t":"【珊瑚の銛：DEF +8】"},{"k":"s","t":"【硝子の銛：FRG +5】"},{"k":"s","t":"【どちらか一つを選んでください】"},{"k":"n","t":"珊瑚の銛は、太く、重く、頼もしい。"},{"k":"n","t":"硝子の銛は、細く、透きとおっていて、今にも折れそうだった。光にかざすと、穂先の縁が、祭壇の灯りを拾って金色に光る。"},{"k":"n","t":"ステータスをひらく。"},{"k":"n","t":"？？？　Lv 8　ジョブ：銛撃士"},{"k":"n","t":"HP 410　LUX 58　STR 34"},{"k":"n","t":"MAG 11　DEF 25　SPD 38"},{"k":"n","t":"LCK 11　PRS 90　FRG 12"},{"k":"n","t":"FRGに触れる。"},{"k":"s","t":"【FRG（儚さ）：高いほど強く、高いほど壊れやすい】"},{"k":"n","t":"あの一行が、もう一度出た。"},{"k":"n","t":"硝子の銛を、手にとってみる。"},{"k":"s","t":"【FRG 12 → 17】"},{"k":"s","t":"【与ダメージ ×1.17／被ダメージ ×1.17】"},{"k":"n","t":"強くなるぶん、同じだけ脆くなる。"},{"k":"n","t":"まっとうな設計なら、ここは珊瑚の銛だ。初めてのボスで、守りを捨てる理由はない。"},{"k":"n","t":"でも。"},{"k":"n","t":"僕は、設計した側の顔を想像していた。この二本を並べた誰かは、どちらを選ばせたかったのだろう。安全な数字と、危うい数字。危うい数字のほうに、こんなにきれいな形を与えた人の気持ちを、確かめてみたかった。"},{"k":"d","t":"「こっちにする」"},{"k":"n","t":"硝子の銛を握る。"},{"k":"n","t":"泡殻の膜が、少しだけ薄くなった。虹色の干渉が、さっきより鮮やかに流れている。"},{"k":"n","t":"壊れやすくなって、きれいになった。"},{"k":"d","t":"「ルカ」"},{"k":"n","t":"ウタが、僕の膜に手を当てていた。"},{"k":"d","t":"「うすくなった」"},{"k":"d","t":"「うん。そういう銛なんだ」"},{"k":"n","t":"ウタは何も言わず、手を離さなかった。"},{"k":"break"},{"k":"n","t":"祭壇へ、踏みこむ。"},{"k":"n","t":"暗がりが、動いた。"},{"k":"n","t":"チョウチンアンコウだった。"},{"k":"n","t":"礼拝堂の天井に届きそうなほど、大きい。皮膚は古い石のように黒く、目だけが、提灯と同じ琥珀色に光っている。"},{"k":"s","t":"【灯喰い　HP 2,400】"},{"k":"n","t":"頭上に、長いゲージが一本。"},{"k":"n","t":"灯喰いが、口をひらいた。"},{"k":"n","t":"牙の並んだ暗い口の奥へ、祭壇の灯りが、吸いこまれていく。一つ、また一つ。炎の形のまま、糸を引くように細くなって、闇の中に消える。"},{"k":"s","t":"【祭壇の灯り　40 → 37】"},{"k":"n","t":"そのたびに、近くの珊瑚から色が抜けた。"},{"k":"n","t":"翠だった枝が、灰色になり、白くなる。灯りが一つ食べられるごとに、珊瑚が一本ずつ、白い骨になっていく。"},{"k":"n","t":"灯りと珊瑚が、つながっているのだ。"},{"k":"n","t":"灯喰いの提灯が、食べた灯りの色で、いっそう強く光った。"},{"k":"d","t":"「ウタ、下がってて」"},{"k":"n","t":"僕は、銛を構えた。"},{"k":"break"},{"k":"n","t":"突く。"},{"k":"d","t":"「63」"},{"k":"n","t":"ぱちん。"},{"k":"d","t":"「67」「61」"},{"k":"n","t":"浅瀬とは、手ごたえの桁が違った。数字の泡が、群青の中で大きくふくらんで、琥珀の光を映して弾ける。"},{"k":"n","t":"硝子の銛は、軽かった。軽いぶん、速い。突くたびに、穂先から光の粉が散る。"},{"k":"n","t":"灯喰いの尾が、横から来た。"},{"k":"d","t":"「98」"},{"k":"n","t":"赤い数字。"},{"k":"n","t":"泡殻が、たわんだ。HPのゲージが四分の一ほど持っていかれる。浅瀬の痛みとは比べものにならない。"},{"k":"n","t":"×1.17。数字にすれば、たった二割弱。けれど、体で受けると、その二割はひどく重かった。"},{"k":"n","t":"ゲージに、細い線が一本、走った。"},{"k":"n","t":"ひびだ。"},{"k":"n","t":"HPが減ると、ゲージそのものがひび割れていく。泡殻の厚みを、そのまま絵にしているのだ。"},{"k":"n","t":"よくできている、と思った。思いたくなかった。"},{"k":"n","t":"灯喰いの提灯が、ふっと暗くなった。"},{"k":"n","t":"来る。"},{"k":"n","t":"体が先に動いた。横へ跳ぶ。さっきまで僕のいた場所を、巨大な顎が噛み砕いた。水が渦を巻く。"},{"k":"n","t":"提灯が、暗くなってから一拍半。それが噛みつきの合図だ。"},{"k":"d","t":"「64」「66」「CRITICAL　105」"},{"k":"n","t":"金色の縁どりの数字が、灯喰いの鼻先で、ひときわ大きく弾けた。"},{"k":"n","t":"三桁。"},{"k":"n","t":"初めての三桁だった。"},{"k":"d","t":"「わあ」と、背中のほうでウタの声がした。浅瀬で覚えた、その場で生まれる「わあ」だった。"},{"k":"n","t":"その勢いのまま、もう二撃。"},{"k":"d","t":"「69」「62」"},{"k":"break"},{"k":"s","t":"【灯喰い　HP 1,843】"},{"k":"n","t":"灯喰いが、身をよじって祭壇へ戻った。"},{"k":"n","t":"口がひらく。灯りが吸いこまれる。"},{"k":"s","t":"【祭壇の灯り　37 → 35】"},{"k":"s","t":"【灯喰い　HP +120 → 1,963】"},{"k":"n","t":"回復した。"},{"k":"n","t":"灯りを食べるたびに、一つにつき60。そして、珊瑚がまた二本、白くなる。"},{"k":"n","t":"食べられる直前、灯りの一つが、僕の目の前を横切った。"},{"k":"n","t":"炎の芯に、細い文字が揺れていた。"},{"k":"s","t":"〈ここで待ってる〉"},{"k":"n","t":"浅瀬の珊瑚の枝を流れていたのと、同じ種類の光だった。誰かが、いつか、誰かに言った言葉。"},{"k":"n","t":"その一行ごと、灯りは闇に吸いこまれた。すぐ横の珊瑚の枝から、文字の流れが止まる。翠が抜けて、白い雪のような静けさだけが残った。"},{"k":"n","t":"灯りは、ただの明かりではなかった。この場所に残った、誰かの声なのだ。"},{"k":"d","t":"「やめろ」"},{"k":"n","t":"声が出た。誰に向けたのか、自分でも分からなかった。"},{"k":"n","t":"削っても、食べられたら戻る。戻るたびに、この礼拝堂から色が消える。"},{"k":"n","t":"攻撃の手を、休めるわけにはいかなかった。"},{"k":"n","t":"突く。突く。突く。提灯が暗くなったら跳ぶ。跳んだ先から、また突く。"},{"k":"d","t":"「62」「69」「65」"},{"k":"n","t":"尾が来る。"},{"k":"d","t":"「103」"},{"k":"n","t":"ひびが、二本になった。HPは、もう半分ほどしか残っていない。"},{"k":"n","t":"そのとき、背中のほうで、何かが聞こえた。"},{"k":"n","t":"歌だった。"},{"k":"n","t":"ウタが、歌っていた。言葉のない、六つほどの音。上がって、少し下がって、また上がる。浅瀬で、最初に聞いた旋律。"},{"k":"n","t":"体が、軽くなった。"},{"k":"s","t":"【SPD 38 → 41】"},{"k":"n","t":"表示の右側に、効果元の欄がある。いつもなら、そこにジョブやスキルの名前が入る。"},{"k":"s","t":"【効果元：――】"},{"k":"n","t":"空欄だった。"},{"k":"n","t":"ウタには、まだジョブがない。歌潮士の結晶にも触れていない。なのに、歌が数字を動かしている。"},{"k":"n","t":"この海のシステムには、彼女の歌を参照する項目がないのだ。だから、効果元が書けない。"},{"k":"n","t":"システムの外側から、数字が届いている。"},{"k":"d","t":"「ウタ、そのまま！」"},{"k":"n","t":"ウタは、うなずくかわりに、歌を一段高くした。"},{"k":"break"},{"k":"n","t":"三つ速くなっただけで、海の見え方が変わった。"},{"k":"n","t":"提灯が暗くなる。一拍半を待たずに、跳べる。跳んだ勢いのまま、横腹へ。"},{"k":"d","t":"「67」「70」「63」「CRITICAL　99」"},{"k":"n","t":"足していく。ゲージの残りと照らしあわせる。前の仕事で、何千回もやった計算だった。"},{"k":"d","t":"「64」「60」「71」「59」「66」「61」「63」「64」"},{"k":"s","t":"【灯喰い　HP 960】"},{"k":"n","t":"灯喰いが、また祭壇へ向かう。"},{"k":"n","t":"今度は、その前に回りこんだ。祭壇と顎のあいだに、僕の泡殻を割りこませる。"},{"k":"n","t":"顎が、僕の鼻先で止まった。灯りを食べるために、まっすぐ祭壇を狙っていたから。"},{"k":"n","t":"突く。"},{"k":"d","t":"「68」"},{"k":"n","t":"灯喰いが、怯んだように身を引いた。"},{"k":"n","t":"いける。"},{"k":"n","t":"熱が、胸の中で泡立っていた。"},{"k":"n","t":"楽しい、と思ってしまった。"},{"k":"n","t":"突く。弾ける。突く。弾ける。"},{"k":"d","t":"「65」「61」「69」「66」"},{"k":"d","t":"「62」「60」「64」「59」「63」「61」「65」「60」「65」"},{"k":"n","t":"尾が来た。避けきれなかった。"},{"k":"d","t":"「107」"},{"k":"n","t":"ひびが、三本になる。HPのゲージが、端のほうでかろうじてつながっている。"},{"k":"n","t":"残り、102。"},{"k":"n","t":"それでも、僕は数えていた。"},{"k":"s","t":"【灯喰い　HP 72】"},{"k":"n","t":"残り、三パーセント。"},{"k":"n","t":"72。"},{"k":"n","t":"僕の一撃は、低く出れば58、高く出れば71。"},{"k":"n","t":"71。72には、一つだけ届かない。どんな目が出ても、あと二撃いる。"},{"k":"n","t":"クリティカルが出れば、話は別だ。その確率は、一割ちょっと。"},{"k":"n","t":"数字は、全部見えていた。"},{"k":"n","t":"見えていたから、怖くなかった。"},{"k":"n","t":"ウタの歌は、まだ続いていた。旋律が上がりきる手前で、ふっと消えて、また最初から始まる。終わらない歌だった。"},{"k":"n","t":"僕は、銛を引いた。次の一撃のための、ほんの少しの溜め。"},{"k":"n","t":"金色が出るか。出なければ、もう一撃。"},{"k":"n","t":"賽を振る直前の、あの一瞬の静けさ。何百回も人に味わわせてきた瞬間を、僕は初めて、自分の体で味わっていた。"},{"k":"n","t":"悪くない、と思った。この瞬間のために、数字はあるのだ。"},{"k":"break"},{"k":"n","t":"灯喰いが、祭壇を見た。"},{"k":"s","t":"【祭壇の灯り　35】"},{"k":"n","t":"まだ、灯りはある。食べに行く。その隙に、背中から突けばいい。"},{"k":"n","t":"けれど、灯喰いは祭壇へ向かわなかった。"},{"k":"n","t":"琥珀の目が、ゆっくりと動いた。"},{"k":"n","t":"僕の背中の、さらに後ろへ。"},{"k":"n","t":"歌っている、ウタへ。"},{"k":"n","t":"ウタは、光っていた。"},{"k":"n","t":"透きとおった体の内側に、淡い光がともっている。歌うたびに、その光が少し強くなる。四角い欠片の衣が、一枚一枚、灯りのように明滅していた。"},{"k":"n","t":"祭壇の灯りと、同じ色だった。"},{"k":"n","t":"提灯が、暗くなる。"},{"k":"n","t":"一拍半。"},{"k":"d","t":"「ウタ！」"},{"k":"n","t":"僕は跳んだ。噛みつきの来る方向とは、逆に。避けるためではなく、間に入るために。"},{"k":"n","t":"ウタの前に、泡殻ごと体をねじこむ。"},{"k":"n","t":"視界が、灯喰いの口で埋まった。牙の向こうに、食べられた灯りが、ぼんやりと溜まっているのが見えた。"},{"k":"n","t":"硝子の銛を突きだす。"},{"k":"n","t":"届いたかどうか、分からなかった。数字は、浮かばなかった。"},{"k":"n","t":"かわりに、膜が鳴った。"},{"k":"n","t":"ひびの入った泡殻が、きしんで、たわんで、限界まで薄く伸びる。"},{"k":"n","t":"×1.17。"},{"k":"n","t":"いい銛だった。いい選択だった、と、まだ思っていた。"},{"k":"n","t":"泡が割れていく、そのほんの一瞬。"},{"k":"n","t":"虹色の破片の向こうで、僕は見た。"},{"k":"n","t":"僕の後ろにいたはずのウタが、灯喰いの口の中へ、灯りと同じ形に細くなって、吸いこまれていくのを。"},{"k":"n","t":"手を伸ばした。"},{"k":"n","t":"指は、もう膜の外に届かなかった。"},{"k":"n","t":"HPが0になる音は、思っていたよりずっと小さかった。――パチン。"}]},{"id":"ep07","act":null,"title":"第7話　破泡","paras":[{"k":"s","t":"【破泡】"},{"k":"n","t":"最初に戻ってきたのは、その二文字だった。"},{"k":"n","t":"暗闇の中に、白い文字だけが浮かんでいる。音はない。痛みもない。ただ、自分の泡が割れたのだという事実が、静かに置かれていた。"},{"k":"s","t":"【EXP −312】"},{"k":"s","t":"【FRG 12 → 18】"},{"k":"n","t":"数字が二つ、続けて灯って、消えた。"},{"k":"n","t":"それから、光が来た。"},{"k":"break"},{"k":"n","t":"目をひらくと、雪が降っていた。"},{"k":"n","t":"いや、雪ではなかった。虹色の、薄い破片だった。"},{"k":"n","t":"割れたシャボン玉の膜のかけらが、天井の高いところから、ゆっくりと舞い落ちてくる。一枚一枚が、落ちながら色を変えた。真珠色から、薄い青へ。青から、翠へ。"},{"k":"n","t":"僕の泡殻の、かけらだった。"},{"k":"n","t":"ここは、礼拝堂だった。灯喰いのいた場所とは違う。もっと高い天井と、もっと細い柱。崩れかけた石のアーチに、白い珊瑚がびっしりと絡みついている。"},{"k":"n","t":"尖った高い窓から、真珠白の光が一筋、斜めに差しこんでいた。光の中を、破片が雪のように降っていく。"},{"k":"n","t":"祭壇には、灯りが一つだけ残っていた。"},{"k":"n","t":"小さな尖塔の形をした祠の奥で、琥珀色の炎が一つ、じっと立っている。ほかの燭台は、どれも空だった。"},{"k":"n","t":"僕の体は、ほとんど透きとおっていた。輪郭だけの、光の線。泡殻は、どこにもない。"},{"k":"s","t":"【HP 0／410】"},{"k":"n","t":"手を伸ばす。重さのない腕が、祭壇の灯りに触れた。"},{"k":"n","t":"温かかった。"},{"k":"s","t":"【HP 410／410】"},{"k":"s","t":"【LUX 58／58】"},{"k":"s","t":"【復活地点を記録しました】"},{"k":"n","t":"体に、色が戻ってくる。白い潜水服。継ぎ目の琥珀色。そのまわりに、薄い膜がふくらんで、もう一度僕を包んだ。"},{"k":"n","t":"右手は、空だった。"},{"k":"n","t":"硝子の銛は、泡と一緒に砕けていた。降ってくる破片のどこかに、あの透きとおった穂先も混じっているのだろう。"},{"k":"break"},{"k":"n","t":"破片のあいだを、別の光が漂っていた。"},{"k":"n","t":"小さな、金色の粒。何百も、何千も。"},{"k":"n","t":"僕から離れていくのが分かった。胸のあたりから、ほどけるように抜けていく。"},{"k":"n","t":"EXPだ。"},{"k":"n","t":"Lv8で稼いだ経験値の、三割。数字にすれば312。それが、光の粒になって、礼拝堂の空気に溶けていく。"},{"k":"n","t":"粒は、ゆっくりと床へ降りていった。祭壇の下、白い珊瑚の茂みへ。"},{"k":"n","t":"白い枝は、何も流していなかった。浅瀬の端で見た、あの雪のような静けさ。誰にも思い出されなくなった言葉の、骨。"},{"k":"n","t":"金色の粒が、その白に触れた。"},{"k":"n","t":"一粒、また一粒。染みこんでいく。"},{"k":"n","t":"白い茂みの真ん中で、何かが動いた。"},{"k":"n","t":"小さな芽だった。白の中から、翠の色が、そっと頭をもたげる。花びらのような葉が、一枚ずつ、内側からひらいていく。"},{"k":"n","t":"翠の珊瑚が、一輪、咲いた。"},{"k":"n","t":"白い茂みの中で、そこだけが光っていた。"},{"k":"n","t":"なくしたものが、咲いている。"},{"k":"n","t":"僕は、ただそれを見ていた。"},{"k":"n","t":"悔しいとも、きれいだとも、うまく言えなかった。両方が、同じ泡の中に入っていた。"},{"k":"break"},{"k":"d","t":"「おかえり」"},{"k":"n","t":"声がした。"},{"k":"n","t":"振り向くと、ベンチに誰かが座っていた。"},{"k":"n","t":"木の長椅子が何列も並ぶ、その真ん中あたり。僕に背を向けて、小柄な人影が一人。"},{"k":"n","t":"頭に、真鍮の潜水兜をかぶっていた。丸い窓のついた、古めかしい兜だ。その縁から、白い髪がこぼれている。肩には、重そうな鎧。"},{"k":"s","t":"【千歳　Lv 99　潜騎士】"},{"k":"n","t":"九十九。"},{"k":"n","t":"この海で初めて見る、二桁の上限の数字だった。"},{"k":"d","t":"「……ただいま、でいいんですか」"},{"k":"d","t":"「いいんだよ。帰ってきたんだから」"},{"k":"n","t":"兜の中から、くぐもった声が笑った。年を重ねた女の人の声だった。どこか、海辺の町の言葉の響きがある。"},{"k":"d","t":"「あんた、灯喰いにやられたろう。いい割れ方してたよ。ここまで音が聞こえた」"},{"k":"d","t":"「見てたんですか」"},{"k":"d","t":"「聞いてただけさ。割れる音は、この礼拝堂まで届くんだ。だから、ここで待ってる」"},{"k":"d","t":"「待ってる？」"},{"k":"d","t":"「灯会の決まりでね。破泡したもんを、廃教会で待つ。それだけ」"},{"k":"n","t":"カゲロウの言っていた、唯一の決まり。"},{"k":"d","t":"「僕のこと、知ってたんですか」"},{"k":"d","t":"「知らないよ」"},{"k":"n","t":"あっさりと、千歳さんは言った。"},{"k":"d","t":"「知らない誰かでも、待つんだよ。泡が割れて、一人で目を覚ますのは、さびしいからね」"},{"k":"n","t":"僕は、何も言えなかった。"},{"k":"n","t":"死んだ人から荷物が届いた夜、部屋の灯りはデスクライト一つだけだった。誰も待っていなかった。"},{"k":"n","t":"ここでは、知らない人が待っていた。"},{"k":"n","t":"長椅子の背もたれに、細かな傷がいくつも刻まれているのに気づいた。"},{"k":"n","t":"文字だった。カタカナ、漢字、ローマ字。大きさも書き方もばらばらの、たくさんの名前。"},{"k":"d","t":"「迎えたもんの名前さ」"},{"k":"n","t":"千歳さんが、腰の小刀を軽く叩いた。"},{"k":"d","t":"「名札はすぐ変わっちまうけど、木に彫ったのは残るからね。……あんた、名前は」"},{"k":"d","t":"「表示は、こうです」"},{"k":"n","t":"僕は頭上を指さした。にじんだ枠の中の、三つの疑問符。"},{"k":"d","t":"「本当は、ルカっていいます」"},{"k":"d","t":"「ルカ」"},{"k":"n","t":"千歳さんは小刀を抜いて、背もたれの空いたところに、ゆっくりと二文字を刻んだ。"},{"k":"n","t":"ル。カ。"},{"k":"n","t":"システムの文字ではない、少し傾いた、人の手の字だった。名札は何も変わらない。それでも、その二文字は、確かにそこにあった。"},{"k":"break"},{"k":"n","t":"千歳さんは、祭壇の下の翠の珊瑚に、兜の窓を向けた。"},{"k":"d","t":"「咲いたね」"},{"k":"d","t":"「僕のEXPです。……たぶん」"},{"k":"d","t":"「そうだよ。なくしたぶんだけ、海がきれいになる。そういう決まりなんだ」"},{"k":"n","t":"千歳さんは、少し遠くを見るようにした。"},{"k":"d","t":"「昔、全部還した人がいてね」"},{"k":"d","t":"「全部？」"},{"k":"d","t":"「経験値を、ぜんぶ。どうやったのかは知らない。でも、そこだけ珊瑚が森みたいになってる。いつか、連れてってあげるよ」"},{"k":"n","t":"全部。三割でこれなら、全部を還したら、どれほどの森になるのだろう。"},{"k":"n","t":"想像しようとして、やめた。それは、何もかもを手放すということだ。"},{"k":"n","t":"ステータスをひらく。"},{"k":"s","t":"【FRG 18】"},{"k":"n","t":"12だったものが、18になっていた。"},{"k":"n","t":"壊れやすさが、増えている。"},{"k":"d","t":"「あの、FRGって……」"},{"k":"d","t":"「上がってたろう」"},{"k":"n","t":"千歳さんは、うなずいた。"},{"k":"d","t":"「割れるたびに、上がるんだよ。壊れたぶんだけ、脆く、強くなる」"},{"k":"n","t":"脆く、強く。"},{"k":"n","t":"設計者として、その仕組みを想像した。壊れた人ほど、強い一撃を出せる。そのかわり、もっと壊れやすくなる。"},{"k":"n","t":"残酷な設計だと思った。"},{"k":"n","t":"同じくらい、正直な設計だとも思った。"},{"k":"d","t":"「海はね、深いほど静かで、静かなほど光るんだよ」"},{"k":"n","t":"千歳さんは、それだけ言った。説明というより、天気の話をするような口ぶりで。"},{"k":"break"},{"k":"n","t":"虹色の破片は、まだ降っていた。"},{"k":"n","t":"降りながら、少しずつ薄くなっていく。床に届く前に、溶けて消えるものもある。"},{"k":"n","t":"僕は、破片の一枚を手のひらで受けた。"},{"k":"n","t":"その小さな膜に、何かが映っていた。"},{"k":"n","t":"琥珀色の口。吸いこまれていく光。"},{"k":"n","t":"ウタだ。"},{"k":"n","t":"泡が割れる直前に見たものが、破片の中で、まだ揺れていた。灯りと同じ形に細くなって、闇の奥へ引きこまれていく、透きとおった体。"},{"k":"d","t":"「……ウタ」"},{"k":"n","t":"声に出した瞬間、破片は手のひらで溶けた。"},{"k":"d","t":"「連れがいたのかい」"},{"k":"d","t":"「深民の子です。案内役の。僕が、名前をつけた」"},{"k":"d","t":"「名前を」"},{"k":"n","t":"千歳さんの兜が、わずかに傾いた。"},{"k":"d","t":"「それで、あいつに呑まれた」"},{"k":"d","t":"「僕が、かばいきれなくて」"},{"k":"n","t":"かばった、はずだった。泡殻ごと、間に入った。"},{"k":"n","t":"それでも、届かなかった。"},{"k":"n","t":"ステータスの数字は、全部正しかった。金色が出るか、もう一撃いるか。その賭けに、僕は夢中になっていた。数字の向こうにいるウタのことを、ほんの一瞬、忘れていた。"},{"k":"n","t":"楽しいと思ってしまった、あの一瞬を。"},{"k":"n","t":"祭壇の下で、翠の珊瑚が小さく光っている。"},{"k":"n","t":"僕のなくした312は、あそこで咲いた。けれど、ウタは咲かない。経験値みたいに、誰かの美しさに還ったりはしない。"},{"k":"n","t":"なくしていいものと、なくしてはいけないもの。数字は、その区別をしてくれなかった。"},{"k":"d","t":"「深民はね、泡殻を持ってないんだよ」"},{"k":"n","t":"千歳さんが、静かに言った。"},{"k":"d","t":"「だから、割れない。そのかわり、食べられたら、食べたやつの中に残る。灯りと同じさ」"},{"k":"d","t":"「……まだ、いるんですか」"},{"k":"n","t":"千歳さんは、立ちあがった。"},{"k":"n","t":"鎧が、重い音を立てた。真鍮の兜が、祭壇の灯りを映して鈍く光る。"},{"k":"n","t":"思っていたより、ずっと小さな人だった。僕の肩くらいまでしかない。それなのに、礼拝堂の水がその人のまわりだけ、どっしりと動かない気がした。"},{"k":"d","t":"「灯喰いの提灯、見たかい。食べた灯りの色で光るんだ」"},{"k":"d","t":"「見ました。琥珀色の」"},{"k":"d","t":"「さっき、ここから聞こえたよ。あいつの腹の底で、ちっちゃな歌がね」"},{"k":"n","t":"六つほどの音。上がって、少し下がって、また上がる。"},{"k":"n","t":"千歳さんは、兜の窓ごしに僕を見た。"},{"k":"n","t":"千歳さんは言った。「あの子、まだあいつの腹の中で光ってるよ。迎えに行くかい」"}]},{"id":"ep08","act":null,"title":"第8話　灯会","paras":[{"k":"n","t":"迎えに行く、と僕は答えた。"},{"k":"n","t":"けれど千歳さんは、すぐには灯喰いのところへ向かわなかった。"},{"k":"d","t":"「一人で行っても、もう一回割れるだけだよ。仲間を連れていきな」"},{"k":"n","t":"礼拝堂を出て、群青の中を下へ。千歳さんの重い鎧は、沈むというより、水の中を歩いているように見えた。"},{"k":"s","t":"【深度 -900m】"},{"k":"s","t":"【深度 -1,000m】"},{"k":"n","t":"泡殻が、低くきしんだ。"},{"k":"s","t":"【圧損　−5／分】"},{"k":"n","t":"この深さに必要なPRSは100。僕のは90。足りない10の、半分ずつ。"},{"k":"n","t":"HPが、一分ごとに5ずつ削れていく。"},{"k":"d","t":"「おや、足りてないね」"},{"k":"n","t":"千歳さんが振り向いた。"},{"k":"d","t":"「あたしの分担に入りな」"},{"k":"n","t":"千歳さんの鎧から、淡い光の輪がひろがった。輪が僕の泡殻に触れて、膜の外側を薄く包む。"},{"k":"s","t":"【水圧分担：千歳】"},{"k":"n","t":"見ると、圧損の数字は、−5のままだった。"},{"k":"d","t":"「減るのは止まらないんですね」"},{"k":"d","t":"「止まらないよ。分担は、潰れないための傘さ。痛いのは自分持ち」"},{"k":"n","t":"千歳さんは、からからと笑った。"},{"k":"d","t":"「でも、傘があると、もっと深くまで行けるだろう」"},{"k":"n","t":"分かりやすい、と思った。痛みと安全を、別の数字にしてある。"},{"k":"break"},{"k":"n","t":"群青の底に、塔が立っていた。"},{"k":"n","t":"灯台だった。"},{"k":"n","t":"白い石を積んだ、細くて高い塔。半分は海底の砂に埋もれ、壁には光珊瑚がびっしりと絡んでいる。"},{"k":"n","t":"そのてっぺんで、灯りが回っていた。"},{"k":"n","t":"真珠白の光の帯が、ゆっくりと群青を掃いていく。光が通りすぎるたびに、遠くの珊瑚の森が、一瞬だけ翠に浮かびあがる。"},{"k":"d","t":"「灯会の拠点さ。昔は、どこかのゲームの港の灯台だったらしい」"},{"k":"n","t":"海の底で、まだ船を待っている灯台。"},{"k":"n","t":"中に入ると、人がいた。"},{"k":"n","t":"十人ほど。らせん階段の踊り場や、窓辺の石段に、思い思いに腰かけている。話している人、眠っている人、黙って光を眺めている人。"},{"k":"n","t":"入口の扉がひらいて、泡殻の薄い若いダイバーが一人、ふらふらと入ってきた。"},{"k":"d","t":"「……割れた。三回目」"},{"k":"d","t":"「おかえりー」"},{"k":"d","t":"「おかえり」"},{"k":"n","t":"あちこちから、気の抜けた声が飛ぶ。誰かが手を叩き、誰かが温かそうな泡を一つ放ってやる。ダイバーは照れくさそうに笑って、踊り場の隅に座りこんだ。"},{"k":"n","t":"それだけだった。誰も、なぜ割れたのかを訊かない。"},{"k":"d","t":"「入るのも、出るのも自由。会費もなし。リーダーもなし」"},{"k":"n","t":"千歳さんが言った。"},{"k":"d","t":"「だから、あたしも偉くないよ。年寄りなだけ」"},{"k":"d","t":"「兄ちゃん！」"},{"k":"n","t":"聞き覚えのある声がした。"},{"k":"n","t":"らせん階段の上から、継ぎはぎのコートが手を振っていた。泡の束が、風船みたいに揺れている。"},{"k":"s","t":"【カゲロウ】"},{"k":"n","t":"カゲロウ。蜉蝣。KAGEROU。名札は、相変わらず規則正しく瞬いていた。"},{"k":"d","t":"「生きとったか。……いや、割れたんやな。顔に書いてある」"},{"k":"d","t":"「書いてありますか」"},{"k":"d","t":"「書いてあるわ。いっぺん割れた人の顔や」"},{"k":"n","t":"カゲロウは、僕の肩を叩いた。泡殻ごしに、ぽん、と。"},{"k":"d","t":"「灯会へ、いらっしゃい」"},{"k":"break"},{"k":"n","t":"灯台のいちばん上の部屋に、もう一人いた。"},{"k":"n","t":"回る灯りの真下で、女の子が、ランタンを膝に抱えていた。"},{"k":"n","t":"僕よりずいぶん年下だろうか。肩までの髪に、丸い眼鏡。ランタンの中で、小さな白い炎が揺れている。"},{"k":"s","t":"【ノア　Lv 72　灯守】"},{"k":"d","t":"「こんばんは。千歳さんが、また誰か拾ってきたって聞いて」"},{"k":"d","t":"「拾ってきたんだよ」"},{"k":"n","t":"千歳さんが、平然と言った。"},{"k":"d","t":"「ノアちゃんはね、うちでいちばん光が強い灯守さ。割れかけた泡を、何べんも戻してもらった」"},{"k":"d","t":"「千歳さんが無茶するからでしょ」"},{"k":"n","t":"ノアは、ランタンを少し持ちあげてみせた。白い炎が、眼鏡のレンズに二つ映る。"},{"k":"d","t":"「湘南のほうから潜ってるの。窓から海が見えるところ」"},{"k":"d","t":"「現実でも海の近くなんですね」"},{"k":"d","t":"「うん。だから、夢でも海にいるのかも」"},{"k":"n","t":"ノアは笑って、僕の泡殻を見た。それから、頭上の名札を。"},{"k":"d","t":"「……あれ」"},{"k":"d","t":"「表示は、こうなんです」"},{"k":"n","t":"僕は、初めて人に説明した。"},{"k":"n","t":"名前を入力したら、二つの泡になって沈んでいったこと。何を入れても【？？？】になること。問い合わせ先がないこと。そして、闇の底から聞こえた声のこと。"},{"k":"d","t":"「その名前、もらったよ、って」"},{"k":"n","t":"話し終えると、灯台の中が少し静かになった。"},{"k":"d","t":"「ふうん」"},{"k":"n","t":"カゲロウが、腕を組んだ。"},{"k":"d","t":"「名前、とられたんか」"},{"k":"d","t":"「たぶん。……たぶん、です」"},{"k":"d","t":"「本当の名前は？」"},{"k":"n","t":"ノアが訊いた。"},{"k":"d","t":"「ルカ」"},{"k":"d","t":"「じゃあ、ルカくんだ」"},{"k":"n","t":"ノアは、あっさりと言った。"},{"k":"d","t":"「表示がどうでも、私たちはルカくんって呼ぶよ。それでいいでしょ？」"},{"k":"d","t":"「ええな。ルカ。呼びやすい」"},{"k":"d","t":"「ルカ、だね」"},{"k":"n","t":"カゲロウと、千歳さんも続いた。"},{"k":"n","t":"三人に、名前を呼ばれた。"},{"k":"n","t":"頭上の名札を見上げる。"},{"k":"s","t":"【？？？】"},{"k":"n","t":"変わらなかった。"},{"k":"n","t":"浅瀬で、ウタに呼ばれたときは、にじみが一瞬だけ薄くなった気がした。今は、それもない。三人が呼んでも、疑問符はぴくりともしなかった。"},{"k":"n","t":"気のせいだったのだろうか。あのときだけ、何かが違ったのだろうか。"},{"k":"d","t":"「名札なんか、どうでもええねん」"},{"k":"n","t":"カゲロウが言った。"},{"k":"d","t":"「わしらが呼んどる。それで足りる」"},{"k":"s","t":"〈パーティ：？？？／ノア／カゲロウ／千歳〉"},{"k":"n","t":"パーティの表示に、四つの名前が並んだ。僕の欄だけが、疑問符のままで。"},{"k":"n","t":"ノアの名前の横に、小さな数字がいくつか並んでいた。Lv、HP、LUX。その最後に、【FRG 88】。"},{"k":"n","t":"88。僕の18の、五倍近い。"},{"k":"n","t":"Lv72なら、そういうものなのだろうか。そのときは、深く考えなかった。"},{"k":"break"},{"k":"d","t":"「で、灯喰いや」"},{"k":"n","t":"カゲロウが、床に泡を一つ置いた。泡の中に、小さな礼拝堂の模型が浮かんでいる。"},{"k":"d","t":"「あいつ、強いで。何人も割られとる」"},{"k":"d","t":"「戦い方、見せてもらってもいいですか」"},{"k":"n","t":"僕は、泡の模型に指を入れた。小さな灯喰いが、礼拝堂の中で泳ぎだす。"},{"k":"n","t":"頭の中で、一度割れた戦いを巻きもどした。"},{"k":"d","t":"「噛みつきの前に、提灯が暗くなります。暗くなってから、一拍半」"},{"k":"d","t":"「ほう」"},{"k":"d","t":"「尾は、横から。三回に一回、提灯が明るくなったあとに来る」"},{"k":"d","t":"「よう見とるな」"},{"k":"d","t":"「灯りを食べると、一つにつき60回復します。そして、食べた灯りの数だけ、まわりの珊瑚が白くなる」"},{"k":"n","t":"千歳さんの兜が、小さくうなずいた。"},{"k":"d","t":"「それから、提灯。あれは灯りを食べたあとに、必ず一度、強く光ります。食べたものを、あそこに溜めているんだと思う」"},{"k":"n","t":"言いながら、気づいた。"},{"k":"n","t":"僕はいま、仕事をしている。"},{"k":"n","t":"敵の行動を分解して、予告を探して、遊ぶ人が勝てる筋道を組み立てる。七年間、毎日やってきたことだ。誰にも頼まれなくなった、昨日までの仕事。"},{"k":"d","t":"「作戦は、こうです」"},{"k":"n","t":"千歳さんが、盾で噛みつきを受ける。ノアが、それを支える。カゲロウの泡の分身を祭壇のまわりに灯して、偽物の灯りにする。食べても回復しない灯りを。"},{"k":"d","t":"「灯喰いが偽物を食べに行った瞬間、提灯が光ります。そこを、僕が突く」"},{"k":"d","t":"「それと、もう一つ」"},{"k":"n","t":"僕は、最後に見た告知を思い出していた。"},{"k":"s","t":"【告知：深度 -800m 灯喰いが祭壇の灯りを占拠中】"},{"k":"s","t":"【次の灯り：案内役#07】"},{"k":"n","t":"次の灯り。灯喰いは、最初からウタを狙っていた。"},{"k":"d","t":"「あいつは、ウタを“案内役#07”として狙っていました。僕がつけた名前じゃなくて、もう使っていない古い名前で」"},{"k":"d","t":"「古い名前で、呼んで、食べたんか」"},{"k":"d","t":"「たぶん。だから、ウタはまだ、あいつの中で“灯り”の扱いになってる。……溜めた灯りは、提灯に集まる」"},{"k":"n","t":"提灯を割れば、灯りは外に出る。"},{"k":"n","t":"ウタも、一緒に。"},{"k":"n","t":"しばらく、誰も何も言わなかった。"},{"k":"d","t":"「……あかん」"},{"k":"n","t":"カゲロウが、頭をかいた。"},{"k":"d","t":"「兄ちゃん、仕事できる人やん」"},{"k":"d","t":"「元、ですけど」"},{"k":"d","t":"「元でも、できる人や」"},{"k":"n","t":"ノアが、くすっと笑った。"},{"k":"d","t":"「ルカくん、いま、すごく楽しそうな顔してた」"},{"k":"n","t":"そうだろうか。そうかもしれない。"},{"k":"n","t":"誰かの役に立ったのは、ずいぶん久しぶりだった。"},{"k":"break"},{"k":"n","t":"作戦の細かいところを詰めているうちに、ノアが時計を見た。"},{"k":"n","t":"視界の隅の、現実の時刻。"},{"k":"s","t":"【3:39】"},{"k":"d","t":"「あ、そろそろだ」"},{"k":"d","t":"「毎晩、3時40分ちょうどに落ちるんです、この子」"},{"k":"n","t":"カゲロウが教えてくれた。いつのまにか、丁寧な言葉づかいになっていた。そういえば作戦の途中で一度、一拍だけ黙ったのだった。"},{"k":"d","t":"「お薬の時間だから」"},{"k":"n","t":"ノアは、なんでもないことのように笑った。"},{"k":"n","t":"ランタンを膝から下ろして、立ちあがる。それから、僕の頭上を見上げた。"},{"k":"n","t":"名札を見ているのだと思った。疑問符の三つ並んだ、にじんだ枠を。"},{"k":"n","t":"けれど、ノアの目は、もう少し上を見ていた。"},{"k":"d","t":"「ねえ、ルカくん」"},{"k":"n","t":"灯台の灯りが、ゆっくりと一周して、ノアの眼鏡を白く光らせた。"},{"k":"n","t":"ノアが言った。「ルカくんの名前、私には『？？？』じゃなくて、白い灯りみたいな空白に見えるよ」"}]},{"id":"ep09","act":null,"title":"第9話　灯りを取り返す","paras":[{"k":"s","t":"【深度 -800m／薄明層】"},{"k":"n","t":"小礼拝堂は、前に来たときより暗かった。"},{"k":"n","t":"祭壇の灯りは、もう二十も残っていなかった。まわりの珊瑚は、ほとんどが白い。雪の降り積もった森のように、音がない。"},{"k":"n","t":"その奥で、琥珀色の提灯が揺れていた。"},{"k":"s","t":"【灯喰い　HP 2,400】"},{"k":"n","t":"ゲージは、満タンに戻っていた。僕が削った分は、灯りを食べて取り返したのだろう。"},{"k":"d","t":"「ほれ、兄ちゃん」"},{"k":"n","t":"カゲロウが、泡の束から一本の銛を引き抜いて、僕に放った。"},{"k":"n","t":"硝子ではない。灰色の、まっすぐな、ふつうの銛だ。"},{"k":"d","t":"「貸しや。返さんでええけど、貸しや」"},{"k":"d","t":"「どっちなんですか」"},{"k":"d","t":"「気持ちの問題や」"},{"k":"s","t":"【灯会の銛 を装備しました】"},{"k":"n","t":"握る。重くて、頼もしい。"},{"k":"s","t":"〈パーティ：？？？／ノア／カゲロウ／千歳〉"},{"k":"n","t":"四つの名前が、視界の端に並んでいる。前は、二つだけだった。"},{"k":"n","t":"そして、そのどちらも、今ここにはいない。"},{"k":"n","t":"耳を澄ます。"},{"k":"n","t":"灯喰いの腹の底から、かすかに何かが聞こえた。六つほどの音。上がって、少し下がって、また上がる。"},{"k":"d","t":"「……いる」"},{"k":"d","t":"「いるね」"},{"k":"n","t":"千歳さんが、盾を構えた。"},{"k":"break"},{"k":"d","t":"「ほな、いくで！」"},{"k":"n","t":"カゲロウの泡の束が、ほどけた。"},{"k":"n","t":"泡が祭壇のまわりに散って、一つずつ、ぽうっと琥珀色に灯る。本物の灯りと見分けがつかない。"},{"k":"s","t":"【泡身代わり ×3】"},{"k":"n","t":"灯喰いの目が、偽物の灯りに向いた。"},{"k":"n","t":"口がひらく。吸いこむ。"},{"k":"s","t":"【灯喰い　HP +0】"},{"k":"d","t":"「回復せえへんで！　中身、空っぽの泡やからな！」"},{"k":"n","t":"灯喰いが、身をよじった。食べたはずのものが、腹の中で弾けたのだ。"},{"k":"n","t":"その瞬間、提灯が、強く光った。"},{"k":"n","t":"食べたあとに、必ず一度。"},{"k":"d","t":"「今！」"},{"k":"n","t":"僕は跳んだ。灰色の銛の穂先を、まっすぐ提灯へ。"},{"k":"d","t":"「113」"},{"k":"n","t":"数字の泡が、提灯の前で弾けた。胴を突いたときの、倍ちかい。"},{"k":"n","t":"弱点だ。"},{"k":"n","t":"灯喰いが、怒ったように尾を振った。"},{"k":"n","t":"千歳さんの盾が、その前に立った。鈍い音。水が、重く揺れる。"},{"k":"d","t":"「38」"},{"k":"n","t":"赤い数字が、千歳さんの上で小さく弾けた。それだけだった。九十九の盾の前では、あの尾も、ただの波だった。"},{"k":"d","t":"「来るよ、ルカ。提灯が暗くなる」"},{"k":"n","t":"一拍半。"},{"k":"n","t":"僕は横へ跳んだ。顎が、空を噛む。"},{"k":"n","t":"跳んだ先で、ノアのランタンの光が待っていた。"},{"k":"d","t":"「はい、ルカくん」"},{"k":"n","t":"白い炎が、僕の泡殻を包む。"},{"k":"d","t":"「2,104」"},{"k":"n","t":"緑の数字が、大きく弾けた。"},{"k":"n","t":"HPのゲージが、一瞬で端まで満ちた。満ちて、余った。僕のHPは410しかない。回復量は、その五倍だった。"},{"k":"d","t":"「……多すぎませんか」"},{"k":"d","t":"「ごめん、加減が苦手で」"},{"k":"n","t":"ノアは笑った。灯守Lv72の光は、僕の泡殻には大きすぎるらしい。"},{"k":"n","t":"この演出は、ちょっと気持ちよすぎる、と思った。"},{"k":"break"},{"k":"s","t":"【灯喰い　HP 1,640】"},{"k":"n","t":"作戦は、回りはじめていた。"},{"k":"n","t":"カゲロウが偽物の灯りを灯す。灯喰いが食べる。空振りの腹で、提灯が光る。僕が突く。千歳さんが尾を受け、ノアが割れかけた泡を戻す。"},{"k":"d","t":"「107」「121」「CRITICAL　172」"},{"k":"n","t":"提灯の前で、金色の泡が大きく弾けた。"},{"k":"s","t":"【灯喰い　HP 1,240】"},{"k":"n","t":"灯喰いが、急に向きを変えた。"},{"k":"n","t":"偽物の灯りでも、祭壇でもない。琥珀の目が見ていたのは、ノアのランタンだった。"},{"k":"n","t":"白い炎。この礼拝堂でいちばん強い灯り。"},{"k":"d","t":"「ノア、下がって！」"},{"k":"n","t":"提灯が、暗くなる。"},{"k":"n","t":"一拍半より、早かった。学習している。"},{"k":"n","t":"顎がひらいた。ノアは動かなかった。ランタンを胸に抱いたまま、目だけを大きくして。"},{"k":"n","t":"その前に、真鍮の兜が割りこんだ。"},{"k":"d","t":"「させないよ」"},{"k":"n","t":"千歳さんの盾が、顎ごと灯喰いを押し戻した。重い音が、礼拝堂の柱を震わせる。"},{"k":"d","t":"「211」"},{"k":"n","t":"赤い数字。千歳さんの上で弾けた、今夜いちばん大きな数字だった。それでも、あの人の足は一歩も下がらなかった。"},{"k":"d","t":"「……ありがと、千歳さん」"},{"k":"d","t":"「灯りを守るのが、潜騎士の仕事さ」"},{"k":"d","t":"「ルカさん、右です！」"},{"k":"n","t":"カゲロウの声だった。けれど、言葉の置き方が違った。丁寧で、少し硬い。"},{"k":"d","t":"「尾が、右から。……次は、提灯が光ります」"},{"k":"n","t":"言われたとおりに、尾が来た。僕は左へ逃げた。"},{"k":"n","t":"視界の隅で、時計が【2:30】に変わっていた。さっきまでの「ほな、いくで」と、同じ口だった。戦いのさなかに、カゲロウの中の誰かが、入れ替わったみたいだった。"},{"k":"n","t":"考えている暇は、なかった。"},{"k":"n","t":"拍子がある、と思った。"},{"k":"n","t":"食べる。光る。突く。受ける。戻す。"},{"k":"n","t":"四人の動きが、一つの曲の小節みたいに繰り返される。そこに、灯喰いの腹の底の歌が、かすかに重なっていた。"},{"k":"n","t":"ウタの歌は、少しずつ大きくなっていた。"},{"k":"n","t":"提灯が光るたびに、その中で、透きとおった何かが揺れるのが見えた。溜めこまれた灯りの真ん中に、ひときわ澄んだ光が一つ。"},{"k":"d","t":"「ウタ！」"},{"k":"n","t":"呼んだ。"},{"k":"n","t":"提灯の中の光が、揺れた。"},{"k":"n","t":"歌の拍子が、変わった。"},{"k":"n","t":"六つの音の、終わりのない旋律。それが、僕たちの小節に合わせて、拍を刻みはじめた。"},{"k":"n","t":"食べる。光る。――ラ、と高い音。突く。――下がる音。受ける。戻す。――また上がる。"},{"k":"n","t":"腹の中から、ウタが、こっちの曲に入ってきた。"},{"k":"d","t":"「……合いました」"},{"k":"n","t":"カゲロウが、小さくつぶやいた。"},{"k":"n","t":"千歳さんの盾が、拍子に合わせて鳴る。ノアのランタンが、拍子に合わせて明滅する。僕の銛が、拍子の頭を打つ。"},{"k":"n","t":"四人と、腹の中の一人。"},{"k":"s","t":"【連携条件を満たしました】"},{"k":"s","t":"【連携技「潮騒銛」】"},{"k":"n","t":"視界に、知らない名前が灯った。"},{"k":"n","t":"千歳さんが盾で灯喰いの顎を押しあげる。カゲロウの泡が三つ、提灯のまわりで同時に弾ける。ノアの光が、僕の銛の穂先に集まる。"},{"k":"n","t":"ウタの歌が、いちばん高い音に届いた。"},{"k":"n","t":"その一拍に、僕は銛を突きだした。"},{"k":"break"},{"k":"d","t":"「1,280」"},{"k":"n","t":"四桁の数字が、提灯の真ん中で、ふくらんだ。"},{"k":"n","t":"金と、白と、琥珀と、翠。四つの色の泡が重なって、一つの大きな虹の泡になって――"},{"k":"n","t":"弾けた。"},{"k":"n","t":"潮が引くときの、あの長い音がした。浜を洗う波が、いっせいに砂を鳴らすような。"},{"k":"n","t":"四人ぶんの力が、一つの数字になっていた。誰がいくつ足したのかは、どこにも書いていない。"},{"k":"n","t":"一人では、決して出ない数字だった。"},{"k":"s","t":"【灯喰い　HP 0】"},{"k":"n","t":"提灯が、割れた。"},{"k":"n","t":"中から、光があふれた。"},{"k":"n","t":"何十もの灯りが、琥珀色の炎の形のまま、いっせいに外へ流れだした。糸を引くように細く、それから、ふっと元の形に戻って、祭壇へ帰っていく。"},{"k":"s","t":"【祭壇の灯り　18 → 40】"},{"k":"n","t":"灯りが燭台に一つずつ戻るたびに、礼拝堂が明るくなる。"},{"k":"n","t":"けれど、白くなった珊瑚は、白いままだった。"},{"k":"n","t":"色は、戻らなかった。灯りが帰ってきても、一度忘れられた言葉は、もう流れない。"},{"k":"n","t":"それでも、白い森は、灯りに照らされて、少しだけ温かそうに見えた。"},{"k":"n","t":"戻ってきた灯りの一つが、僕の目の前で揺れていた。"},{"k":"n","t":"炎の芯に、細い文字。"},{"k":"s","t":"〈ここで待ってる〉"},{"k":"n","t":"前に、灯喰いの口へ吸いこまれていくのを見た、あの一行だった。"},{"k":"n","t":"帰ってきたのだ。誰が、誰を待っていたのかは分からない。それでも、その言葉は、元の燭台に戻って、また同じ場所で灯りはじめた。"},{"k":"n","t":"そして、最後に、いちばん澄んだ光が、提灯の殻からこぼれた。"},{"k":"n","t":"透きとおった体。四角い欠片の衣。長い袖が、触手のように光をひいて揺れる。"},{"k":"d","t":"「……ルカ」"},{"k":"n","t":"ウタだった。"},{"k":"n","t":"泡殻を持たない深民の体は、どこも欠けていなかった。ただ、少しだけ、前より光が強い気がした。"},{"k":"d","t":"「歌、聞こえてた？」"},{"k":"d","t":"「聞こえてた」"},{"k":"d","t":"「よかった」"},{"k":"n","t":"ウタは、僕の泡殻にぴたりとくっついた。"},{"k":"d","t":"「ずっと、暗かった。でも、ルカの数字が弾ける音が、外から聞こえたの。ぱちん、ぱちんって」"},{"k":"n","t":"頭上の名札が、一瞬だけ、また薄くなった気がした。"},{"k":"n","t":"浅瀬のときと同じ。ほかの誰に呼ばれても起きなかった、あの揺れ。"},{"k":"n","t":"すぐに、元に戻った。"},{"k":"break"},{"k":"n","t":"灯喰いのほどけたあとに、金色の泡がいくつも浮かんでいた。"},{"k":"n","t":"ファンファーレが鳴った。"},{"k":"s","t":"【LEVEL UP!】×3　Lv 8 → Lv 11"},{"k":"n","t":"PRS 90 → 120"},{"k":"n","t":"ウタが、拍子に合わせて手を叩いた。"},{"k":"n","t":"そのとき、ウタの前に、透明な板がひとつひらいた。"},{"k":"s","t":"【深民「ウタ」は、ジョブを選ぶことができます】"},{"k":"n","t":"六つの結晶の小さな影が、板の上で回っていた。"},{"k":"n","t":"ウタは、迷わなかった。"},{"k":"n","t":"指が、青い結晶の影に触れる。"},{"k":"s","t":"【ウタ　歌潮士 Lv 1】"},{"k":"s","t":"【深民「ウタ」がパーティに加わりました】"},{"k":"s","t":"〈パーティ：？？？／ウタ／ノア／カゲロウ／千歳〉"},{"k":"d","t":"「ゲストじゃ、なくなった」"},{"k":"n","t":"ウタは、自分の名前を見上げた。それから、僕の【？？？】の隣にある、その二文字を、指でそっとなぞった。"},{"k":"d","t":"「歌で、だれかの役に立てるなら。わたし、それがいい」"},{"k":"n","t":"自分で選んだのだ、と思った。誰に言われたのでもなく。"},{"k":"break"},{"k":"d","t":"「ルカさん、何か落ちています」"},{"k":"n","t":"カゲロウが、祭壇の下を指さした。"},{"k":"n","t":"灯喰いのほどけた場所に、紙のようなものが一枚、沈んでいた。"},{"k":"n","t":"拾いあげる。"},{"k":"n","t":"チケットだった。"},{"k":"n","t":"ひどく色褪せている。角は丸く擦りきれて、印刷はほとんど白く飛んでいた。それでも、何行かは読めた。"},{"k":"n","t":"＿＿＿　最終夜イベント　入場券"},{"k":"n","t":"地名のところだけが、白い。ウタの「ようこそ」と同じように。"},{"k":"n","t":"僕は、その文字を見つめた。"},{"k":"n","t":"地名ではなく、文字の形を。"},{"k":"n","t":"横画の終わりが、少しだけ丸い。払いが、水に溶けるように細くなる。夜の画面でも読めるように、ほんの少しだけ字間をあけた、明朝体。"},{"k":"n","t":"知っている。"},{"k":"n","t":"この書体の見本帳を、何十冊もめくった夜を、僕は覚えている。"},{"k":"n","t":"そのチケットの書体は、七年前に僕が自分で選んだものだった。"}]},{"id":"ep10","act":null,"title":"第10話　三人で一人","paras":[{"k":"n","t":"チケットのことは、誰にも言えなかった。"},{"k":"n","t":"言葉にした途端、何かが確定してしまう気がした。差出人の欄を見なかった、あの夜と同じように。"},{"k":"n","t":"僕はチケットを泡に包んで、持ち物の奥にしまった。"},{"k":"n","t":"そして、潜った。"},{"k":"s","t":"【深度 -1,000m】"},{"k":"n","t":"それからの夜は、たぶん、この海でいちばん楽しい日々だった。"},{"k":"break"},{"k":"n","t":"狩った。"},{"k":"n","t":"灯台を出て、群青のさらに下へ。光る烏賊の群れ、骨だけで泳ぐ魚、砂の中で眠る巨大な二枚貝。"},{"k":"d","t":"「ルカ、右から三匹！」"},{"k":"n","t":"ウタの歌が、僕たちの足を速くする。今度は、効果元の欄に、ちゃんと名前が入っていた。"},{"k":"s","t":"【SPD +8％（効果元：ウタ／潮の歌）】"},{"k":"n","t":"空欄だったところに、彼女の名前がある。それだけで、少しうれしかった。"},{"k":"n","t":"交易もした。カゲロウの泡の束から、光る石を買い、潮の地図を売る。泡貨は、貯めずに使う。贈れば一日、弾けない。灯台では、誰かが誰かに、毎晩少しずつ泡貨を贈っていた。"},{"k":"n","t":"昼間は、東京で泡を数えた。"},{"k":"n","t":"目が覚めるとすぐ、メモ帳に丸を並べる。○ 光る烏賊は左に逃げる。○ カゲロウの温かい泡は、少ししょっぱい。○ 千歳さんは、兜をとらない。"},{"k":"n","t":"丸の数は、夜ごとに増えていった。ほどけていく記憶より、増えていく記憶のほうが多くなった。"},{"k":"n","t":"仕事を失ってから、初めてのことだった。"},{"k":"n","t":"ジョブも試した。"},{"k":"n","t":"一晩だけ、銛を置いて、灯守になってみた。"},{"k":"d","t":"「ランタンはね、胸の前で持つの。自分の心臓の高さ」"},{"k":"n","t":"ノアが教えてくれた。"},{"k":"n","t":"僕のランタンの光は、ノアのものよりずっと小さかった。マッチを一本擦ったくらいの、頼りない灯り。それでも、暗い岩陰を照らすと、隠れていた小魚がいっせいに逃げていった。"},{"k":"s","t":"【アビリティ「微光」を習得しました】"},{"k":"n","t":"小さな灯りを一つ、ともすだけの力。回復量は、ほとんどない。"},{"k":"n","t":"それでも、手放したくないと思った。"},{"k":"n","t":"銛撃士に戻るとき、画面が一つひらいた。"},{"k":"s","t":"【アビリティ持ち越し】"},{"k":"n","t":"銛撃士　枠 1／1：微光（灯守）"},{"k":"n","t":"覚えた力のうち、一つだけを次のジョブへ連れていける。"},{"k":"n","t":"設計者なら、ここは一番強いアビリティを選ばせたい画面だ。迷わせて、組み合わせを考えさせて、楽しませる。"},{"k":"n","t":"僕は、いちばん弱い光を選んだ。"},{"k":"d","t":"「いいね、それ」"},{"k":"n","t":"ノアが言った。理由は訊かなかった。"},{"k":"break"},{"k":"n","t":"夜を重ねるたびに、泡殻が厚くなっていった。"},{"k":"n","t":"ある夜の終わり、深度2,000mの岩棚で、それはまとめてやってきた。"},{"k":"n","t":"ファンファーレが、五回ぶん、ひとつながりに鳴った。金色の泡が、群青の中に滝のように降る。"},{"k":"s","t":"【LEVEL UP!】×5　Lv 11 → Lv 16"},{"k":"n","t":"PRS 120 → 170　FRG 18 → 20"},{"k":"d","t":"「わあ」"},{"k":"n","t":"ウタが、降ってくる金色に手を伸ばした。"},{"k":"d","t":"「ルカ、五つも光った」"},{"k":"d","t":"「五つも光ったね」"},{"k":"n","t":"まとめて鳴るファンファーレは、一回ずつより、少しだけ照れくさかった。"},{"k":"s","t":"【深度 -2,000m】"},{"k":"s","t":"【圧損　−15／分】"},{"k":"n","t":"要求は200。僕のPRSは170。足りない30の、半分ずつ。"},{"k":"n","t":"前より痛い。それでも、泡殻はきしむだけで、潰れはしない。このくらいの不足なら、一人でも潜れる。"},{"k":"n","t":"僕たちは、岩棚の上で休むことにした。"},{"k":"n","t":"ウタは、千歳さんの隣にちょこんと座って、新しく覚えた潮の歌を口ずさんでいた。"},{"k":"n","t":"六つの音の旋律とは、別の歌だ。歌潮士の歌は、ちゃんと始まって、ちゃんと終わる。"},{"k":"d","t":"「ウタちゃん、上手になったねえ」"},{"k":"d","t":"「でも、前の歌のほうが、すき」"},{"k":"d","t":"「終わらないほうかい」"},{"k":"d","t":"「うん。終わらないほう」"},{"k":"n","t":"千歳さんは、兜の中で小さく笑ったようだった。"},{"k":"d","t":"「終わらない歌は、いつか誰かに、終わらせてもらうといいよ」"},{"k":"n","t":"ウタは首をかしげた。僕も、その言葉の意味は分からなかった。"},{"k":"break"},{"k":"n","t":"カゲロウが、泡の束から温かい泡を配っていた。"},{"k":"d","t":"「ほい、兄ちゃん。嬢ちゃんも。ノアちゃんは甘いほうな」"},{"k":"n","t":"関西の言葉。陽気で、少し早口。"},{"k":"n","t":"視界の隅の、現実の時刻を見た。"},{"k":"s","t":"【2:29】"},{"k":"d","t":"「カゲロウさん」"},{"k":"d","t":"「なんや」"},{"k":"d","t":"「前から、訊きたかったんです。話し方が、ときどき――」"},{"k":"d","t":"「ああ、それな」"},{"k":"n","t":"カゲロウは、笑って頭をかいた。"},{"k":"d","t":"「隠しとるつもりは、なかってんけどな。わしらは――」"},{"k":"s","t":"【2:30】"},{"k":"n","t":"カゲロウの動きが、一拍、止まった。"},{"k":"n","t":"まばたき一回ぶんの、空白。"},{"k":"n","t":"それから、同じ口が、まるで違う置き方で言葉を続けた。"},{"k":"d","t":"「――わたしたちは、三人なんです」"},{"k":"n","t":"丁寧で、少し硬い声。語尾を一つずつ確かめるような。"},{"k":"d","t":"「さっきまで話していたのは、湊くんです。大阪の高校生で、今、眠りが浅くなったところ。続きは、わたしが話しますね」"},{"k":"d","t":"「……あなたは」"},{"k":"d","t":"「ジウといいます。ソウルで、介護の仕事をしています。今夜は夜勤で、二時半から五時まで、仮眠の時間なんです」"},{"k":"n","t":"ジウさんは、少し恥ずかしそうに笑った。同じ顔なのに、笑い方まで違った。"},{"k":"d","t":"「夢潜行は、眠っているあいだしかできませんよね。三人とも、長くは眠れないんです。湊くんは受験生で、寝つくのが零時。わたしは、仮眠の二時間半。もう一人は、ラゴスにいて」"},{"k":"d","t":"「ラゴス」"},{"k":"d","t":"「ナイジェリアです。日本との時差は、八時間。向こうの夜九時が、こちらの朝五時」"},{"k":"n","t":"零時から二時半。二時半から五時。五時から先。"},{"k":"n","t":"三人の眠りが、リレーのバトンみたいに、一つの体を夜の向こうまで運んでいく。"},{"k":"d","t":"「一人じゃ、ひと晩もたないんです。でも、三人なら、朝まで灯りをつけておける」"},{"k":"n","t":"ジウさんは、泡の束を見上げた。"},{"k":"d","t":"「だから、この子を、家族って呼んでいます」"},{"k":"break"},{"k":"n","t":"僕は、ずっと気になっていたことを訊いた。"},{"k":"d","t":"「名札が、三つに切り替わるのは」"},{"k":"d","t":"「三人の登録名を、順番に映しているんです。カタカナが湊くん、漢字がわたし、ローマ字がトゥンデ。いちばん最初に名前をつけたのが、わたしで」"},{"k":"d","t":"「だから、ウタには漢字に見えた？」"},{"k":"d","t":"「わたしにも、理由は分からないんです。深民の子には、いちばん奥にしまわれた最初の字が、そのまま見えてしまうのかもしれません」"},{"k":"n","t":"ウタが、こくこくとうなずいた。"},{"k":"d","t":"「虫の字、二つ。ずっと、もぞもぞしてる」"},{"k":"n","t":"ゆっくり侵されていく名前と、規則正しく交代する名前。浅瀬で感じたあの違いは、間違っていなかった。"},{"k":"n","t":"カゲロウの名前は、壊れていなかった。最初から、三つあったのだ。"},{"k":"d","t":"「泡身代わりも、三体までしか出せないんです」"},{"k":"n","t":"ジウさんが、泡の束から三つの泡を浮かべてみせた。小さな人の形をした泡が、三つ並んで、ぺこりと頭を下げる。"},{"k":"s","t":"【泡身代わり　最大 3体】"},{"k":"d","t":"「一人一体、みたいで、かわいいでしょう」"},{"k":"n","t":"ジウさんは、コートの内ポケットから、厚い帳面を取りだした。"},{"k":"d","t":"「これは、三人の交易帳です。誰が、いつ、何を売って、何を買ったか。それぞれ、自分の時間のぶんしか書けないので、ページごとに字が違うんです」"},{"k":"n","t":"めくると、本当に三種類の字が並んでいた。勢いのある崩し字と、几帳面な楷書と、英語の走り書き。"},{"k":"d","t":"「読み合わせないと、三人とも、全部は分からない。……それが、ちょうどいいんです」"},{"k":"n","t":"ジウさんは、帳面を閉じた。"},{"k":"break"},{"k":"n","t":"五時になった。"},{"k":"s","t":"【5:00】"},{"k":"n","t":"カゲロウが、また一拍、止まった。"},{"k":"d","t":"「――Good morning, everyone! いや、こっちは夜か。ハハ！」"},{"k":"n","t":"明るい声が、岩棚に響いた。"},{"k":"d","t":"「トゥンデだよ。ラゴスは今、夜の九時。ジウから聞いた？　オーケー、じゃあ自己紹介は省略！」"},{"k":"n","t":"トゥンデさんは、僕の頭上の名札を見上げた。"},{"k":"d","t":"「キミの名前、クールだね。？？？。三人で一人の僕らより、ミステリアス」"},{"k":"d","t":"「直し方、知りませんか」"},{"k":"d","t":"「知らない。でも、名前がいくつあっても、ひとつもなくても、ここではみんな家族さ」"},{"k":"n","t":"僕は、笑った。三人分の慰めを、一晩でもらった気がした。"},{"k":"n","t":"ノアも、笑っていた。"},{"k":"n","t":"ランタンを膝に抱えて、白い炎の向こうで、肩を揺らして。"},{"k":"n","t":"その姿が、一瞬、ちらついた。"},{"k":"n","t":"電波の悪い映像みたいに、輪郭が二重になって、すぐに戻る。"},{"k":"n","t":"パーティ表示の、ノアの欄。その最後の数字が、音もなく書き換わった。"},{"k":"s","t":"【FRG 88 → 89】"},{"k":"n","t":"僕は、自分のFRGが上がった夜を思い出していた。泡が割れて、礼拝堂で目を覚まして。壊れたぶんだけ、脆く、強くなる。"},{"k":"n","t":"ノアは、今夜一度も割れていない。"},{"k":"n","t":"僕の声は、思っていたより小さかった。"},{"k":"d","t":"「……破泡してないのに、なんで上がるの？」"}]},{"id":"ep11","act":null,"title":"第11話　海女の深さ","paras":[{"k":"n","t":"ノアは、あの夜の問いに答えなかった。"},{"k":"d","t":"「さあ。この海、ときどき変なんだよ」"},{"k":"n","t":"そう笑って、いつもどおり3時40分ちょうどに落ちていった。"},{"k":"n","t":"だから僕は、問いを泡に包んで、メモ帳の丸の一つにした。○ ノアのFRG、89。割れていないのに。"},{"k":"n","t":"そして、さらに下へ潜った。"},{"k":"s","t":"【深度 -2,000m】"},{"k":"break"},{"k":"n","t":"群青は、もう夜の色に近かった。"},{"k":"n","t":"頭上の真珠白は、とうに見えない。光珊瑚の翠だけが、岩壁のところどころで、灯籠のように灯っている。"},{"k":"n","t":"この深さの魚は、硬く、重かった。銛が通るたびに、数字の泡が大きくふくらむ。"},{"k":"n","t":"一晩目は、灯台のまわりで、光る烏賊を追った。烏賊は左に逃げる。メモ帳の丸のとおりだった。"},{"k":"n","t":"二晩目は、千歳さんの盾の陰から、岩に擬態した蟹を突いた。殻の継ぎ目にだけ、数字が深く入る。"},{"k":"n","t":"三晩目は、ウタの歌の拍子で突いた。拍の頭で突くと、泡が一回り大きく弾ける。気のせいかもしれない。けれど、気のせいだとしても、気持ちのいい気のせいだった。"},{"k":"n","t":"その夜の終わりに、ファンファーレが鳴った。"},{"k":"s","t":"【LEVEL UP!】×5　Lv 16 → Lv 21"},{"k":"n","t":"PRS 170 → 220　FRG 20 → 21"},{"k":"n","t":"五つの金色が、深い群青の中で、星みたいに弾けた。"},{"k":"d","t":"「また五つ」"},{"k":"n","t":"ウタが、指を折って数えた。"},{"k":"d","t":"「ルカ、二十一」"},{"k":"d","t":"「二十一だね」"},{"k":"n","t":"二十一。灯台で初めて会った夜のノアの、三分の一にも届かない。千歳さんの、五分の一と少し。"},{"k":"n","t":"それでも、数字は確かに積もっていた。"},{"k":"break"},{"k":"d","t":"「ここから先は、あたしのそばを離れるんじゃないよ」"},{"k":"n","t":"深度2,500mを過ぎたあたりで、千歳さんが言った。"},{"k":"n","t":"千歳さんの鎧から、淡い光の輪がひろがっている。潜騎士の水圧分担。輪の内側にいる仲間の泡殻を、千歳さんの泡殻が外から支える。"},{"k":"s","t":"【深度 -2,500m】"},{"k":"s","t":"【要求PRS 250／現在 220（不足 30）】"},{"k":"s","t":"【圧損　−15／分】"},{"k":"n","t":"足りないぶんの、半分ずつ。式は、もう体が覚えていた。"},{"k":"n","t":"この深さなら、まだ一人でも潜れる。輪の外でも、削られるだけで済む。"},{"k":"n","t":"なのに、千歳さんは僕を輪の中に置いた。"},{"k":"n","t":"僕は、頭の中で線を引いた。"},{"k":"n","t":"自分のPRSの二割に、10を足す。220の二割は44。足して、54。足りないぶんが54を超えたら、泡殻は削られるのではなく、潰れる。"},{"k":"n","t":"要求が274。深度にして、2,740m。"},{"k":"n","t":"そこが、今の僕の底だ。"},{"k":"n","t":"輪の中で、深度計の数字が増えていく。2,600。2,700。2,740を越えた瞬間も、泡殻は鳴らなかった。千歳さんが、外から支えている。"},{"k":"s","t":"【深度 -2,900m】"},{"k":"s","t":"【圧損　−35／分】"},{"k":"d","t":"「どうしてですか、って顔をしてるね」"},{"k":"n","t":"千歳さんが、兜の奥で笑った。"},{"k":"d","t":"「やってみな。ちょっとだけ」"},{"k":"n","t":"光の輪の縁から、僕は一歩だけ外へ出た。"},{"k":"n","t":"泡殻が、悲鳴をあげた。"},{"k":"n","t":"きしむのではない。押しつぶされる。膜が内側へたわみ、虹色の干渉が、ぎゅっと一点に寄せられていく。"},{"k":"s","t":"【警告：圧壊ライン超過】"},{"k":"s","t":"【要求PRS 290／現在 220（不足 70／圧壊ライン 54）】"},{"k":"n","t":"HPのゲージが、目に見えて縮んでいく。一分ごとではない。一秒ごとに。"},{"k":"d","t":"「戻りな」"},{"k":"n","t":"千歳さんの手が、僕の腕をつかんで、輪の中へ引き戻した。"},{"k":"n","t":"泡殻が、ふっと元の形に戻った。"},{"k":"s","t":"【水圧分担：千歳】"},{"k":"s","t":"【圧損　−35／分】"},{"k":"n","t":"HPは、まだ減っている。不足は70のまま、一分に35ずつ。けれど、潰れはしない。"},{"k":"d","t":"「分かったかい」"},{"k":"d","t":"「……分かりました」"},{"k":"n","t":"足りないぶんが少しなら、痛いだけで済む。足りなさすぎると、泡は形を保てない。その境目が、圧壊ライン。"},{"k":"n","t":"PRSが大きいほど、許される不足も大きくなる。弱いうちは、ほんの少しの不足でも潰れる。"},{"k":"n","t":"よくできた線だと思った。そして、ひどく正直な線だとも。"},{"k":"d","t":"「あたしの輪の中なら、要求が1,100まではもつ。あたしのPRSが1,100だからね」"},{"k":"d","t":"「千歳さんは、それ以上は」"},{"k":"d","t":"「行けないよ」"},{"k":"n","t":"千歳さんは、あっさりと言った。"},{"k":"d","t":"「Lv99でも、PRSは1,100が上限さ。海の底より深くは、誰も潜れないようにできてる」"},{"k":"n","t":"現実の海でいちばん深い場所が、一万一千メートル。"},{"k":"n","t":"この海の水圧は、本物の海と、同じ形をしているのだ。"},{"k":"break"},{"k":"n","t":"岩棚で、少し休んだ。"},{"k":"n","t":"千歳さんは、珍しく兜の窓を少しあけて、群青の向こうを眺めていた。"},{"k":"d","t":"「千歳さんは、現実でも、潜ってるんですか」"},{"k":"d","t":"「潜ってるよ。房総の海でね。今も現役の海女さ」"},{"k":"d","t":"「海女」"},{"k":"d","t":"「七十四になっても、まだ潜ってる。体じゃ、もう二十メートルがせいぜいだけどね」"},{"k":"n","t":"千歳さんは、窓の向こうで笑った。"},{"k":"d","t":"「ここなら、体じゃ行けない深さまで行ける。それが、うれしくてね」"},{"k":"d","t":"「現実の海は、どうやって潜るんですか。機械とか」"},{"k":"d","t":"「機械は持たないよ。何ひとつ」"},{"k":"n","t":"ウタが、千歳さんの膝に寄ってきた。"},{"k":"d","t":"「本物の海って、どんな色？」"},{"k":"d","t":"「朝は、銀色。昼は、緑。夕方になると、金色が一枚かぶさる」"},{"k":"n","t":"千歳さんは、指で水をなでるようにした。"},{"k":"d","t":"「それから、冷たい。ここの海より、ずっと冷たいよ。冷たくて、しょっぱくて、ちゃんと痛い」"},{"k":"d","t":"「痛いの、いいこと？」"},{"k":"d","t":"「いいことさ。生きてるうちは、海は痛いもんだよ」"},{"k":"n","t":"ウタは、自分の指先を見た。透きとおった指先には、冷たさも痛みもない。それでも、何かを確かめるように、きゅっと握った。"},{"k":"n","t":"何でもないことのように、千歳さんは言った。"},{"k":"d","t":"「時計も、電話も。身につけるのは、磯着と、眼鏡と、腰の鉤だけ」"},{"k":"d","t":"「どうしてですか」"},{"k":"d","t":"「さあねえ。昔からそうしてるから、っていうのもあるけど」"},{"k":"n","t":"千歳さんは、少し考えるように首をかしげた。"},{"k":"d","t":"「機械を持ってると、海に名前を呼ばれる気がしてね。持ってなければ、海はあたしを、ただの生きもんとして通してくれる」"},{"k":"n","t":"名前を呼ばれる。"},{"k":"n","t":"頭上の【？？？】が、少しだけ重くなった気がした。"},{"k":"break"},{"k":"d","t":"「そうだ。あんたに、一つ教えとこう」"},{"k":"n","t":"千歳さんは、唇をすぼめた。"},{"k":"n","t":"ひゅう、と、細く高い音が鳴った。"},{"k":"n","t":"口笛とは違う。息を長く吐ききったあとの、喉の奥から抜けるような、かすれた音。群青の中を、まっすぐ遠くまで渡っていく。"},{"k":"d","t":"「磯笛さ。海女が水から上がったとき、吸う前に、こうやって吐くんだ。胸の中の古い息を、ぜんぶ」"},{"k":"d","t":"「どうやるんですか」"},{"k":"d","t":"「唇を細くして、肺の底から。……違う違う、口笛になってる」"},{"k":"n","t":"ひゅ、と僕の音は途中で切れた。もう一度。ひゅう、と、少しだけ長く。"},{"k":"d","t":"「そうそう。それが、生きて上がってきたって合図になる」"},{"k":"n","t":"ウタが、目を輝かせて真似をした。"},{"k":"n","t":"ウタの磯笛は、旋律になった。六つの音の、最初の一つ。"},{"k":"d","t":"「ウタちゃんのは、歌になっちまうね」"},{"k":"n","t":"千歳さんは、笑った。"},{"k":"break"},{"k":"n","t":"ステータスを見せてもらった。"},{"k":"s","t":"【千歳　Lv 99　潜騎士】"},{"k":"s","t":"【HP 9,999／9,999 MAX★】"},{"k":"s","t":"【PRS 1,100 MAX★】"},{"k":"n","t":"小さな星の印が、二つの数字の横で光っていた。"},{"k":"d","t":"「これは」"},{"k":"d","t":"「上限さ。それ以上は、表示できないって印」"},{"k":"d","t":"「本当は、もっとあるんですか」"},{"k":"d","t":"「さあね。数えてくれるもんがいないからね」"},{"k":"n","t":"千歳さんは、あっけらかんと笑った。"},{"k":"d","t":"「9,999で止まってるだけさ。止まってるって、ちゃんと書いてあるだろう。正直なもんだよ」"},{"k":"n","t":"正直な数字。"},{"k":"n","t":"上限で止まっていることを、隠さない表示。僕なら、たぶんそう作る。止まっていることまで含めて、数字は本当のことを言うべきだから。"},{"k":"d","t":"「ねえ、ルカ」"},{"k":"n","t":"千歳さんは、兜の窓を閉めた。"},{"k":"d","t":"「もし、本物の海で何かあったら、あたしが行くよ」"},{"k":"d","t":"「本物の海で、って」"},{"k":"d","t":"「言ってみただけさ。年寄りは、言ってみたくなるんだよ」"},{"k":"n","t":"冗談のような声だった。けれど、兜の奥の目は、笑っていなかった気がする。"},{"k":"break"},{"k":"n","t":"深度計は、-2,900mのまま止まっていた。"},{"k":"n","t":"あと100m。そこから先が、沈都層だと灯台で聞いた。"},{"k":"n","t":"僕たちは、千歳さんの輪の中で、さらに下を見た。"},{"k":"n","t":"岩棚の縁から、群青の闇が、まっすぐ下へ落ちていく。"},{"k":"n","t":"その底に、何かがあった。"},{"k":"n","t":"光だった。"},{"k":"n","t":"一つではない。何十、何百、何千。小さな、四角い、琥珀色の光。規則正しく並んで、ところどころが欠けている。"},{"k":"n","t":"窓だ、と思った。"},{"k":"n","t":"夜の街を、高いところから見下ろしたときの、あの光り方。"},{"k":"n","t":"足元のはるか下に、何千もの窓が灯る“街”の光が見えた。"}]},{"id":"ep12","act":null,"title":"第12話　深度3,000m／名前を盗んだ僕","paras":[{"k":"n","t":"眠る前、浅瀬モードの隅に、見慣れた数字が出ていた。"},{"k":"s","t":"【実質化率 1.4％】"},{"k":"n","t":"0.8％だったはずだ。いつ1％を越えたのか、僕は覚えていなかった。"},{"k":"n","t":"覚えていないことが、少しだけ怖かった。"},{"k":"break"},{"k":"s","t":"【深度 -2,900m】"},{"k":"n","t":"岩棚の縁で、千歳さんが籠手を外した。"},{"k":"n","t":"その手のひらに、小さな殻が載っていた。巻き貝を半分に割ったような、乳白色の殻。内側が、真珠みたいに光っている。"},{"k":"d","t":"「持っていきな」"},{"k":"s","t":"【耐圧殻：PRS +70】"},{"k":"d","t":"「これ、千歳さんのじゃ」"},{"k":"d","t":"「昔のさ。もう要らない」"},{"k":"n","t":"千歳さんは、僕の胸の泡殻に、殻をそっと押しあてた。殻は膜に溶けて、見えなくなった。"},{"k":"s","t":"【PRS 220 → 290】"},{"k":"d","t":"「ここから先は、自分の足でも立てるようにね」"},{"k":"n","t":"この深さに要るのは、290。足りないぶんは、ゼロ。"},{"k":"n","t":"圧損の表示が消えた。輪の外に出ても、泡殻は鳴らなかった。"},{"k":"n","t":"視界の隅の時計は、【1:12】。ノアが落ちるまで、まだ二時間以上ある。カゲロウは、まだ大阪弁だった。"},{"k":"d","t":"「ほな、いよいよ沈都層やな」"},{"k":"break"},{"k":"n","t":"そのとき、下から誰かが上がってきた。"},{"k":"n","t":"白い潜水服。黒い髪。片手に、硝子の穂先の銛。"},{"k":"n","t":"見覚えがありすぎた。"},{"k":"n","t":"毎朝、洗面所の鏡で見ている顔だった。"},{"k":"n","t":"頭上に、名札が浮かんでいる。"},{"k":"s","t":"【ルカ】"},{"k":"n","t":"にじんでいない。欠けてもいない。くっきりとした、正しい二文字。"},{"k":"n","t":"僕の頭上には、今も【？？？】が浮かんでいる。"},{"k":"d","t":"「――その名前、もらったよ」"},{"k":"n","t":"声まで、僕の声だった。"},{"k":"n","t":"最初の夜に、深いところから聞こえた声。あれは、この口から出ていたのだ。"},{"k":"n","t":"夜の海に沈んでいった「ル」と「カ」の泡が、体を持って、僕の前に立っていた。"},{"k":"s","t":"【ルカ　HP 1,520】"},{"k":"n","t":"僕と、同じ数字だった。"},{"k":"break"},{"k":"d","t":"「ノア、下がって！」"},{"k":"n","t":"僕が叫んだのと、同時だった。"},{"k":"d","t":"「ノア、前へ！」"},{"k":"n","t":"同じ声が、反対のことを叫んだ。"},{"k":"n","t":"ノアの足が止まる。どちらを聞けばいいのか、分からない顔で。"},{"k":"d","t":"「千歳さん、右！」"},{"k":"d","t":"「千歳さん、左！」"},{"k":"n","t":"千歳さんの盾が、一瞬、迷った。"},{"k":"n","t":"その隙間に、偽物の銛が滑りこんだ。"},{"k":"d","t":"「267」"},{"k":"n","t":"赤い数字が、僕の上で弾けた。"},{"k":"n","t":"突き返す。"},{"k":"d","t":"「268」「251」"},{"k":"s","t":"【ルカ　HP 1,001】"},{"k":"d","t":"「ルカくん、今戻す！」"},{"k":"n","t":"ノアのランタンが光った。灯守の灯火。温かい光の帯が、まっすぐに伸びて――"},{"k":"n","t":"偽物の胸に吸いこまれた。"},{"k":"d","t":"「2,071」"},{"k":"s","t":"【ルカ　HP 1,520】"},{"k":"n","t":"満タンだった。"},{"k":"d","t":"「え……」"},{"k":"n","t":"ノアの顔から、色が引いた。"},{"k":"n","t":"灯火は、名前で相手を選ぶ。ノアが心の中で「ルカ」と呼んだから、光は【ルカ】の名札へ飛んだ。"},{"k":"n","t":"カゲロウの泡身代わりも、同じだった。「ルカを守れ」と放った泡は、偽物の前でふくらんで、僕の銛を受けとめた。"},{"k":"d","t":"「あかん、全部向こうに行く！」"},{"k":"n","t":"仲間の手が、全部、僕の名前のほうへ流れていく。"},{"k":"n","t":"僕の名前は、もう僕のところにはなかった。"},{"k":"d","t":"「どっちが、ルカだい」"},{"k":"n","t":"千歳さんが、低く言った。責める声ではなかった。本当に、分からないのだ。"},{"k":"n","t":"同じ顔。同じ声。あの夜の僕と同じ、硝子の銛。同じHP。違うのは、頭の上の文字だけ。そして、正しい文字を持っているのは、向こうだった。"},{"k":"n","t":"僕は、答えられなかった。"},{"k":"n","t":"僕が僕だと、どうやって証明すればいいのだろう。名札は【？？？】で、声は写されて、数字まで同じなのに。"},{"k":"n","t":"足元が、すっと冷えた。泡殻の外の水が、内側まで染みてくるような寒さだった。"},{"k":"d","t":"「267」"},{"k":"n","t":"また、赤い数字。"},{"k":"n","t":"偽物は、仲間の名前も呼んだ。ウタを、「案内役#07」と。"},{"k":"n","t":"ウタの体の光が、ふっと揺らいだ。歌が、途切れる。"},{"k":"d","t":"「やめろ」"},{"k":"n","t":"僕の声で、偽物が笑った。"},{"k":"break"},{"k":"d","t":"「267」"},{"k":"n","t":"三度目の赤い数字を見たとき、何かが引っかかった。"},{"k":"n","t":"267。267。267。"},{"k":"n","t":"三回とも、同じだった。"},{"k":"n","t":"僕の攻撃は、毎回ゆらぐ。268、251。式に乱数が入っているからだ。0.9倍から1.1倍。数字が毎回少しずつ違うから、突くたびに、次の数字を待つ楽しみがある。"},{"k":"n","t":"偽物の数字は、ゆらがない。"},{"k":"d","t":"「この数字は、綺麗すぎる」"},{"k":"n","t":"声に出していた。"},{"k":"n","t":"四度目。"},{"k":"d","t":"「267」"},{"k":"n","t":"僕のHPは、残り452。あと二発で、僕が割れる。"},{"k":"n","t":"数字は、全部見えていた。だから、分かった。"},{"k":"n","t":"あいつは、僕の数字を写している。STRも、DEFも、FRG 21まで。けれど、乱数だけは写せない。運は、写せない。"},{"k":"n","t":"そして、もう一つ。"},{"k":"n","t":"あいつの銛は、いつも同じ拍で来る。四拍目の頭。一度も、ずれない。"},{"k":"n","t":"ずれないものは、読める。"},{"k":"d","t":"「ウタ」"},{"k":"n","t":"僕は、偽物ではなく、ウタのほうを向いた。"},{"k":"d","t":"「歌って。僕じゃなくて、ウタの拍で動く。みんなも、僕の声じゃなくて、歌を聞いて」"},{"k":"n","t":"ウタが、顔を上げた。"},{"k":"n","t":"偽物が、口をひらいた。"},{"k":"d","t":"「ウタ――」"},{"k":"n","t":"同じ声。同じ名前。"},{"k":"n","t":"けれど、ウタは振り向かなかった。"},{"k":"d","t":"「ちがう」"},{"k":"n","t":"ウタは、まっすぐ僕を見ていた。"},{"k":"d","t":"「その呼び方、知らない」"},{"k":"n","t":"六つの音が、群青に戻ってきた。"},{"k":"break"},{"k":"n","t":"上がって、少し下がって、また上がる。"},{"k":"n","t":"偽物の銛が、四拍目の頭に来る。僕は、ウタの拍の裏へ、半歩だけずれた。"},{"k":"n","t":"穂先が、僕の泡殻のすぐ横を通りすぎる。"},{"k":"n","t":"空振り。"},{"k":"d","t":"「283」"},{"k":"n","t":"突き返した数字が、金色に近い朱で弾けた。"},{"k":"n","t":"千歳さんの盾が、歌の拍子で鳴る。ノアは、ランタンを下ろした。灯火を、もう誰にも飛ばさない。カゲロウの泡が、歌の休符に合わせて、偽物の視界をふさぐ。"},{"k":"n","t":"僕の声は、使わなかった。偽物が写せるのは、僕の声だけだから。"},{"k":"d","t":"「247」「290」「259」「276」"},{"k":"n","t":"数字が、ゆらぐ。毎回、違う。"},{"k":"n","t":"その違いが、うれしかった。"},{"k":"n","t":"前の仕事で、何度も言われたことがある。乱数なんて、ないほうが公平だと。毎回同じ数字が出れば、誰も損をしない、と。"},{"k":"n","t":"僕は、いつも反対した。毎回同じなら、それはもう、遊びではなく作業だ。次の数字が分からないから、人は銛を引く。ゆらぎは、生きている手ざわりなのだ。"},{"k":"n","t":"その手ざわりが、今、僕を僕にしていた。"},{"k":"s","t":"【ルカ　HP 165】"},{"k":"n","t":"偽物が、こちらを見た。"},{"k":"n","t":"同じ顔。けれど、その目には何も映っていなかった。"},{"k":"d","t":"「ルカ」"},{"k":"n","t":"ウタが、呼んだ。"},{"k":"n","t":"僕は振り向いた。"},{"k":"n","t":"偽物は、振り向かなかった。"},{"k":"n","t":"名札に書かれた名前を、自分のことだと分かっていない。文字列を持っているだけで、呼ばれたことが、一度もないのだ。"},{"k":"n","t":"呼ばれた記憶は、名札には書いていない。"},{"k":"n","t":"僕は銛を引いた。ウタの旋律が、いちばん高い音へ上がっていく。その頂点で。"},{"k":"d","t":"「CRITICAL　417」"},{"k":"n","t":"金色の縁どりの数字が、偽物の胸で、大きく弾けた。"},{"k":"s","t":"【ルカ　HP 0】"},{"k":"break"},{"k":"n","t":"偽物の体が、ほどけはじめた。"},{"k":"n","t":"足先から、泡になっていく。白い潜水服も、黒い髪も、硝子の銛も。"},{"k":"n","t":"最後に残った唇が、僕の耳もとまで流れてきた。"},{"k":"d","t":"「名前は、もうこっちのものだ」"},{"k":"n","t":"僕の声で、偽物はささやいた。"},{"k":"d","t":"「……君は、終わらせ方を知っている」"},{"k":"n","t":"意味を訊く前に、唇は泡になった。"},{"k":"n","t":"ぱちん、と。"},{"k":"n","t":"頭上の【ルカ】の二文字が、群青の上へ昇っていく。消えたのではない。どこかへ、持ち帰られていく。"},{"k":"n","t":"僕の名札は、【？？？】のままだった。"},{"k":"s","t":"【LEVEL UP!】Lv 21 → Lv 22"},{"k":"n","t":"PRS 290 → 300"},{"k":"n","t":"ファンファーレが鳴った。"},{"k":"n","t":"その音を、僕はいつもより長く聞いていた。誰にも写せない、僕の数字の音。"},{"k":"n","t":"？？？　Lv 22　ジョブ：銛撃士"},{"k":"n","t":"HP 1,605　LUX 160　STR 96"},{"k":"n","t":"MAG 22　DEF 70　SPD 104"},{"k":"n","t":"LCK 31　PRS 300　FRG 21"},{"k":"d","t":"「ルカ」"},{"k":"n","t":"ウタが、もう一度呼んだ。"},{"k":"d","t":"「うん」"},{"k":"n","t":"返事をした。それだけで、足りた。"},{"k":"d","t":"「……ごめんね、ルカくん」"},{"k":"n","t":"ノアが、ランタンを胸に抱いたまま言った。"},{"k":"d","t":"「名前で、選んじゃった。いちばん近くにいたのに」"},{"k":"d","t":"「ノアのせいじゃないよ。あいつは、そういうふうに作られてた」"},{"k":"d","t":"「次は、間違えない」"},{"k":"n","t":"ノアは、僕の頭上の【？？？】を見上げた。それから、小さく笑った。"},{"k":"d","t":"「空白のほうを、呼べばいいんだもんね」"},{"k":"break"},{"k":"n","t":"僕たちは、岩棚から降りた。"},{"k":"s","t":"【深度 -3,000m／沈都層】"},{"k":"n","t":"要求PRSは300。僕のPRSも、300。圧損は、ゼロ。"},{"k":"n","t":"境を越えた瞬間、海の音が変わった。浅瀬からずっと鳴っていた、高く澄んだ泡の音が遠のいて、低い弦のような響きが、足元から満ちてくる。"},{"k":"n","t":"光も、変わった。"},{"k":"n","t":"真珠白と翠が、背中のほうへ退いていく。かわりに、琥珀の灯りが、夜の底から立ちのぼってきた。"},{"k":"n","t":"眼下に、街があった。"},{"k":"n","t":"石畳の通り。崩れかけたアーケード。窓という窓に、琥珀の灯りがともっている。誰もいないのに、灯りだけが、まだ誰かを待っているみたいに。"},{"k":"n","t":"街の真ん中に、時計塔のある聖堂が立っていた。緑に光る珊瑚が、尖塔のてっぺんまで絡みついている。"},{"k":"n","t":"時計の針は、十一時十四分で止まっていた。"},{"k":"n","t":"23:14。"},{"k":"n","t":"澪さんの荷物が届いた時刻と、同じだった。"},{"k":"n","t":"ウタが、僕の袖をつかんだ。その指が、小さく震えていた。"},{"k":"n","t":"怖がっているのではなかった。"},{"k":"n","t":"眼下の沈んだ街を見て、ウタが小さく言った。"},{"k":"d","t":"「……ただいま？」"}]},{"id":"ep13","act":"第二幕　沈む","title":"第13話　止まった時計の街","paras":[{"k":"n","t":"ただいま、とウタは言った。"},{"k":"n","t":"疑問符をつけたまま。言った本人が、その言葉の行き先を知らない顔で。"},{"k":"s","t":"【深度 -3,000m／沈都層】"},{"k":"n","t":"僕たちは、街へ降りた。"},{"k":"break"},{"k":"n","t":"石畳に、足がついた。"},{"k":"n","t":"海の底に、地面がある。それだけのことに、体が少し驚いていた。浅瀬からここまで、僕はずっと何かの上に浮かんでいたのだ。"},{"k":"n","t":"通りの両側に、店が並んでいた。"},{"k":"n","t":"パン屋。花屋。古い時計屋。どの店先にも琥珀の灯りがともり、硝子の扉の向こうで、棚がきちんと整えられている。誰もいない。けれど、埃ひとつない。"},{"k":"n","t":"閉店した店ではなかった。開店する直前の店だった。"},{"k":"d","t":"「……なんや、気味悪いな」"},{"k":"n","t":"カゲロウが、小声で言った。湊くんの声だ。視界の隅の時計は、【1:31】。"},{"k":"d","t":"「誰もおらんのに、今から客が来るみたいや」"},{"k":"n","t":"看板を見上げる。"},{"k":"n","t":"どの看板にも、店の名前がなかった。"},{"k":"n","t":"〈＿＿＿ベーカリー〉。〈花の＿＿＿〉。名前のところだけが、白く抜けている。ウタの「ようこそ」と同じ、色のない白だった。"},{"k":"n","t":"抜けた白は、どれも同じ幅をしていた。"},{"k":"n","t":"三文字ぶん。"},{"k":"n","t":"僕の名札の疑問符と、同じ数だった。"},{"k":"n","t":"偶然だと思う。偶然だと思うことにして、僕はそれを、メモ帳の丸にもしないでおこうと決めた。"},{"k":"break"},{"k":"n","t":"通りの先に、アーケードがあった。"},{"k":"n","t":"鉄骨の屋根の下に、色褪せた布が何枚も吊るされている。風はないのに、水の揺れで、ゆっくりと裾が動いていた。"},{"k":"n","t":"WELCOME"},{"k":"n","t":"ウタのまわりを漂っていたのと、同じ布だった。ここでは、何十枚も。"},{"k":"d","t":"「ウタちゃんの布だね」"},{"k":"n","t":"ノアが、ランタンを少し掲げた。白い炎が、布の白をいっそう白く照らす。"},{"k":"n","t":"ウタは答えなかった。袖の欠片をひとつずつ明滅させながら、アーケードの入口に立っていた。"},{"k":"n","t":"そこに、台座が並んでいた。"},{"k":"n","t":"膝ほどの高さの、小さな石の台座。七つ。それぞれに、すり減った番号が彫ってある。"},{"k":"n","t":"#01。#02。#03。"},{"k":"n","t":"六つ目までは、台座の上に何もなかった。七つ目だけ、石の表面が、ほかより少し白くすり減っていた。"},{"k":"n","t":"何千回も、同じ角度で、誰かが立ちつづけた跡だった。"},{"k":"n","t":"ウタは、#07の台座に、そっと片足を乗せた。"},{"k":"n","t":"もう片方の足も。"},{"k":"n","t":"手を広げかけて、止めた。首をかしげる、少し手前で。"},{"k":"n","t":"七秒が過ぎた。"},{"k":"n","t":"ウタは、「ようこそ」と言わなかった。"},{"k":"d","t":"「ここ、ちょうどいい高さ」"},{"k":"n","t":"それだけ言って、台座から降りた。"},{"k":"d","t":"「足が、覚えてるの。でも、わたしは覚えてない」"},{"k":"n","t":"体が覚えていて、名前が覚えていない場所。"},{"k":"n","t":"僕は、自分の頭上の空白のことを考えた。名前を覚えている僕と、名前を持っていない名札。ウタとは、ちょうど裏返しだった。"},{"k":"n","t":"千歳さんが、空の台座の一つを、籠手でそっと撫でた。"},{"k":"d","t":"「ここにいた子たちは、どこへ行ったんだろうね」"},{"k":"n","t":"誰も答えなかった。白い珊瑚の雪が、アーケードの外で、音もなく降っていた。"},{"k":"break"},{"k":"n","t":"広場へ向かう途中、時計屋の前で、足が止まった。"},{"k":"n","t":"硝子の扉の向こうに、何十もの時計が掛かっていた。壁掛け時計。置き時計。鳩の出る小さな箱。どれも違う形をしているのに、針だけは、ぜんぶ同じ場所を指していた。"},{"k":"n","t":"十一時十四分。"},{"k":"n","t":"一つ残らず。"},{"k":"d","t":"「……ずれてる時計が、ひとつもないね」"},{"k":"n","t":"ノアが言った。"},{"k":"n","t":"僕は、その言葉を胸の中で繰り返した。ずれていない。ゆらいでいない。"},{"k":"n","t":"偽物の数字が、四回とも267だったことを思い出す。綺麗すぎる数字。この店の時計たちも、同じ顔をしていた。"},{"k":"n","t":"ショーケースの隅に、懐中時計が一つ、蓋をひらいて置かれていた。"},{"k":"n","t":"その文字盤だけが、白く抜けていた。針も、数字もない。三つの疑問符のように、そこだけ時刻のない色をしていた。"},{"k":"n","t":"ウタが、硝子に額をつけた。"},{"k":"d","t":"「あれだけ、まだ決まってないんだね」"},{"k":"n","t":"何が、とは訊けなかった。"},{"k":"break"},{"k":"n","t":"街の真ん中の広場へ出た。"},{"k":"n","t":"時計塔のある聖堂が、正面に立っていた。緑の珊瑚が、尖塔のてっぺんまで絡みついている。上から見たときより、ずっと大きい。"},{"k":"n","t":"針は、十一時十四分。"},{"k":"n","t":"近くで見ると、秒針だけが動いていた。"},{"k":"n","t":"一秒進んで、一秒戻る。進んで、戻る。十四分から、十五分へ。決して届かない、その手前で。"},{"k":"n","t":"時計が、終われずにいた。"},{"k":"n","t":"広場には、舞台が組まれていた。"},{"k":"n","t":"木の床。紅白の幕。左右に、打ち上げ筒が何十本も並んでいる。筒の口には、まだ火の入っていない花火が、丸く詰められたままだった。"},{"k":"n","t":"舞台の上に、横断幕が一枚。"},{"k":"n","t":"＿＿＿　最終夜イベント"},{"k":"n","t":"灯喰いの腹から出てきたチケットと、同じ書体だった。横画の終わりが、少しだけ丸い。夜の画面でも読めるように、ほんの少しだけ字間をあけた、明朝体。"},{"k":"n","t":"胸の奥の泡に、チケットの重みが戻ってきた。"},{"k":"n","t":"僕は、舞台を見上げた。"},{"k":"n","t":"設計者の目が、勝手に動く。花火の筒の並び。観客の立ち位置。幕の上がる方向。最後の台詞を、どの高さから言わせるか。"},{"k":"n","t":"ぜんぶ、分かった。"},{"k":"n","t":"分かってしまうことが、怖かった。"},{"k":"n","t":"見たことはない。そのはずだった。なのに、この舞台のどこに立てば花火がいちばん大きく見えるのか、僕の足は知っていた。ウタの足が台座の高さを知っていたように。"},{"k":"d","t":"「ルカくん」"},{"k":"n","t":"ノアが、隣に来ていた。"},{"k":"d","t":"「顔、また仕事の顔になってる」"},{"k":"d","t":"「……そうかもしれない」"},{"k":"d","t":"「楽しそうじゃないほうの、仕事の顔」"},{"k":"n","t":"ノアは、それ以上訊かなかった。紺のケープのフードを少しだけ下ろして、暗い茶色の髪を耳にかける。ランタンの白い炎が、僕の泡殻の膜に映って、小さく揺れた。"},{"k":"n","t":"その炎が、一瞬、ちらついた。"},{"k":"n","t":"ノアの輪郭ごと。"},{"k":"n","t":"僕が瞬きをしたときには、もう戻っていた。ノアは何も言わなかった。僕も、何も言わなかった。訊いても答えないことを、もう知っていた。"},{"k":"break"},{"k":"n","t":"視界の隅の時計が、【2:30】に変わった。"},{"k":"n","t":"カゲロウが、一拍、止まった。"},{"k":"d","t":"「――少し、静かすぎますね」"},{"k":"n","t":"ジウさんの声だった。"},{"k":"d","t":"「ここ、初めてです。三人とも、こんなに深くまでは」"},{"k":"n","t":"ジウさんは、交易帳をひらいて、何かを書きつけた。几帳面な楷書で。"},{"k":"d","t":"「この街の名前を、記しておきたいのですが」"},{"k":"n","t":"ペン先が、止まった。"},{"k":"d","t":"「……書けません」"},{"k":"n","t":"帳面の上に、白い跡が残っていた。三文字ぶんの、色のない白。"},{"k":"n","t":"インクは出ている。それなのに、街の名前を書こうとしたところだけ、紙が受けとらない。"},{"k":"d","t":"「名前が、ないのではないと思います」"},{"k":"n","t":"ジウさんは、静かに言った。"},{"k":"d","t":"「書かせてもらえないんです。誰かが、ここだけは、まだ書かないでほしいと」"},{"k":"n","t":"まだ、という言葉が、妙に耳に残った。"},{"k":"n","t":"千歳さんが、舞台の端に腰を下ろした。鎧が、木の床を軋ませる。"},{"k":"d","t":"「終わらなかった祭りの跡だね」"},{"k":"d","t":"「終わらなかった？」"},{"k":"d","t":"「花火が、ぜんぶ残ってるだろう。始まる前に、時間が止まったんだ」"},{"k":"n","t":"千歳さんは、兜の窓ごしに、動かない秒針を見上げた。"},{"k":"d","t":"「終わり損ねたもんは、海の底に溜まるんだよ。忘れられたもんは白くなるけど、終わり損ねたもんは、ずっと灯ったままさ」"},{"k":"n","t":"琥珀の窓。開店する直前の店。火の入らない花火。"},{"k":"n","t":"この街は、忘れられたのではない。"},{"k":"n","t":"終わらせてもらえなかったのだ。"},{"k":"break"},{"k":"n","t":"七年間、僕は世界の終わらせ方を作ってきた。"},{"k":"n","t":"閉じていく世界を、人が泣いて、笑って、見送れるように。最後の花火の順番を決め、最後の台詞の長さを測った。"},{"k":"n","t":"それは、終わる世界のためだと思っていた。"},{"k":"n","t":"でも、ほんとうは違ったのかもしれない。"},{"k":"n","t":"終わりは、残される側のためにある。見送った人が、明日も生きていけるように。ちゃんと終わったものだけが、ちゃんと思い出になれる。"},{"k":"n","t":"終わらなかったものは、思い出にさえなれない。"},{"k":"n","t":"ここで、灯りをつけたまま待ちつづける。"},{"k":"n","t":"誰を、待っているのだろう。"},{"k":"break"},{"k":"n","t":"舞台の中央に、演台があった。"},{"k":"n","t":"最後の台詞を言う人が立つ場所だ。設計図の上で、僕が何百回も印をつけてきた場所。"},{"k":"n","t":"演台の上に、紙が一枚、伏せて置かれていた。"},{"k":"n","t":"台本だった。"},{"k":"n","t":"表紙の題は、白く抜けていた。三文字ぶん。"},{"k":"n","t":"ページをめくる。花火の順番。住人たちの立ち位置。灯りを消していく順序。どれも、きちんと書いてある。"},{"k":"n","t":"最後のページだけが、空白だった。"},{"k":"s","t":"〈最後の台詞〉"},{"k":"n","t":"見出しだけがあって、その下に、何もない。"},{"k":"n","t":"僕のフォルダのどれにも、同じ名前のファイルがあった。いつも、そこだけは自分で書いた。"},{"k":"n","t":"空白の下の余白に、一行だけ、手書きの文字があった。"},{"k":"n","t":"インクではない。赤いペンで。"},{"k":"n","t":"右上がりの、急いだような字。"},{"k":"d","t":"『終わらせ方が、まだ甘い』"},{"k":"n","t":"指が、紙の上で止まった。"},{"k":"n","t":"ウタが、僕の袖をつかんだ。ノアのランタンが、紙を白く照らした。千歳さんが、何も言わずに立ちあがった。"},{"k":"n","t":"広場の時計塔で、秒針が、一秒進んで、一秒戻った。"},{"k":"n","t":"十一時十四分。"},{"k":"n","t":"十五分には、まだ届かない。"},{"k":"n","t":"誰かが、この続きを書くのを待っている。"}]},{"id":"ep14","act":null,"title":"第14話　灯台の夜、十九と二十七","paras":[{"k":"n","t":"十一時十四分の街から、僕たちは一度、上へ戻った。"},{"k":"n","t":"台本は、演台の上に伏せたまま置いてきた。持ち出せば、あの空白を自分のものにしてしまう気がした。"},{"k":"s","t":"【深度 -1,000m／灯会・灯台】"},{"k":"break"},{"k":"n","t":"灯台の灯りは、海の底でも、律儀に一周していた。"},{"k":"n","t":"白い光の帯が、群青をなでて、また戻ってくる。その周期を数えると、ちょうど十二秒だった。来ない船のために、正確な時間を守りつづけている。"},{"k":"n","t":"沈都の秒針とは、反対の誠実さだった。"},{"k":"n","t":"あちらは、進めないまま一秒を往復している。こちらは、誰も見ていないまま十二秒を回りつづけている。どちらも、待っていることに変わりはない。"},{"k":"n","t":"灯台の下の部屋で、知らない人が、盾を磨いていた。"},{"k":"n","t":"まだ若い。鎧の継ぎ目が新しく、磨く手つきだけが、妙に年季が入っている。"},{"k":"s","t":"【カイト　Lv 34　潜騎士】"},{"k":"d","t":"「あ、千歳さんの拾ってきた人だ」"},{"k":"n","t":"カイトくんは、盾を膝に立てたまま、ぺこりと頭を下げた。"},{"k":"d","t":"「留守番してました。沈都、どうでした」"},{"k":"d","t":"「時計が、止まってた」"},{"k":"d","t":"「やっぱり」"},{"k":"n","t":"カイトくんは、なぜかうれしそうにうなずいた。"},{"k":"d","t":"「僕も一度だけ、上から見たことがあるんです。千歳さんの輪の中から。降りる許可は、まだもらえなくて」"},{"k":"d","t":"「あんたは、まず自分の泡殻を守れるようになってからさ」"},{"k":"n","t":"千歳さんが、奥から言った。"},{"k":"d","t":"「守ってますよ。前に立ってれば、後ろの人は割れない」"},{"k":"d","t":"「前に立つ理由が、それだけじゃ足りないって言ってるんだよ」"},{"k":"n","t":"カイトくんは、少しだけ唇をとがらせた。それから、僕のほうを見た。"},{"k":"d","t":"「ルカさんは、なんで潜るんですか」"},{"k":"n","t":"答えに詰まった。死んだ人から荷物が届いたから、と言えば正確で、何も伝わらない。"},{"k":"d","t":"「名前を、探してる」"},{"k":"d","t":"「じゃあ、僕と似てます」"},{"k":"n","t":"カイトくんは、盾の表を、僕に向けた。磨きこまれた鉄の面に、僕の顔と、頭上の【？？？】が、ゆがんで映っていた。"},{"k":"d","t":"「僕、現実だと、誰の前にも立ったことがないんです。教室でも、家でも、いつも誰かの後ろで。だから、ここでは前に立つって決めた。盾の前に立つと、後ろにいる人の名前を、ぜんぶ覚えられるから」"},{"k":"d","t":"「名前を、覚える」"},{"k":"d","t":"「守った人の名前は、忘れないんです。不思議と」"},{"k":"n","t":"前に立つ理由。"},{"k":"n","t":"守るためではなく、覚えるため。カイトくんの言葉は、そう聞こえた。千歳さんが「足りない」と言ったのは、たぶん、そこではない。けれど僕には、その理由が少しまぶしかった。"},{"k":"break"},{"k":"n","t":"灯台の外の回廊で、千歳さんが、群青を眺めていた。"},{"k":"n","t":"僕が隣に立つと、千歳さんは、兜の窓を少しだけあけた。"},{"k":"d","t":"「カイトはね、初めて来た夜、泣いてたんだよ」"},{"k":"d","t":"「泣いて」"},{"k":"d","t":"「浅瀬で、三回割れてね。誰も待っててくれないと思ってたらしい。廃教会の長椅子に、自分の名前を刻もうとしてたのさ。自分で自分を待つつもりでね」"},{"k":"n","t":"千歳さんは、灯台の光が一周するのを、目で追った。"},{"k":"d","t":"「あたしが横に座ったら、やめた。それから、毎晩、誰かの前に立つようになった」"},{"k":"d","t":"「前に立つ理由の、足りないほうって」"},{"k":"d","t":"「教えないよ。あの子が、自分で見つけるもんさ」"},{"k":"n","t":"千歳さんは、笑った。それから、少しだけ声を落とした。"},{"k":"d","t":"「あんたもだよ、ルカ。あの台本の空白を、誰のために埋めるのか。それは、あんたが自分で見つけな」"},{"k":"n","t":"灯台の光が、また一周した。十二秒。"},{"k":"n","t":"僕は、その十二秒のあいだ、何も言えなかった。"},{"k":"break"},{"k":"n","t":"夜が更けて、ノアがランタンを提げて立ちあがった。"},{"k":"n","t":"紺のケープのフードを背中に落として、暗い茶色の髪を、指で耳にかけなおす。丸い眼鏡に、白い炎が二つ映っている。"},{"k":"n","t":"視界の隅の時計は、【2:12】。"},{"k":"d","t":"「上で、芯を整えてくるね。灯台の灯りの横でやると、きれいに切れるの」"},{"k":"n","t":"ノアの足音が、螺旋の階段を上っていった。"},{"k":"d","t":"「……ノアちゃん、十九やで」"},{"k":"n","t":"カゲロウが、ぽつりと言った。湊くんの声だった。"},{"k":"d","t":"「え」"},{"k":"d","t":"「知らんかった？　前に言うてたわ。誕生日は冬やて。僕の一個上や。受験せえへんで済むのはええなあ、って言うたら、笑とった」"},{"k":"n","t":"十九。"},{"k":"n","t":"僕より、八つ下か。"},{"k":"n","t":"七年前、僕が見本帳をめくって書体を選んでいた夜、ノアはまだ十二歳だったことになる。"},{"k":"n","t":"数字にすると、急に距離ができた。八という差は、Lvの差より、ずっと動かしようがなかった。"},{"k":"d","t":"「ルカ兄さんは、いくつなん」"},{"k":"d","t":"「二十七」"},{"k":"d","t":"「うわ、ほんまに兄さんや」"},{"k":"n","t":"湊くんは、けらけら笑った。"},{"k":"d","t":"「でもノアちゃん、ルカ兄さんのこと、年下みたいに扱うやん。危なっかしい弟、みたいな」"},{"k":"n","t":"否定できなかった。"},{"k":"n","t":"頭上で、灯台の灯りが一周した。その白い帯の中に、もう一つ、小さな白い炎が揺れているのが、階段の窓から見えた。琥珀ではない。この海で、あの色の灯りを持っているのは、ノアだけだ。"},{"k":"n","t":"僕はそれを、まだメモ帳の丸にしていない。丸にすれば、問いになってしまう。問いになれば、答えを探してしまう。"},{"k":"break"},{"k":"n","t":"カゲロウが、両手を水の中にひらいた。"},{"k":"d","t":"「ほな、地図や。僕が落ちる前に、忘れんうちに」"},{"k":"n","t":"泡が、ひとつ、ふくらんだ。"},{"k":"n","t":"その膜の内側に、街が映っていた。沈都の通り。アーケード。時計屋。広場と、聖堂と、舞台。上から見下ろした形のまま、小さく、正確に。"},{"k":"d","t":"「僕、覚えるのだけは得意やねん。単語帳、三冊目やし」"},{"k":"n","t":"泡の地図は、くるりと回った。銀灰色の前髪が、その光を受けて、淡く透けた。"},{"k":"n","t":"通りの数は、十一本。"},{"k":"n","t":"交差点の数は、二十三。"},{"k":"n","t":"そして、窓。泡の中の街にも、琥珀の窓が、点々と灯っていた。"},{"k":"d","t":"「なあ、ルカ兄さん」"},{"k":"n","t":"湊くんが、地図の一角を指さした。"},{"k":"d","t":"「ここ、住宅区や。ちゃんと見てへんけど、窓、えらい多いで」"},{"k":"n","t":"僕は、泡に顔を近づけた。"},{"k":"n","t":"窓が、多い。住む人の数にしては、多すぎるのかもしれない。あるいは、ちょうどなのかもしれない。"},{"k":"n","t":"数えなければ、分からない。"},{"k":"n","t":"視界の隅の時計が、【2:30】に変わった。"},{"k":"n","t":"カゲロウが、一拍、止まった。"},{"k":"d","t":"「――地図は、湊くんが残していってくれました」"},{"k":"n","t":"ジウさんの声だった。泡の地図は、消えずに回りつづけていた。"},{"k":"d","t":"「窓の数、気になりますね。わたしも、数えるのは好きです。帳面をつける仕事なので」"},{"k":"d","t":"「明日、数えに行こう」"},{"k":"d","t":"「全部、ですか」"},{"k":"d","t":"「数えるのが、いちばん早いことがあるんです」"},{"k":"d","t":"「……そうですね。急がないほうが、早いこともあります」"},{"k":"n","t":"カイトくんが、盾を背負って立ちあがった。"},{"k":"d","t":"「僕も行けますか」"},{"k":"n","t":"千歳さんが、奥で、ふう、と息をついた。"},{"k":"d","t":"「沈都の入口までだよ。そこから先は、あたしの輪の中」"},{"k":"d","t":"「はい！」"},{"k":"n","t":"階段から、ノアが降りてきた。芯を切りそろえたランタンの炎が、さっきより少しだけ背を伸ばしていた。"},{"k":"s","t":"〈パーティ：？？？／ノア／カゲロウ／千歳／ウタ／カイト〉"},{"k":"n","t":"パーティの欄に、名前がひとつ増えた。"},{"k":"break"},{"k":"n","t":"視界の隅の時計は、【3:38】。"},{"k":"d","t":"「そろそろだね」"},{"k":"n","t":"ノアは、いつもと同じ声で言った。"},{"k":"d","t":"「沈都のこと、明日また考えよう。ルカくん、今夜は顔が疲れてる」"},{"k":"d","t":"「ノアも」"},{"k":"d","t":"「私は、いつもこう」"},{"k":"n","t":"ノアは笑って、ランタンを胸に抱いた。"},{"k":"s","t":"【3:40】。"},{"k":"n","t":"ノアの輪郭が、ほどけるように薄くなって、消えた。落ちる、という言い方がいつも似合わないと思う。ノアは、落ちるのではなく、どこかへ帰っていく。"},{"k":"n","t":"白い炎も、ランタンごと、ノアと一緒に消えた。"},{"k":"n","t":"パーティの欄で、ノアの名前だけが、灰色になった。朝を待つように。"},{"k":"n","t":"灯台の光が、また一周した。十二秒。"},{"k":"n","t":"ウタが、ノアの座っていた窓際に、膝を抱えて座っていた。"},{"k":"d","t":"「ノア、また来る？」"},{"k":"d","t":"「来るよ。毎晩、来る」"},{"k":"d","t":"「毎晩」"},{"k":"n","t":"ウタは、その言葉を、泡貨みたいに両手で包んだ。"},{"k":"d","t":"「毎晩って、いつまで？」"},{"k":"n","t":"僕は、答えなかった。"},{"k":"n","t":"答えを、知らなかったから。"}]},{"id":"ep15","act":null,"title":"第15話　窓の数を数える","paras":[{"k":"n","t":"数えることは、考えることに似ている。"},{"k":"n","t":"似ているのではなく、同じなのかもしれない。数え終わるまで、人は結論を急がずにいられるから。"},{"k":"s","t":"【深度 -3,000m／沈都層・住宅区】"},{"k":"break"},{"k":"n","t":"住宅区の入口で、銛を担いだ人が待っていた。"},{"k":"n","t":"大きなゴーグルを額に押しあげて、僕たちを値踏みするように見る。ゴーグルのレンズには、細い目盛りが何本も刻まれていた。"},{"k":"s","t":"【ミナモ　Lv 41　銛撃士】"},{"k":"d","t":"「灯会の人？　千歳さんの輪の中に、新顔がいるって聞いた」"},{"k":"n","t":"僕は、自分の銛を少し持ちあげた。"},{"k":"d","t":"「同じ銛撃士です」"},{"k":"d","t":"「見れば分かる。構えが素人なのに、目だけ玄人」"},{"k":"n","t":"ミナモさんは、ゴーグルを下ろした。レンズの目盛りが、琥珀の窓の光を拾って、細く光る。"},{"k":"d","t":"「測距ゴーグル。遠くの的までの距離が、数字で出るの。私、数字がないと突けないんだ。勘で突く人、信用してない」"},{"k":"n","t":"初めて会う人に、こんなに好感を持ったのは久しぶりだった。"},{"k":"d","t":"「窓を、数えに来たんです」"},{"k":"d","t":"「窓？」"},{"k":"d","t":"「この区画の、灯っている窓の数と、家の数を」"},{"k":"n","t":"ミナモさんは、一拍だけ黙った。それから、ゴーグルの縁を指で叩いた。"},{"k":"d","t":"「いいね。手伝う。そういうの、好き」"},{"k":"n","t":"カイトくんが、入口で盾を立てた。ここから先へは来ない約束だ。"},{"k":"d","t":"「数え終わったら、教えてください。僕も、数字、聞きたいです」"},{"k":"break"},{"k":"n","t":"住宅区は、碁盤の目だった。"},{"k":"n","t":"カゲロウの泡の地図では、通りが十一本。そのうちの四本が、この区画を縦に貫いている。"},{"k":"n","t":"家は、どれも同じ形をしていた。二階建て。玄関の横に、小さな表札。表札は、どれも白く抜けていた。看板と同じ、三文字ぶんの白。"},{"k":"d","t":"「分担しよう」"},{"k":"n","t":"僕は言った。"},{"k":"d","t":"「ミナモさんは、窓を。ゴーグルで、二階まで正確に。僕は、表札を数えます。カゲロウは、地図に印をつけて。数え漏れがないように」"},{"k":"d","t":"「ウタは？」"},{"k":"d","t":"「ウタは、歌って」"},{"k":"d","t":"「なんで？」"},{"k":"d","t":"「歌の一巡りで、一軒。拍があると、数えるのが崩れない」"},{"k":"n","t":"ウタは、ふうん、と首をかしげて、それから六つの音を歌いはじめた。上がって、少し下がって、また上がる。"},{"k":"n","t":"その一巡りごとに、僕たちは一軒ずつ進んだ。"},{"k":"n","t":"表札、一。窓、三。"},{"k":"n","t":"表札、一。窓、三。"},{"k":"n","t":"ミナモさんの声が、拍の頭で正確に落ちてくる。ゴーグルの目盛りは、一度も読み違えない。"},{"k":"n","t":"百軒を越えたあたりで、千歳さんが、輪の縁で腰を下ろした。"},{"k":"d","t":"「気が長いねえ」"},{"k":"d","t":"「短いと、数え間違えるので」"},{"k":"d","t":"「あたしの若いころの漁協にも、あんたみたいなのがいたよ。網の目を、一つずつ数える人でね。みんなに笑われてたけど、網が破れるのは、いつもその人が先に見つけた」"},{"k":"break"},{"k":"n","t":"途中で、ミナモさんが、一度だけ足を止めた。"},{"k":"n","t":"ゴーグルを外して、右目だけを、手のひらで覆う。それから、左目だけを。"},{"k":"d","t":"「疲れました？」"},{"k":"d","t":"「ううん。確かめてるだけ」"},{"k":"n","t":"ミナモさんは、ゴーグルを戻した。"},{"k":"d","t":"「私ね、現実だと、片目がほとんど見えないの。子どものころの病気で。だから、距離が分からない。コップに水を注ぐのも、階段を下りるのも、ちょっとだけ下手」"},{"k":"n","t":"ゴーグルの目盛りが、琥珀の窓を、一つずつ拾っていく。"},{"k":"d","t":"「ここに来て、このゴーグルを見つけたとき、泣いたよ。距離が、数字で出るんだもの。十一メートル。四メートル。数字があれば、私は、ちゃんと届く」"},{"k":"d","t":"「だから、勘で突く人を、信用しない」"},{"k":"d","t":"「そう。勘は、見える人のものだから」"},{"k":"n","t":"ミナモさんは、少し笑った。"},{"k":"d","t":"「数字は、見えない人にも、同じように届く。それって、すごく優しいことだと思わない？」"},{"k":"n","t":"前の仕事で、数字を気持ちよく見せることばかり考えてきた。見えない人に届く数字のことを、僕は、考えたことがなかった。"},{"k":"n","t":"ウタの歌が、次の一巡りに入った。僕たちは、また一軒、進んだ。"},{"k":"break"},{"k":"n","t":"数え終わった。"},{"k":"n","t":"家は、百七軒。"},{"k":"n","t":"表札は、百七枚。ぜんぶ、白。"},{"k":"n","t":"灯っている窓は、三百二十二。"},{"k":"n","t":"ミナモさんが、ゴーグルを押しあげた。"},{"k":"d","t":"「三百二十二。間違いない。三回数えた」"},{"k":"n","t":"百七に、三を掛ける。三百二十一。"},{"k":"n","t":"一つ、多い。"},{"k":"d","t":"「どの家も、窓は三つずつ灯ってる」"},{"k":"n","t":"僕は、泡の地図に指を置いた。"},{"k":"d","t":"「一階の台所。二階の寝室。それから、玄関の上の、小さな部屋」"},{"k":"d","t":"「小さい部屋？」"},{"k":"d","t":"「ほかの二つは、住んでる人のための窓だと思う。料理をして、眠るための。でも、玄関の上の部屋だけは、通りに向けて灯ってる」"},{"k":"d","t":"「数えながら、何軒か、中を覗きました。ベッドが一つ。枕もとに、たたんだタオル。それから、どの家も同じ位置に、使われていない鍵が一本」"},{"k":"n","t":"ミナモさんが、黙って続きを待った。"},{"k":"d","t":"「客間です」"},{"k":"n","t":"口に出すと、論理がひとつずつ、正しい順番で並んだ。"},{"k":"n","t":"この街の家は、どれも、一人ぶんの客を迎える準備をしていた。百七軒が、百七人の客を。"},{"k":"n","t":"最終夜イベント。舞台。花火の筒。開店の直前の店。"},{"k":"d","t":"「この街は、自分の最後の夜に、誰かを招いていたんだ。外から来る人を。泊まって、最後の花火を見て、朝に帰っていく客を」"},{"k":"d","t":"「その客は」"},{"k":"d","t":"「来なかった」"},{"k":"n","t":"だから、客間の窓は、今も灯っている。"},{"k":"n","t":"鍵も、使われないまま、枕もとに置かれている。"},{"k":"d","t":"「……じゃあ、残りの一つは？」"},{"k":"n","t":"ミナモさんが言った。"},{"k":"n","t":"三百二十二から、三百二十一を引いた、一。"},{"k":"n","t":"カゲロウの泡の地図を回す。湊くんが、端っこの一軒を指さした。"},{"k":"d","t":"「ここや。路地の奥。表札が、ない」"},{"k":"n","t":"行ってみた。"},{"k":"n","t":"路地のいちばん奥に、小さな家が一軒、ほかの家から少し離れて建っていた。窓は一つだけ。灯っている。"},{"k":"n","t":"表札の場所には、何もなかった。白く抜けているのではない。表札そのものが、最初から取りつけられていなかった。"},{"k":"d","t":"「白いのと、ないのは、違うね」"},{"k":"n","t":"ノアの声がして、振り向いた。"},{"k":"n","t":"路地の入口に、ノアが立っていた。白い炎のランタンを提げて。今夜は、少し早く潜ってきたらしい。"},{"k":"d","t":"「白いのは、書いてあったものが消えたんでしょ。ないのは、最初から書かれてない」"},{"k":"n","t":"消された名前と、まだ書かれていない名前。"},{"k":"n","t":"頭上の【？？？】が、どちらなのか。僕にはまだ、分からなかった。"},{"k":"n","t":"ウタが、その家の窓を見上げていた。歌は、とうに止んでいる。"},{"k":"d","t":"「ここ、知らない」"},{"k":"n","t":"ウタは、小さく言った。"},{"k":"d","t":"「でも、ここの窓、わたしが見てたの。いつも、台座の上から」"},{"k":"n","t":"七つ目の台座の向きを、僕は思い出した。アーケードの入口。通りの奥。その延長線の先に、この路地がある。"},{"k":"n","t":"毎晩、七秒ごとに「ようこそ」を言いながら、あの子は、この窓を見ていたのだ。"},{"k":"n","t":"誰の家なのかも、知らないまま。"},{"k":"n","t":"ミナモさんが、ゴーグルを下ろして、窓までの距離を測った。"},{"k":"d","t":"「十一メートル。台座からだと、四百十二メートル」"},{"k":"n","t":"数字が、ちゃんと出た。"},{"k":"n","t":"この窓は、数えられる場所にある。それだけのことが、なぜか、救いのように思えた。"}]},{"id":"ep16","act":null,"title":"第16話　灯守の青年","paras":[{"k":"n","t":"浅瀬の廃教会では、破泡した者を、誰かが待っている。"},{"k":"n","t":"灯会の決まりだと、千歳さんは言っていた。割れた泡が、もう一度ふくらんで戻ってくるまで、長椅子に座って待つ。それだけ。"},{"k":"n","t":"だから、沈都にも廃教会があると聞いたとき、僕はそこにも、待つ人がいるのだと思った。"},{"k":"s","t":"【深度 -3,000m／沈都層・東の丘】"},{"k":"break"},{"k":"n","t":"教会は、街の東の丘に建っていた。"},{"k":"n","t":"屋根の半分が崩れ、そこから珊瑚の雪が、静かに降りこんでいる。祭壇の上には、琥珀の灯りが一つ。ほかの窓の灯りより少しだけ低く、少しだけ揺れていた。"},{"k":"n","t":"その灯りの前に、青年が一人、座っていた。"},{"k":"n","t":"白い麻の上着。手には、長い柄の燭台。消えかけた芯を、細い鋏で切りそろえている。"},{"k":"s","t":"【深民「トウヤ」　灯守】"},{"k":"n","t":"深民だった。泡殻を持たない、この海の住人。"},{"k":"d","t":"「お客さん、ですか」"},{"k":"n","t":"トウヤさんは、振り向かずに言った。"},{"k":"d","t":"「珍しいな。ここまで降りてくる人は、ほとんどいない」"},{"k":"d","t":"「灯りを、守ってるんですか」"},{"k":"d","t":"「守ってる、というほどでもないです。消えないように、芯を切ってるだけ」"},{"k":"n","t":"鋏が、ちょきん、と鳴った。炎が、少しだけ背を伸ばす。"},{"k":"d","t":"「長く燃やすと、芯が焦げて、炎が煤ける。だから、焦げたところを切る。少し短くなるかわりに、明るさが戻る」"},{"k":"n","t":"ノアが、ランタンを胸の前で、そっと持ちなおした。"},{"k":"d","t":"「私も、灯守なの」"},{"k":"d","t":"「そうみたいですね。……白い」"},{"k":"n","t":"トウヤさんは、初めて振り向いた。ノアの炎を見て、少しだけ目を細めた。"},{"k":"d","t":"「この街の灯りは、ぜんぶ琥珀です。白は、初めて見ました」"},{"k":"n","t":"ノアは、何も言わなかった。笑いもしなかった。"},{"k":"break"},{"k":"n","t":"教会の中には、長椅子が並んでいた。"},{"k":"n","t":"浅瀬の廃教会と、同じ形だった。背もたれの木に、小さな文字が、いくつも刻まれている。"},{"k":"n","t":"浅瀬の長椅子では、それは待っている相手の名前だった。割れた泡の名前を刻んで、その横に座る。戻ってきたら、名前の横に、小さな丸をつける。"},{"k":"n","t":"ここの長椅子にも、刻み跡はあった。"},{"k":"n","t":"けれど、文字ではなかった。"},{"k":"n","t":"どれも、短い線だった。一本、一本、きちんと同じ長さで。数えるための、正の字の、書きかけのような。"},{"k":"d","t":"「これは」"},{"k":"d","t":"「夜の数です」"},{"k":"n","t":"トウヤさんは、燭台を置いた。"},{"k":"d","t":"「僕の前の灯守が、刻んでいたそうです。一晩ごとに、一本。誰かを待つためじゃない。何晩、灯りが消えなかったかを数えるために」"},{"k":"d","t":"「誰も、待っていない？」"},{"k":"d","t":"「待つ人が、いないんです。ここで割れた人は、戻ってこない。ここは、浅瀬とは違う。割れたら、それで終わりです」"},{"k":"n","t":"千歳さんが、兜の奥で、低く息をのんだのが分かった。"},{"k":"d","t":"「戻らない、のかい」"},{"k":"d","t":"「戻りません。だから、待たない。待っても、来ないものを待つのは、灯守の仕事じゃない」"},{"k":"n","t":"トウヤさんの声は、乾いてはいなかった。ただ、静かだった。何度も自分に言い聞かせた言葉は、こういう静けさを帯びる。"},{"k":"d","t":"「じゃあ、どうして灯りを守るんですか」"},{"k":"n","t":"僕は訊いた。"},{"k":"d","t":"「待つ人がいないなら、誰のために」"},{"k":"n","t":"トウヤさんは、少し考えた。鋏を、指の上で一回転させた。"},{"k":"d","t":"「消えるのが、怖いからです。この灯りが消えたら、この街に、まだ夜が続いていることを、誰も知らなくなる」"},{"k":"n","t":"まだ、夜が続いている。"},{"k":"n","t":"十一時十四分の夜が。"},{"k":"break"},{"k":"n","t":"僕は、長椅子の刻み跡を、目で数えた。"},{"k":"n","t":"一本が、一晩。"},{"k":"n","t":"背もたれ一枚に、およそ三百六十本。長椅子が、十九脚。そのうち十六脚と半分が、刻み跡で埋まっていた。"},{"k":"n","t":"およそ、六千。"},{"k":"n","t":"割り算をする。六千を、三百六十五で。"},{"k":"n","t":"十六年と、少し。"},{"k":"d","t":"「……おかしい」"},{"k":"n","t":"思わず、声に出ていた。"},{"k":"d","t":"「この海の夜は、現実の夜とずれてる。ここでの一晩が、現実の一晩と同じとは限らない。でも、もし同じなら――」"},{"k":"n","t":"十六年前。"},{"k":"n","t":"七年前ではない。"},{"k":"n","t":"僕が書体を選んだのは、七年前だ。この街の最後の夜が、七年前のことなら、刻み跡は二千五百本くらいでなければならない。"},{"k":"d","t":"「夜が、速いんだよ」"},{"k":"n","t":"千歳さんが言った。"},{"k":"d","t":"「深いところほど、夜の数え方が速くなる。浅瀬でも、ときどき感じるだろう。一晩潜ってると、二晩も三晩も生きた気がするって」"},{"k":"n","t":"七年が、十六年ぶんの夜になる。二倍と少し。"},{"k":"n","t":"この街は、僕が知っているより、ずっと長く待っていたのだ。"},{"k":"n","t":"数字は、嘘をつかない。けれど、数字は、どこで数えたかによって違う顔をする。その違いを読み落とすのは、いつも数える側だ。"},{"k":"break"},{"k":"n","t":"千歳さんが、腰の鉤を外した。"},{"k":"n","t":"現実の海で、岩から貝を剥がすための、小さな鉄の鉤だと言っていた。ここでは、装備ではない。ただの、持ちもの。"},{"k":"d","t":"「一つ、いいかい」"},{"k":"n","t":"トウヤさんに、そう断ってから、千歳さんは、いちばん後ろの長椅子に腰を下ろした。刻み跡のない、まっさらな背もたれ。"},{"k":"n","t":"鉤の先で、木を削りはじめた。"},{"k":"n","t":"ゆっくり。一画ずつ。"},{"k":"n","t":"僕は、それを読まないようにした。読んではいけない気がした。けれど、最後の一画のあとで、千歳さんのほうから言った。"},{"k":"d","t":"「うちの人の名前さ」"},{"k":"n","t":"千歳さんは、刻んだ文字を、籠手の指でなぞった。"},{"k":"d","t":"「三十年前に、房総の海で上がってこなかった。網を見に出て、それっきり。船だけが、朝に浜へ戻ってきた」"},{"k":"n","t":"誰も、何も言わなかった。"},{"k":"d","t":"「あたしは、ずっと待ったよ。浜で。何年も。でも、待ってたのは、あの人じゃなかったんだね。あの人が上がってこなかったことを、あたしがちゃんと終わらせられる日を、待ってたんだ」"},{"k":"n","t":"千歳さんは、立ちあがった。"},{"k":"d","t":"「ここに刻んどけば、待つ人のいない教会にも、一人ぶん、待たれる名前がある。それで、いいだろう」"},{"k":"n","t":"トウヤさんは、長いあいだ、その名前を見ていた。"},{"k":"n","t":"それから、燭台を持って、その長椅子の横に立った。"},{"k":"d","t":"「この椅子の灯りは、僕が守ります」"},{"k":"d","t":"「待たなくていいよ。来ないから」"},{"k":"d","t":"「待ちません。でも、覚えておきます」"},{"k":"n","t":"千歳さんは、兜の奥で、少しだけ笑った。"},{"k":"d","t":"「それで、十分さ」"},{"k":"n","t":"芯をちょきんと切られて、祭壇の琥珀が、少しだけ明るくなった。"},{"k":"n","t":"割れたら、それで終わり。"},{"k":"n","t":"その言葉が、僕の胸の中で、泡にならずに残っていた。ここから先の海では、僕たちも、そうなのだ。"},{"k":"n","t":"ノアが、ランタンの白い炎を、長いあいだ見つめていた。"},{"k":"n","t":"待たれる名前と、待たれない名前。"},{"k":"n","t":"ノアは、その夜も3時40分ちょうどに落ちた。白い炎も、いつものように、ノアと一緒に消えた。"}]},{"id":"ep17","act":null,"title":"第17話　歌を継ぐ者","paras":[{"k":"n","t":"ウタの歌には、言葉がない。"},{"k":"n","t":"六つほどの音。上がって、少し下がって、また上がる。そして、終わりまで行かずに、途中でふっと消える。"},{"k":"n","t":"浅瀬で初めて聞いた夜から、僕はずっと、あれは未完成の歌なのだと思っていた。書きかけの、続きのある歌。"},{"k":"n","t":"沈都で、その続きを知っている人に会った。"},{"k":"s","t":"【深度 -3,000m／沈都層・水路】"},{"k":"break"},{"k":"n","t":"街の西側には、水路があった。"},{"k":"n","t":"海の底に、水路がある。おかしな話だけれど、そこだけ水の色が違った。群青の中を、もう少し澄んだ、硝子のような水が、ゆっくり流れている。"},{"k":"n","t":"その岸で、誰かが歌っていた。"},{"k":"n","t":"六つの音だった。"},{"k":"n","t":"ウタが、僕の袖をぎゅっとつかんだ。"},{"k":"n","t":"上がって、少し下がって、また上がる。ウタの歌と同じ旋律。けれど、ウタがいつも消えてしまうところで、その声は消えなかった。"},{"k":"n","t":"七つ目の音へ。八つ目へ。旋律は、ゆるやかに下りながら、まだ続いていく。"},{"k":"n","t":"岸に座っていたのは、長い髪を三つ編みにした深民の女性だった。膝の上に、貝殻を何枚も糸で綴った、帳面のようなものを載せている。"},{"k":"s","t":"【深民「シオネ」　歌継ぎ】"},{"k":"d","t":"「……あら」"},{"k":"n","t":"シオネさんは、歌をやめて、こちらを見た。それから、ウタを見て、目を丸くした。"},{"k":"d","t":"「案内役の子。まだ、いたの」"},{"k":"n","t":"ウタの指が、僕の袖の中で、冷たくなった。"},{"k":"d","t":"「わたし、ウタ」"},{"k":"d","t":"「ウタ」"},{"k":"n","t":"シオネさんは、その名前を、口の中で一度ころがした。"},{"k":"d","t":"「いい名前ね。歌の子に、歌の名前。誰がつけたの」"},{"k":"n","t":"ウタが、僕を見上げた。"},{"k":"d","t":"「ルカ」"},{"k":"d","t":"「そう」"},{"k":"n","t":"シオネさんは、僕を見て、少しだけ頭を下げた。"},{"k":"d","t":"「ありがとう。あの子たちには、番号しかなかったから」"},{"k":"break"},{"k":"d","t":"「この歌は、街の歌なの」"},{"k":"n","t":"シオネさんは、貝殻の帳面をひらいた。一枚ごとに、細い線が刻まれている。音の高さを、線の位置で記した、楽譜だった。"},{"k":"d","t":"「最後の夜に、街のみんなで歌うはずだった。案内役の子たちは、そのはじめの六つの音だけを、毎晩の練習で歌っていた。お客さんが来たときに、迎えの歌として」"},{"k":"d","t":"「続きは」"},{"k":"d","t":"「続きは、歌継ぎが持っている。私の前の人も、その前の人も」"},{"k":"n","t":"シオネさんは、楽譜を指でなぞった。"},{"k":"d","t":"「歌を、ぜんぶ一人に持たせないための決まりなの。はじめは案内役が、なかほどは歌継ぎが、終わりは、最後の夜に舞台で。三つに分けておけば、誰か一人が忘れても、歌は消えない」"},{"k":"n","t":"カゲロウの泡みたいだ、と思った。三人で一人。一つの体を、夜の向こうまで運ぶための分担。"},{"k":"d","t":"「歌ってもらえますか。続きを」"},{"k":"n","t":"シオネさんは、ウタを見た。"},{"k":"n","t":"ウタは、少し迷ってから、うなずいた。"},{"k":"n","t":"シオネさんが、六つの音を歌う。ウタが、それに声を重ねる。"},{"k":"n","t":"六つ目の音で、ウタの声が、いつものように、ふっと消えた。"},{"k":"n","t":"シオネさんの声だけが、続いた。"},{"k":"n","t":"そして、旋律の上に、言葉が乗った。"},{"k":"n","t":"ひかりの　つぶを　かぞえてる"},{"k":"n","t":"ひとつ　はじけて　ふたつ　うまれ"},{"k":"n","t":"なまえの　ない　みずの　そこで"},{"k":"n","t":"だれかが　まってる　あかりの　かず"},{"k":"n","t":"ウタの唇が、動いていた。声にはならない。けれど、言葉の形を、なぞっていた。知らないはずの言葉を、唇だけが覚えていた。台座の高さを、足が覚えていたように。"},{"k":"n","t":"はじけるから　うつくしい"},{"k":"n","t":"その一行で、僕の背中が、すっと冷えた。"},{"k":"n","t":"浅瀬で、泡貨を両手で包んで、ウタが言った言葉。どこで覚えたのか彼女自身も知らないようだった、あの言葉。"},{"k":"n","t":"この街の歌だったのだ。"},{"k":"n","t":"ウタは、自分が何を覚えているのかも知らないまま、この街の歌の一行だけを、ずっと胸に持っていた。"},{"k":"n","t":"いつか　だれかが　この　うたを　――"},{"k":"n","t":"そこで、シオネさんの声も、止まった。"},{"k":"n","t":"旋律の頂点の、手前で。"},{"k":"break"},{"k":"d","t":"「……ここまで」"},{"k":"n","t":"シオネさんは、楽譜を閉じた。"},{"k":"d","t":"「終わりは、知らないの」"},{"k":"d","t":"「知らない？」"},{"k":"d","t":"「終わりの音は、最後の夜に、舞台の上で、はじめて歌われるはずだった。だから、歌継ぎには渡されていない。楽譜にも、書いていない」"},{"k":"n","t":"シオネさんは、貝殻の最後の一枚を、僕に見せた。"},{"k":"n","t":"何も刻まれていなかった。"},{"k":"n","t":"白い貝殻。台本の〈最後の台詞〉と同じ、空白。"},{"k":"d","t":"「最後の夜は、来なかった。だから、終わりの音を知っている人は、この街に、一人もいない」"},{"k":"n","t":"僕は、その白い貝殻を見つめた。"},{"k":"n","t":"論理は、短い。"},{"k":"n","t":"歌は三つに分けられていた。はじめの六つの音。なかほどの言葉。終わりの音。"},{"k":"n","t":"はじめは、ウタが持っている。なかほどは、シオネさんが持っている。"},{"k":"n","t":"終わりは、誰も持っていない。"},{"k":"n","t":"誰も持っていないものは、忘れられることもない。忘れられないものは、白くもならない。この歌は、白くなって消えることもできずに、頂点の手前で、ずっと止まっている。"},{"k":"n","t":"十一時十四分の秒針と、同じように。"},{"k":"d","t":"「シオネさんは、終わりの音を、知りたいと思いますか」"},{"k":"n","t":"僕は訊いた。"},{"k":"n","t":"シオネさんは、しばらく水路の流れを見ていた。"},{"k":"d","t":"「知りたい、とは思わないわ」"},{"k":"d","t":"「どうして」"},{"k":"d","t":"「知ったら、歌い終わってしまうもの」"},{"k":"n","t":"それは、怖がる声ではなかった。もっと静かな、何かを手放せない人の声だった。"},{"k":"d","t":"「歌い終わったら、歌は思い出になる。思い出になったら、もう、毎晩歌わなくてよくなる。私は、毎晩歌うのが、仕事なの。歌継ぎじゃなくなったら、私は、何になるのかしら」"},{"k":"n","t":"誰も、答えられなかった。"},{"k":"n","t":"ノアが、ランタンを少しだけ持ちあげた。白い炎が、水路の澄んだ水に映って、ゆらいだ。"},{"k":"d","t":"「終わったあとも、歌は、誰かの中に残るよ」"},{"k":"n","t":"ノアは言った。"},{"k":"d","t":"「ちゃんと終わった歌は、ちゃんと覚えていられる。私は、そっちのほうが、うらやましい」"},{"k":"n","t":"シオネさんは、ノアを見た。それから、白い炎を見た。"},{"k":"d","t":"「あなた、変わった灯りね」"},{"k":"d","t":"「よく言われる」"},{"k":"n","t":"ノアは笑った。いつもと同じ笑い方で。"},{"k":"break"},{"k":"n","t":"帰り道、ウタは何度も、六つの音を歌った。"},{"k":"n","t":"六つ目のところで、ふっと消える。それから、唇だけで、言葉をなぞる。"},{"k":"n","t":"ひかりの　つぶを　かぞえてる――。"},{"k":"d","t":"「ルカ」"},{"k":"d","t":"「うん」"},{"k":"d","t":"「わたし、はじめのところしか、持ってないんだね」"},{"k":"d","t":"「うん」"},{"k":"d","t":"「でも、はじめがないと、なかほども、終わりも、来ないんだよね」"},{"k":"n","t":"僕は、足を止めた。"},{"k":"n","t":"ウタは、自分の胸に、透きとおった手を当てていた。"},{"k":"d","t":"「だったら、わたし、ちゃんと持ってる」"},{"k":"n","t":"はじめの六つの音。毎晩、七秒ごとに繰り返された「ようこそ」と同じ、迎えるための歌。"},{"k":"n","t":"来なかった客を、迎えつづけた歌。"},{"k":"n","t":"それでも、はじめがなければ、何も始まらない。"},{"k":"d","t":"「……うん。ちゃんと、持ってる」"},{"k":"n","t":"僕は、メモ帳をひらいた。"},{"k":"n","t":"○　歌は三つに分けられている。終わりの音は、誰も持っていない。"},{"k":"n","t":"その丸の横に、もう一つ、小さく書きくわえた。"},{"k":"n","t":"○　台本の〈最後の台詞〉も、誰も持っていない。"},{"k":"n","t":"二つの丸を、線でつないだ。"},{"k":"n","t":"同じ空白だった。"}]},{"id":"ep18","act":null,"title":"第18話　珊瑚は何を覚えているか","paras":[{"k":"n","t":"この海の珊瑚は、記憶から育つ。"},{"k":"n","t":"灯台で、誰かがそう話していた。誰かが覚えていることが、海水に溶けて、少しずつ石灰の枝になる。だから、浅瀬の珊瑚は翠に光り、忘れられたものの上では、白く崩れて雪になる。"},{"k":"n","t":"では、終わらなかったものの上では、何が育つのだろう。"},{"k":"s","t":"【深度 -3,000m／沈都層・南の庭園】"},{"k":"break"},{"k":"n","t":"南の庭園は、白かった。"},{"k":"n","t":"花壇も、噴水も、ベンチも、すべてが白い珊瑚に覆われていた。枝の先が、触れる前から崩れて、粉のように舞う。街のほかの場所に灯っている琥珀は、ここだけ、一つもない。"},{"k":"n","t":"その真ん中で、小柄な深民が、両手を地面に当てていた。"},{"k":"n","t":"手のひらの下から、細い緑の芽が、一本だけ伸びかけている。"},{"k":"s","t":"【深民「スイ」　珊瑚術士】"},{"k":"d","t":"「静かにしてね」"},{"k":"n","t":"スイさんは、顔を上げずに言った。"},{"k":"d","t":"「今、聞いてるところだから」"},{"k":"n","t":"僕たちは、息をひそめた。泡殻の中の呼吸の音さえ、うるさい気がした。"},{"k":"n","t":"緑の芽は、指一本ぶんだけ伸びて、そこで止まった。先端が、ゆっくり白くなる。"},{"k":"d","t":"「……だめか」"},{"k":"n","t":"スイさんは、ようやく手を離した。"},{"k":"d","t":"「ここの珊瑚は、白すぎる。覚えていた人が、もう誰も覚えていないから」"},{"k":"d","t":"「白い珊瑚から、記憶を戻せるんですか」"},{"k":"d","t":"「戻せはしないわ。聞くだけ」"},{"k":"n","t":"スイさんは、立ちあがって、膝の粉を払った。"},{"k":"d","t":"「珊瑚は、育ったときの記憶を、枝の芯に持ってる。白くなっても、芯だけは残る。そこに、生きた珊瑚を一本、継ぎ木するの。継いだ枝が白くなるまでの、ほんの少しのあいだだけ、芯の記憶が、声になる」"},{"k":"d","t":"「どのくらい」"},{"k":"d","t":"「長くて、七秒」"},{"k":"n","t":"七秒。"},{"k":"n","t":"ウタの「ようこそ」の間と、同じ長さだった。"},{"k":"break"},{"k":"d","t":"「手伝えることは、ありますか」"},{"k":"n","t":"僕は訊いた。"},{"k":"d","t":"「あるわよ。生きた珊瑚には、生きた記憶が要る。ここの白に負けないくらい、濃いのが」"},{"k":"n","t":"スイさんは、僕たちの顔を、一人ずつ見た。"},{"k":"d","t":"「誰か、この街のことを、何か覚えていない？　ほんの少しでいい。色でも、形でも」"},{"k":"n","t":"沈黙があった。"},{"k":"n","t":"この街のことを、覚えている人。"},{"k":"n","t":"ウタは、足が台座の高さを覚えている。シオネさんは、歌のなかほどを覚えている。"},{"k":"n","t":"そして、僕は。"},{"k":"d","t":"「書体を」"},{"k":"n","t":"言葉が、先に出た。"},{"k":"d","t":"「この街のチケットと、横断幕の書体を、僕は覚えています。七年前に、僕が選んだ。見本帳を、何十冊もめくって」"},{"k":"n","t":"スイさんは、まっすぐに僕を見た。"},{"k":"d","t":"「それは、濃いわね」"},{"k":"n","t":"スイさんの手が、僕の手首に触れた。冷たくはなかった。深民の手は、泡殻ごしに、少しだけ温かい。"},{"k":"d","t":"「思い出して。できるだけ、細かく」"},{"k":"n","t":"僕は、目を閉じた。"},{"k":"n","t":"横画の終わりが、少しだけ丸い。払いが、水に溶けるように細くなる。夜の画面でも読めるように、ほんの少しだけ字間をあけた。"},{"k":"n","t":"その夜の、机の上の、冷めたコーヒー。モニターに映った試し刷り。後ろから覗きこんで、赤ペンで丸をつけた、誰かの手。"},{"k":"n","t":"――これにしなさい。夜に読む字だから。"},{"k":"n","t":"あの声。"},{"k":"n","t":"目をあけたとき、スイさんの手のひらの下から、緑の芽が、勢いよく伸びあがっていた。"},{"k":"d","t":"「今」"},{"k":"n","t":"スイさんが、芽を白い枝の芯に押しあてた。"},{"k":"break"},{"k":"n","t":"音が、した。"},{"k":"n","t":"大勢の人の、ざわめき。"},{"k":"n","t":"広場の方角から。何百人もの、楽しげな、少し浮かれた声。屋台の呼びこみ。子どもの笑い声。木の床を走る足音。"},{"k":"d","t":"『――まもなく、最終夜イベントを開始します』"},{"k":"n","t":"放送の声だった。若い女性の声。少しだけ、緊張している。"},{"k":"d","t":"『本日は、＿＿＿へお越しいただき、ありがとうございます。十一時十五分より、花火の打ち上げを行います。お客様は、広場の――』"},{"k":"n","t":"街の名前のところだけ、音が抜けていた。そこだけ、無音の空白が、三拍ぶん。"},{"k":"n","t":"ざわめきの中に、ひとつだけ、近くの声があった。"},{"k":"d","t":"『ねえ、まだ？』"},{"k":"n","t":"子どもの声だった。"},{"k":"d","t":"『まだよ。もうすぐ。あと一分』"},{"k":"n","t":"大人の声が答えた。"},{"k":"n","t":"あと一分。"},{"k":"n","t":"十一時十四分。"},{"k":"d","t":"『――お知らせします』"},{"k":"n","t":"放送の声が、変わった。さっきと同じ人の声なのに、調子がまるで違った。原稿を、読みあげている声。"},{"k":"d","t":"『本日の――』"},{"k":"n","t":"そこで、緑の枝が、白くなった。"},{"k":"n","t":"七秒。"},{"k":"n","t":"声は、ぷつりと途切れた。"},{"k":"n","t":"庭園に、また、何の音もなくなった。珊瑚の雪だけが、さっきより少し多く、降っていた。"},{"k":"break"},{"k":"n","t":"誰も、すぐには口をきかなかった。"},{"k":"n","t":"最初に動いたのは、ウタだった。白い珊瑚に覆われたベンチに近づいて、その表面に、そっと手を置いた。"},{"k":"d","t":"「ここ、座ってた」"},{"k":"d","t":"「誰が？」"},{"k":"d","t":"「わかんない。でも、あの声の子、ここに座ってた気がする。足が、とどかなくて、ぶらぶらさせて」"},{"k":"n","t":"僕は、いま聞いた声と、住宅区の客間のことを、頭の中で並べなおした。"},{"k":"n","t":"最終夜イベントは、始まる直前だった。客は、いた。少なくとも、広場の周りには、何百人もの声があった。"},{"k":"n","t":"では、住宅区の客間は。百七軒の、灯ったままの窓は。"},{"k":"n","t":"泊まる客は、来なかった。"},{"k":"n","t":"つまり、あの夜、人々は集まった。最後の花火を見るために。そして、花火が上がる一分前に、放送が変わった。"},{"k":"d","t":"「本日の」"},{"k":"n","t":"ミナモさんが、ゴーグルの奥で、その言葉を繰り返した。"},{"k":"d","t":"「本日の、何」"},{"k":"d","t":"「たぶん」"},{"k":"n","t":"僕は、言いかけて、やめた。"},{"k":"n","t":"設計者の耳には、その続きが分かった。原稿を読む声。急に変わった調子。「お知らせします」と「本日の」の順番。何百回も、自分で文面を直してきた種類の放送だった。"},{"k":"n","t":"けれど、それを口に出すのは、まだ早かった。推論には、もう一つ、確かめなければならない前提が残っていた。"},{"k":"n","t":"あれが、誰の判断だったのか。"},{"k":"d","t":"「名前は」"},{"k":"n","t":"スイさんが言った。"},{"k":"d","t":"「名前は、聞こえなかったわね。街の名前のところだけ、あそこでも、白かった」"},{"k":"n","t":"珊瑚の記憶の中でさえ、この街の名前は、白く抜けていた。"},{"k":"n","t":"忘れられたからではない。"},{"k":"n","t":"最後の夜に、誰かが、その名前を持ち去ったのだ。"},{"k":"break"},{"k":"n","t":"帰る前に、スイさんが、緑の芽の残りを、僕の手のひらに乗せた。"},{"k":"n","t":"小指の先ほどの、小さな枝。まだ、白くなっていない。"},{"k":"d","t":"「あなたの記憶で育った枝よ。持っていきなさい」"},{"k":"d","t":"「どうして」"},{"k":"d","t":"「この街で、緑の珊瑚を育てられたのは、あなたが初めてだから」"},{"k":"n","t":"スイさんは、白い庭園を見渡した。"},{"k":"d","t":"「覚えている人がいれば、珊瑚は育つ。この街に足りないのは、灯りじゃない。覚えている人なの」"},{"k":"n","t":"小さな枝は、僕の手の中で、かすかに翠に光った。"},{"k":"n","t":"その光を見ながら、僕は、あの赤ペンの手のことを考えた。"},{"k":"n","t":"――夜に読む字だから。"},{"k":"n","t":"七年前、僕の肩ごしに丸をつけた、右上がりの字の人。"},{"k":"n","t":"あの人は、この街の最後の夜を、知っていたのだ。"},{"k":"s","t":"【LEVEL UP!】×3　Lv 22 → Lv 25"},{"k":"n","t":"PRS 300 → 330"},{"k":"n","t":"白い庭園の縁で、遅れて、ファンファーレが鳴った。戦ってもいないのに。"},{"k":"n","t":"思い出すことも、この海では、経験になるらしい。"}]},{"id":"ep19","act":null,"title":"第19話　引き揚げ屋","paras":[{"k":"n","t":"広場の時計塔に、鎖がかかっていた。"},{"k":"n","t":"太い、黒い鎖だった。尖塔の珊瑚をかき分けて、鐘楼の柱に何重にも巻きつけてある。鎖の先は、頭上の群青へまっすぐ伸びて、見えなくなっていた。"},{"k":"n","t":"上に、何かがいる。"},{"k":"s","t":"【深度 -3,000m／沈都層・中央広場】"},{"k":"break"},{"k":"d","t":"「下がって」"},{"k":"n","t":"千歳さんが、盾を前に出した。カイトくんも、反射的に、その横に並んだ。"},{"k":"n","t":"鎖を伝って、誰かが降りてきた。"},{"k":"n","t":"黒い潜水服。背中に、銛を三本。腕に、見たことのない紋章の腕章をつけている。錨の形を、四角い枠で囲んだ印。"},{"k":"s","t":"【ジン　Lv 58　投銛手】"},{"k":"s","t":"〈所属：ディープサルベージ〉"},{"k":"d","t":"「お、先客か」"},{"k":"n","t":"ジンさんは、石畳に降り立つと、首を鳴らした。"},{"k":"d","t":"「灯会の人たちだろ。悪いね、ここ、今日から作業区域なんだ」"},{"k":"d","t":"「作業？」"},{"k":"d","t":"「引き揚げだよ。この時計塔、まるごと上に持っていく」"},{"k":"n","t":"ジンさんは、親指で鎖を示した。"},{"k":"d","t":"「上に、うちの母船がいる。浮力の泡を百二十個、吊ってきた。この深さの建物一つなら、ひと晩で浅瀬まで上がる」"},{"k":"d","t":"「上げて、どうするんですか」"},{"k":"d","t":"「売るんだよ」"},{"k":"n","t":"あっけらかんとした声だった。"},{"k":"d","t":"「終わったゲームの建物は、この海の底に、いくらでも沈んでる。誰のものでもないから、拾ったもんの勝ちだ。古い時計塔は人気でね。浅瀬の観光地に建てると、客が集まる」"},{"k":"d","t":"「この街は、終わってない」"},{"k":"n","t":"僕の声は、思ったより強く出た。"},{"k":"d","t":"「止まってるだけだ」"},{"k":"n","t":"ジンさんは、一瞬だけ、僕の頭上の【？？？】を見た。それから、肩をすくめた。"},{"k":"d","t":"「止まってるのと、終わってるのと、何が違うんだ。誰も住んでない。誰も来ない。灯りだけついてる。ほっといたら、そのうち白くなって、雪になって消える。それなら、今のうちに上げてやったほうが、時計塔だって幸せだろ」"},{"k":"break"},{"k":"d","t":"「ジン。話は、私がする」"},{"k":"n","t":"鎖の上から、もう一人、降りてきた。"},{"k":"n","t":"背の高い女性だった。白に近い灰色の潜水服。髪は短く切りそろえていて、耳に、細い銀の測量器をかけている。片手に持った板状の端末には、時計塔の図面が、青い線で浮かんでいた。"},{"k":"s","t":"【白波レイ　Lv 63　建築士】"},{"k":"s","t":"〈所属：ディープサルベージ　主任建築家〉"},{"k":"n","t":"レイさんは、まず広場を見渡した。舞台。打ち上げ筒。演台。横断幕。それから、時計塔の針を。"},{"k":"n","t":"十一時十四分。"},{"k":"n","t":"その目の動き方を、僕は知っていた。"},{"k":"n","t":"設計者の目だった。"},{"k":"n","t":"図面と実物を、一つずつ照らし合わせていく目。ずれがないか。崩れているところはないか。そして、自分が引いた線が、まだ正しく立っているか。"},{"k":"d","t":"「よく、もってる」"},{"k":"n","t":"レイさんは、小さく言った。"},{"k":"d","t":"「七年も。思ったより、ずっと」"},{"k":"d","t":"「この街を、知ってるんですか」"},{"k":"n","t":"レイさんは、初めて僕を見た。"},{"k":"n","t":"頭上の【？？？】を見て、それから、僕の顔を見た。図面を確かめるときと、同じ目で。"},{"k":"d","t":"「知ってる。この時計塔を引いたのは、私だから」"},{"k":"n","t":"広場の空気が、変わった。"},{"k":"d","t":"「主任建築家、と書いてあるでしょう。七年前も、同じ肩書きだった。会社は違うけれど」"},{"k":"n","t":"レイさんは、端末の図面を、僕のほうへ向けた。"},{"k":"n","t":"青い線の、時計塔。その足もとに、小さな文字で、設計者の名前が並んでいる。"},{"k":"n","t":"白波レイ。"},{"k":"n","t":"その下に、もう一つの名前があった。"},{"k":"n","t":"白く、抜けていた。"},{"k":"n","t":"三文字ぶんではない。四文字ぶん。"},{"k":"n","t":"その横に、役職だけが読めた。"},{"k":"s","t":"〈最終夜イベント　演出〉"},{"k":"n","t":"僕の指が、勝手に動いて、その白をなぞろうとした。"},{"k":"break"},{"k":"d","t":"「あなたが、ここに来るとは思わなかった」"},{"k":"n","t":"レイさんは、端末を下ろした。"},{"k":"d","t":"「いえ、違うわね。来るかもしれないとは、思っていた。あの人が、あなたに何か送ったと聞いたから」"},{"k":"d","t":"「あの人」"},{"k":"d","t":"「あなたの先生よ」"},{"k":"n","t":"澪さん。"},{"k":"n","t":"名前は、レイさんの口から出なかった。出なかったことで、かえって、はっきりした。"},{"k":"d","t":"「先生と、一緒に仕事をしていたんですか」"},{"k":"d","t":"「この街の最後の夜を、三人で作っていた。私が建物を。あの人が、物語を。それから、入ったばかりの子が一人、書体と、文字の間を」"},{"k":"n","t":"レイさんは、僕の顔から目を離さなかった。"},{"k":"d","t":"「覚えていないのね」"},{"k":"d","t":"「……書体のことは、覚えています」"},{"k":"d","t":"「それだけ？」"},{"k":"d","t":"「それだけです」"},{"k":"n","t":"レイさんは、長い息をついた。泡殻の膜が、少しだけ震えた。"},{"k":"d","t":"「そう。じゃあ、あなたの中でも、この街の名前は白いのね」"},{"k":"n","t":"ジンさんが、退屈そうに鎖を揺らした。"},{"k":"d","t":"「レイさん、昔話はいいから。作業、始めていい？」"},{"k":"d","t":"「待って」"},{"k":"n","t":"レイさんは、時計塔を見上げた。"},{"k":"n","t":"秒針が、一秒進んで、一秒戻る。"},{"k":"d","t":"「この塔は、上げる。それは、決めたこと。資産として回収する。会社の判断で、私の判断でもある」"},{"k":"d","t":"「どうして」"},{"k":"n","t":"僕は訊いた。"},{"k":"d","t":"「あなたが引いた塔でしょう。どうして、売れるんですか」"},{"k":"d","t":"「私が引いたから、よ」"},{"k":"n","t":"レイさんの声は、少しも揺れなかった。"},{"k":"d","t":"「終わらなかった世界を、このまま海の底に置いておくのは、設計者の怠慢よ。誰も来ない街に、灯りだけをつけて、待たせつづける。それは、優しさじゃない。私は、この街に、別の使い道をあげたい。浅瀬で、人が集まる場所として。それも、一つの続きでしょう」"},{"k":"n","t":"論理は、通っていた。"},{"k":"n","t":"通っていることが、苦しかった。"},{"k":"n","t":"僕は、反論を探した。止まっているものと、終わっているものは違う。この街は、まだ待っている。誰かが、最後の台詞を書くのを。"},{"k":"n","t":"けれど、それを言うなら、問われるのは、僕のほうだった。"},{"k":"n","t":"では、お前が書くのか、と。"},{"k":"n","t":"七年間、世界の終わらせ方を作ってきた。閉じていく世界に、最後の夜を設計してきた。それなのに、この街の最後の夜を、僕は覚えてさえいない。"},{"k":"n","t":"終わりの設計者として、僕は、彼女に反論する資格を持っていなかった。"},{"k":"break"},{"k":"n","t":"ウタが、僕の前に出た。"},{"k":"n","t":"小さな体で、両手を広げる。#07の台座の上で、何千回も繰り返した、あの角度で。"},{"k":"d","t":"「ようこそ」"},{"k":"n","t":"ウタは言った。"},{"k":"n","t":"七秒の型ではなかった。首をかしげずに、まっすぐ、レイさんを見て。"},{"k":"d","t":"「ようこそ。でも、これは持っていかないで」"},{"k":"n","t":"レイさんの目が、初めて揺れた。"},{"k":"d","t":"「……案内役の、七番」"},{"k":"d","t":"「ウタ」"},{"k":"d","t":"「ウタ」"},{"k":"n","t":"レイさんは、その名前を繰り返した。シオネさんがしたのと、同じように。"},{"k":"n","t":"それから、ジンさんのほうを向いた。"},{"k":"d","t":"「作業は、明日の夜に延ばす」"},{"k":"d","t":"「えっ、なんで」"},{"k":"d","t":"「浮力の泡の点検。一つ、怪しいのがあった」"},{"k":"d","t":"「点検は済んだって、さっき――」"},{"k":"d","t":"「あった」"},{"k":"n","t":"ジンさんは、何か言いかけて、やめた。それから、僕たちのほうを見て、ため息をついた。"},{"k":"d","t":"「明日の夜、また来るよ。邪魔するなら、そのときは本気で突く」"},{"k":"n","t":"ジンさんは、鎖を伝って、上へ戻っていった。"},{"k":"n","t":"レイさんは、まだ残っていた。"},{"k":"n","t":"端末の図面を閉じる前に、もう一度、あの白く抜けた四文字の欄を見た。"},{"k":"d","t":"「ねえ」"},{"k":"n","t":"レイさんは、背を向けたまま言った。"},{"k":"d","t":"「あの夜、放送の原稿を書いたのが、誰だったか。あなたは、覚えている？」"},{"k":"n","t":"僕は、答えられなかった。"},{"k":"n","t":"レイさんは、それ以上は訊かずに、鎖を上っていった。"},{"k":"n","t":"時計塔の秒針が、一秒進んで、一秒戻った。"},{"k":"n","t":"鎖は、まだ、尖塔に巻きついたままだった。"}]},{"id":"ep20","act":null,"title":"第20話　十一時十五分の手前で","paras":[{"k":"n","t":"次の夜、鎖は二本に増えていた。"},{"k":"n","t":"尖塔の珊瑚が、鎖の重みでぎしぎしと鳴っている。頭上の群青の奥で、浮力の泡が、いくつも鈍く光っていた。百二十個。ジンさんの言ったとおりの数だった。"},{"k":"n","t":"数字は、嘘をつかない。百二十個をそろえてきたのなら、今夜は本当に上げるつもりなのだ。"},{"k":"s","t":"【深度 -3,000m／沈都層・中央広場】"},{"k":"break"},{"k":"n","t":"広場には、灯会の全員がいた。"},{"k":"n","t":"千歳さんと、カイトくん。ミナモさんは、少し離れた屋根の上で、ゴーグルの目盛りを合わせている。ノアは舞台の袖で、ランタンを下げていた。カゲロウが、交易帳を閉じた。ジウさんの声だった。"},{"k":"d","t":"「では、始めましょうか」"},{"k":"n","t":"ウタは、演台の前に立っていた。台本は、まだ、伏せたままそこにある。"},{"k":"n","t":"トウヤさんも、シオネさんも、スイさんも、広場の縁に来ていた。深民は泡殻を持たない。戦いには、加われない。それでも、来ていた。"},{"k":"n","t":"時計塔の鎖の根もとに、ジンさんが立っていた。銛を一本、肩に担いで。"},{"k":"d","t":"「来ると思った」"},{"k":"d","t":"「来ないと思ってた？」"},{"k":"d","t":"「いや。来てほしかった、かもな」"},{"k":"n","t":"ジンさんは、銛を構えた。"},{"k":"d","t":"「悪いけど、仕事だ。邪魔するなら、突く」"},{"k":"s","t":"【ジン　HP 4,210】"},{"k":"break"},{"k":"n","t":"ジンさんの銛は、重かった。"},{"k":"n","t":"一投ごとに、水を押しのける音がする。投げた銛は、背中の鎖に繋がっていて、刺さるたびに巻き取られて戻ってくる。"},{"k":"d","t":"「312」"},{"k":"n","t":"千歳さんの盾が、正面で受けた。盾の表に、赤い数字が弾ける。"},{"k":"n","t":"千歳さんの盾が、続けて二度鳴った。"},{"k":"d","t":"「297」「330」"},{"k":"n","t":"数字が、ゆらいでいる。"},{"k":"n","t":"僕は、それを確かめて、少しだけ安心した。この人は、写しではない。本物の誰かが、どこかの夜に眠って、この銛を投げている。"},{"k":"d","t":"「カイト、左を」"},{"k":"d","t":"「はい！」"},{"k":"n","t":"カイトくんが、ウタの前に滑りこんだ。盾を立てる。ジンさんの二投目が、その表に当たって、金属の悲鳴をあげた。"},{"k":"d","t":"「284」"},{"k":"n","t":"カイトくんの体が、半歩、後ろへ押された。けれど、倒れなかった。"},{"k":"d","t":"「ウタさん、下がってて！」"},{"k":"d","t":"「ウタでいい」"},{"k":"d","t":"「ウタ！」"},{"k":"n","t":"カイトくんが叫ぶ。守った人の名前を、彼はまた一つ覚えた。"},{"k":"n","t":"ミナモさんの銛が、屋根の上から一直線に飛んだ。ゴーグルの目盛りどおりの距離。ジンさんの肩の留め具に、正確に。"},{"k":"d","t":"「418」"},{"k":"n","t":"カゲロウの泡が、ジンさんの視界の前でふくらんだ。"},{"k":"n","t":"僕は、その陰から突いた。"},{"k":"d","t":"「251」「276」"},{"k":"s","t":"【ジン　HP 2,863】"},{"k":"d","t":"「やるな」"},{"k":"n","t":"ジンさんが、笑った。"},{"k":"d","t":"「でもさ、これ、勝っても意味ないぜ。俺を割っても、上の母船は残る。泡も、鎖も。明日、別の誰かが来るだけだ」"},{"k":"n","t":"その通りだった。"},{"k":"n","t":"戦いは、問いを解決しない。問いを、先に延ばすだけだ。"},{"k":"break"},{"k":"d","t":"「もういいわ、ジン」"},{"k":"n","t":"舞台の上から、声がした。"},{"k":"n","t":"白波レイさんが、演台の横に立っていた。いつのまに降りてきたのか、誰も気づかなかった。"},{"k":"d","t":"「レイさん、まだ半分も――」"},{"k":"d","t":"「いいの」"},{"k":"n","t":"レイさんは、演台の上の台本を、手に取らずに見下ろしていた。"},{"k":"d","t":"「ねえ。昨日、ジンが訊いたことに、答えて」"},{"k":"n","t":"僕に言っていた。"},{"k":"d","t":"「止まっているものと、終わっているものの違い。あなたは、答えられなかった。放送の原稿のことも。でも、まずはこっちから。今夜は――」"},{"k":"n","t":"僕は、銛を下ろした。"},{"k":"n","t":"広場の縁を見た。トウヤさん。シオネさん。スイさん。ウタ。"},{"k":"n","t":"戦いに加われないのに、ここに来ている人たち。"},{"k":"n","t":"前提を、一つずつ置く。"},{"k":"d","t":"「終わりは、残される側のためにある」"},{"k":"n","t":"声に出すと、それは、七年かけて考えてきたことの、いちばん短い形になった。"},{"k":"d","t":"「終わる世界のためじゃない。見送った人が、明日も生きていけるように、終わりはある。ちゃんと終わったものだけが、ちゃんと思い出になれる」"},{"k":"d","t":"「それで」"},{"k":"d","t":"「この時計塔を浅瀬に上げたら、それは、上げた人たちのための続きになる。浅瀬で、新しいお客さんが、古い時計を見て喜ぶ。それは、悪いことじゃない」"},{"k":"n","t":"レイさんは、黙って聞いていた。"},{"k":"d","t":"「でも、それは、この街に残された人たちのための終わりじゃない。灯りの芯を切りつづけている人。歌のなかほどを、毎晩歌っている人。白い珊瑚の声を聞いている人。来なかった客を、七秒ごとに迎えつづけた子」"},{"k":"n","t":"ウタが、僕を見ていた。"},{"k":"d","t":"「この人たちには、まだ、終わりが来ていない。塔を上げても、ここに残る。終わりのないまま、塔のない広場で、待ちつづける」"},{"k":"n","t":"論理は、そこで一つの結論に着いた。"},{"k":"d","t":"「止まっているものは、持ち去っても、終わらない。終わらせなければ、終わらない」"},{"k":"n","t":"広場が、静かになった。"},{"k":"n","t":"ジンさんが、銛の穂先を、石畳に下ろしていた。"},{"k":"break"},{"k":"n","t":"レイさんは、長いあいだ、僕を見ていた。"},{"k":"n","t":"それから、端末をひらいて、何かを打ちこんだ。"},{"k":"n","t":"頭上で、鎖が、鳴った。"},{"k":"n","t":"二本の鎖が、尖塔の珊瑚から、ゆっくりとほどけていく。浮力の泡が、ひとつ、またひとつ、群青の上へ遠ざかっていった。"},{"k":"d","t":"「レイさん！」"},{"k":"d","t":"「作業は、中止。会社には、私から言う」"},{"k":"n","t":"中止。"},{"k":"n","t":"その言葉を、レイさんは、ひどく慎重に口にした。何度も使ったことのある言葉を、初めて使う人のように。"},{"k":"d","t":"「勘違いしないで。あなたに負けたわけじゃない。あなたの論理が、正しいかどうかも、まだ分からない」"},{"k":"n","t":"レイさんは、演台の台本を見下ろした。"},{"k":"d","t":"「ただ、あなたの論理には、続きがある。終わらせなければ、終わらない。なら、誰が終わらせるの」"},{"k":"n","t":"答えは、分かっていた。分かっていて、言えなかった。"},{"k":"n","t":"レイさんは、台本を、指先で、僕のほうへ少しだけずらした。"},{"k":"d","t":"「書けるのは、あなただけ」"},{"k":"n","t":"レイさんは、それだけ言って、背を向けた。"},{"k":"n","t":"鎖の残りを伝って、上へ。ジンさんが、肩をすくめて、そのあとに続いた。"},{"k":"d","t":"「次は、仕事抜きで会おうぜ」"},{"k":"n","t":"ジンさんは、去り際に、一度だけ振り向いた。"},{"k":"d","t":"「あんたの数字、ゆらいでて、よかった」"},{"k":"break"},{"k":"n","t":"広場に、灯会の全員と、深民の人たちが残った。"},{"k":"n","t":"演台の上の台本は、僕のほうへ、指一本ぶんだけ、近づいていた。"},{"k":"n","t":"最後のページを、僕は開かなかった。開けば、空白が見える。見れば、何かを書かなければならなくなる。"},{"k":"n","t":"まだ、書けなかった。"},{"k":"n","t":"何を書けばいいのか、分からないからではない。誰のために書くのか、まだ全部は分かっていないからだ。"},{"k":"n","t":"ノアが、舞台の袖から、僕の隣に来た。"},{"k":"d","t":"「ルカくん、顔」"},{"k":"d","t":"「うん」"},{"k":"d","t":"「今の顔は、楽しそうじゃないけど、逃げてない顔」"},{"k":"n","t":"ノアは、ランタンを掲げた。白い炎が、時計塔の文字盤を照らした。"},{"k":"n","t":"視界の隅の時計は、【3:31】。"},{"k":"n","t":"秒針が、一秒進んで、一秒戻る。"},{"k":"n","t":"進んで、戻る。"},{"k":"n","t":"そのとき、秒針が、止まった。"},{"k":"n","t":"進みも、戻りもせずに。"},{"k":"n","t":"十一時十四分の、最後の一秒のところで。"},{"k":"n","t":"そして、一度だけ、深く震えた。"},{"k":"n","t":"鐘楼の奥で、錆びた歯車が、何かを思い出そうとするように、低く鳴った。広場の打ち上げ筒が、いっせいに、かすかに応えた。"},{"k":"n","t":"ウタが、息をのんだ。"},{"k":"n","t":"トウヤさんの燭台の炎が、背を伸ばした。シオネさんが、六つの音を、口の中だけで歌った。スイさんの白い庭園の方角で、珊瑚の雪が、一瞬だけ止んだ。"},{"k":"n","t":"それから、秒針は、また一秒戻った。"},{"k":"n","t":"十一時十四分。"},{"k":"n","t":"十五分には、まだ届かない。"},{"k":"n","t":"けれど、届こうとしたのだ。一度だけ。"},{"k":"n","t":"僕は、台本の上に、そっと手を置いた。開かずに。"},{"k":"n","t":"この街の、最後の夜の、続き。"},{"k":"n","t":"それを書く人間は、もう、決まっていた。"}]}];
